INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_acid_splash','Acid Splash',0,'evocation','action','ranged',60,1,1,0,null,'instantaneous',0,0,'You create an acidic bubble at a point within range, where it explodes in a 5-foot-radius Sphere. Each creature in that Sphere must succeed on a Dexterity saving throw or take 1d6 Acid damage. Cantrip Upgrade: The damage increases by 1d6 when you reach levels 5 (2d6), 11 (3d6), and 17 (4d6).','d6',1,'acid',1,2,3,4,null,'dex',null,'area','sphere',5,1,1);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_aid','Aid',2,'abjuration','action','ranged',30,1,1,1,'a strip of white cloth','8_hours',0,0,'Choose up to three creatures within range. Each target''s Hit Point maximum and current Hit Points increase by 5 for the duration. Using a Higher-Level Spell Slot: Each target''s Hit Points increase by 5 for each spell slot level above 2.',null,null,null,1,null,null,null,null,null,null,'multiple',null,null,0,0);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_alarm','Alarm',1,'abjuration','1_minute','ranged',30,1,1,1,'a bell and silver wire','8_hours',0,1,'You set an alarm against intrusion. Choose a door, a window, or an area within range no larger than a 20-foot Cube. Until the spell ends, an alarm alerts you whenever a creature touches or enters the warded area. You can designate creatures that won''t set off the alarm and choose whether the alarm is audible (handbell sound for 10 seconds within 60 feet) or mental (a ping if you are within 1 mile, which awakens you if asleep).',null,null,null,0,null,null,null,null,null,null,'single',null,null,0,1);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_alter_self','Alter Self',2,'transmutation','action','self',null,1,1,0,null,'concentration_1_hour',1,0,'You alter your physical form. Choose one option for the duration, and you can use a Magic action to replace it with another: Aquatic Adaptation (breathe underwater, gain Swim Speed equal to your Speed); Change Appearance (alter your looks, height, weight, features — can''t change size or basic shape); Natural Weapons (grow claws, fangs, horns, or hooves dealing 1d6 damage of appropriate type using your spellcasting modifier).',null,null,null,0,null,null,null,null,null,null,'self',null,null,0,1);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_animal_friendship','Animal Friendship',1,'enchantment','action','ranged',30,1,1,1,'a morsel of food','24_hours',0,0,'Target a Beast you can see within range. The target must succeed on a Wisdom saving throw or have the Charmed condition for the duration. If you or one of your allies deals damage to the target, the spell ends. Using a Higher-Level Spell Slot: You can target one additional Beast for each spell slot level above 1.',null,null,null,1,null,null,null,null,'wis',null,'single',null,null,0,0);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_animal_messenger','Animal Messenger',2,'enchantment','action','ranged',30,1,1,1,'a morsel of food','24_hours',0,1,'A Tiny Beast you can see within range must succeed on a Charisma saving throw or attempt to deliver a message for you (CR 0 beasts automatically fail). You specify a location, a recipient matching a general description, and a message of up to twenty-five words. The Beast travels up to 25 miles per 24 hours (50 if flying). If it doesn''t reach its destination before the spell ends, the message is lost and the Beast returns. Using a Higher-Level Spell Slot: Duration increases by 48 hours per slot level above 2.',null,null,null,1,null,null,null,null,'cha',null,'single',null,null,0,0);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_animal_shapes','Animal Shapes',8,'transmutation','action','ranged',30,1,1,0,null,'24_hours',0,0,'Choose any number of willing creatures you can see within range. Each target shape-shifts into a Large or smaller Beast of your choice with CR 4 or lower. You can choose a different form for each target. Targets retain their creature type, Hit Points, Hit Dice, alignment, ability to communicate, and INT/WIS/CHA scores. Equipment melds into the new form and can''t be used. Targets gain Temporary HP equal to the HP of their first Beast form. The transformation lasts for the duration or until the target ends it as a Bonus Action.',null,null,null,0,null,null,null,null,null,null,'multiple',null,null,0,0);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_animate_dead','Animate Dead',3,'necromancy','1_minute','ranged',10,1,1,1,'a drop of blood, a piece of flesh, and a pinch of bone dust','instantaneous',0,0,'Choose a pile of bones or a corpse of a Medium or Small Humanoid within range. It becomes a Skeleton (bones) or Zombie (corpse). You can command it as a Bonus Action if within 60 feet. It obeys for 24 hours; you must recast on it before that period ends to maintain control, which also reasserts control over up to four creatures animated by this spell. Using a Higher-Level Spell Slot: Animate or reassert control over two additional Undead per slot level above 3.',null,null,null,1,null,null,null,null,null,null,'single',null,null,0,1);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_animate_objects','Animate Objects',5,'transmutation','action','ranged',120,1,1,0,null,'concentration_1_minute',1,0,'Choose nonmagical, non-Gargantuan objects within range not worn, carried, or fixed. Maximum objects equals your spellcasting modifier (Medium or smaller = 1, Large = 2, Huge = 3). Each becomes an animated Construct ally under your control. You can Bonus Action command any within 500 feet. When one drops to 0 HP it reverts to object form. Using a Higher-Level Spell Slot: Slam damage increases by 1d4 (Medium/smaller), 1d6 (Large), or 1d12 (Huge) per slot level above 5.',null,null,'force',1,null,null,null,1,null,null,'multiple',null,null,0,1);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_antilife_shell','Antilife Shell',5,'abjuration','action','self',null,1,1,0,null,'concentration_1_hour',1,0,'An aura extends from you in a 10-foot Emanation for the duration. The aura prevents creatures other than Constructs and Undead from passing or reaching through it. Affected creatures can still cast spells or make attacks with Ranged or Reach weapons through the barrier. If you move so that an affected creature is forced to pass through the barrier, the spell ends.',null,null,null,0,null,null,null,null,null,null,'self','emanation',10,0,0);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_antimagic_field','Antimagic Field',8,'abjuration','action','self',null,1,1,1,'iron filings','concentration_1_hour',1,0,'An aura of antimagic surrounds you in a 10-foot Emanation. No one can cast spells, take Magic actions, or create magical effects inside the aura, and those things can''t target or affect anything inside it. Magic items don''t function inside. No teleportation or planar travel into or out of it. Ongoing spells (except from Artifacts or deities) are suppressed inside. Dispel Magic has no effect on the aura.',null,null,null,0,null,null,null,null,null,null,'self','emanation',10,0,1);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_antipathy_sympathy','Antipathy/Sympathy',8,'enchantment','1_hour','ranged',60,1,1,1,'a mix of vinegar and honey','10_days',0,0,'Choose antipathy or sympathy and target one Huge-or-smaller creature or object. Specify a creature kind. When such a creature comes within 120 feet it makes a WIS save. On fail — Antipathy: Frightened, must flee by safest route; Sympathy: Charmed, must approach by safest route and can''t move away if within 5 feet. If creature ends its turn 120+ feet away, it repeats the save; success ends the effect and grants 1-minute immunity.',null,null,null,0,null,null,null,null,'wis',null,'single',null,null,0,1);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_arcane_eye','Arcane Eye',4,'divination','action','ranged',30,1,1,1,'a bit of bat fur','concentration_1_hour',1,0,'You create an Invisible, invulnerable eye within range that hovers for the duration. You mentally receive visual information from the eye, which can see in every direction and has Darkvision 30 feet. As a Bonus Action, you can move the eye up to 30 feet in any direction. A solid barrier blocks its movement, but it can pass through openings as small as 1 inch in diameter.',null,null,null,0,null,null,null,null,null,null,'self',null,null,0,1);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_arcane_gate','Arcane Gate',6,'conjuration','action','ranged',500,1,1,0,null,'concentration_10_minutes',1,0,'You create two linked circular portals in two Large unoccupied spaces on the ground you can see — one within range, one within 10 feet of you. Each portal is a two-dimensional glowing ring filled with mist that blocks sight. Anything entering the open side of one portal exits from the open side of the other. As a Bonus Action, you can change the facing of the open sides.',null,null,null,0,null,null,null,null,null,null,'self',null,null,0,1);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_arcane_lock','Arcane Lock',2,'abjuration','action','touch',null,1,1,1,'gold dust worth 25+ GP, which the spell consumes','until_dispelled',0,0,'You touch a closed door, window, gate, container, or hatch and magically lock it. This lock can''t be opened by any nonmagical means. You and any creatures you designate when you cast the spell can open and close it despite the lock. You can also set a password that, when spoken within 5 feet, unlocks it for 1 minute.',null,null,null,0,null,null,null,null,null,null,'single',null,null,0,1);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_arcane_vigor','Arcane Vigor',2,'abjuration','bonus_action','self',null,1,1,0,null,'instantaneous',0,0,'You tap into your life force to heal yourself. Roll one or two of your unexpended Hit Point Dice and regain Hit Points equal to the roll''s total plus your spellcasting ability modifier. Those dice are then expended. Using a Higher-Level Spell Slot: The number of Hit Dice you can roll increases by one for each slot level above 2.',null,null,null,1,null,null,null,null,null,null,'self',null,null,1,1);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_armor_of_agathys','Armor of Agathys',1,'abjuration','bonus_action','self',null,1,1,1,'a shard of blue glass','1_hour',0,0,'Protective magical frost surrounds you. You gain 5 Temporary Hit Points. If a creature hits you with a melee attack roll before the spell ends, the creature takes 5 Cold damage. The spell ends early if you have no Temporary Hit Points. Using a Higher-Level Spell Slot: The Temporary Hit Points and Cold damage both increase by 5 for each slot level above 1.',null,null,'cold',1,null,null,null,null,null,null,'self',null,null,0,0);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_arms_of_hadar','Arms of Hadar',1,'conjuration','action','self',null,1,1,0,null,'instantaneous',0,0,'Invoking Hadar, you cause tendrils to erupt from yourself. Each creature in a 10-foot Emanation makes a Strength saving throw. On a failed save, a target takes 2d6 Necrotic damage and can''t take Reactions until the start of its next turn. On a successful save, a target takes half as much damage only. Using a Higher-Level Spell Slot: The damage increases by 1d6 for each slot level above 1.','d6',2,'necrotic',1,null,null,null,1,'str',null,'area','emanation',10,0,0);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_astral_projection','Astral Projection',9,'necromancy','1_hour','ranged',10,1,1,1,'for each target: one jacinth worth 1,000+ GP and one silver bar worth 100+ GP, all consumed','until_dispelled',0,0,'You and up to eight willing creatures within range project astral bodies into the Astral Plane. Each target''s body is left in suspended animation (Unconscious, no aging, no food/air needed). Astral forms replicate statistics and possessions but have a silvery cord; if cut, both body and astral form die. Astral forms can travel the Astral Plane. If an astral form leaves that plane, the body follows via the cord. Damage to one form doesn''t affect the other. Spell ends for a target at 0 HP or by Magic action dismissal.',null,null,null,0,null,null,null,null,null,null,'multiple',null,null,0,1);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_augury','Augury',2,'divination','1_minute','self',null,1,1,1,'specially marked sticks, bones, cards, or other divinatory tokens worth 25+ GP','instantaneous',0,1,'You receive an omen about the results of a course of action you plan to take within the next 30 minutes: Weal (good), Woe (bad), Weal and Woe (both), or Indifference (neither). The spell doesn''t account for circumstances that might change the results. If cast more than once before a Long Rest, there is a cumulative 25% chance per casting after the first that you get no answer.',null,null,null,0,null,null,null,null,null,null,'self',null,null,0,1);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_aura_of_life','Aura of Life',4,'abjuration','action','self',null,1,0,0,null,'concentration_10_minutes',1,0,'An aura radiates from you in a 30-foot Emanation for the duration. While in the aura, you and your allies have Resistance to Necrotic damage, and your Hit Point maximums can''t be reduced. If an ally with 0 Hit Points starts its turn in the aura, that ally regains 1 Hit Point.',null,null,null,0,null,null,null,null,null,null,'self','emanation',30,0,0);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_aura_of_purity','Aura of Purity',4,'abjuration','action','self',null,1,0,0,null,'concentration_10_minutes',1,0,'An aura radiates from you in a 30-foot Emanation for the duration. While in the aura, you and your allies have Resistance to Poison damage and Advantage on saving throws to avoid or end effects that include the Blinded, Charmed, Deafened, Frightened, Paralyzed, Poisoned, or Stunned condition.',null,null,null,0,null,null,null,null,null,null,'self','emanation',30,0,0);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_aura_of_vitality','Aura of Vitality',3,'abjuration','action','self',null,1,0,0,null,'concentration_1_minute',1,0,'An aura radiates from you in a 30-foot Emanation for the duration. When you create the aura and at the start of each of your turns while it persists, you can restore 2d6 Hit Points to one creature in it.',null,null,null,0,null,null,null,null,null,null,'self','emanation',30,0,0);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_awaken','Awaken',5,'transmutation','8_hours','touch',null,1,1,1,'an agate worth 1,000+ GP, which the spell consumes','instantaneous',0,0,'You touch a Beast or Plant creature with Intelligence 3 or less, or a natural plant that isn''t a creature. The target gains Intelligence 10 and can speak one language you know. A natural plant becomes a Plant creature and gains mobility and human-like senses. The awakened target has the Charmed condition for 30 days or until you or allies damage it. When that ends, the creature chooses its attitude toward you.',null,null,null,0,null,null,null,null,null,null,'single',null,null,0,0);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_bane','Bane',1,'enchantment','action','ranged',30,1,1,1,'a drop of blood','concentration_1_minute',1,0,'Up to three creatures of your choice that you can see within range must each make a Charisma saving throw. Whenever a target that fails this save makes an attack roll or a saving throw before the spell ends, the target must subtract 1d4 from the attack roll or save. Using a Higher-Level Spell Slot: You can target one additional creature for each slot level above 1.',null,null,null,1,null,null,null,1,'cha',null,'multiple',null,null,1,0);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_banishing_smite','Banishing Smite',5,'conjuration','bonus_action','self',null,1,0,0,null,'concentration_1_minute',1,0,'The target hit by the attack roll takes an extra 5d10 Force damage. If the attack reduces the target to 50 Hit Points or fewer, the target must succeed on a Charisma saving throw or be transported to a harmless demiplane for the duration with the Incapacitated condition. When the spell ends, the target reappears in the space it left or nearest unoccupied space.','d10',5,'force',0,null,null,null,null,'cha',null,'single',null,null,0,0);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_banishment','Banishment',4,'abjuration','action','ranged',30,1,1,1,'a pentacle','concentration_1_minute',1,0,'One creature you can see within range must succeed on a Charisma saving throw or be transported to a harmless demiplane for the duration with the Incapacitated condition. When the spell ends, it reappears in the space it left or nearest unoccupied space. If the target is an Aberration, Celestial, Elemental, Fey, or Fiend and the spell lasts 1 minute, it doesn''t return — it is instead transported to a random location on an associated plane. Using a Higher-Level Spell Slot: Target one additional creature per slot level above 4.',null,null,null,1,null,null,null,1,'cha',null,'single',null,null,1,1);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_barkskin','Barkskin',2,'transmutation','bonus_action','touch',null,1,1,1,'a handful of bark','1_hour',0,0,'You touch a willing creature. Until the spell ends, the target''s skin assumes a bark-like appearance, and the target has an Armor Class of 17 if its AC is lower than that.',null,null,null,0,null,null,null,null,null,null,'single',null,null,1,0);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_beacon_of_hope','Beacon of Hope',3,'abjuration','action','ranged',30,1,1,0,null,'concentration_1_minute',1,0,'Choose any number of creatures within range. For the duration, each target has Advantage on Wisdom saving throws and Death Saving Throws and regains the maximum number of Hit Points possible from any healing.',null,null,null,0,null,null,null,null,null,null,'multiple',null,null,0,0);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_beast_sense','Beast Sense',2,'divination','action','touch',null,0,1,0,null,'concentration_1_hour',1,1,'You touch a willing Beast. For the duration, you can perceive through the Beast''s senses as well as your own. When perceiving through the Beast''s senses, you benefit from any special senses it has.',null,null,null,0,null,null,null,null,null,null,'single',null,null,0,0);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_befuddlement','Befuddlement',8,'enchantment','action','ranged',150,1,1,1,'a key ring with no keys','instantaneous',0,0,'You blast the mind of a creature you can see within range. The target makes an Intelligence saving throw. On a failed save, it takes 10d12 Psychic damage and can''t cast spells or take the Magic action. Every 30 days the target repeats the save, ending the effect on a success. Greater Restoration, Heal, or Wish can also end it. On a successful save, the target takes half damage only.','d12',10,'psychic',0,null,null,null,null,'int',null,'single',null,null,1,1);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_bestow_curse','Bestow Curse',3,'necromancy','action','touch',null,1,1,0,null,'concentration_1_minute',1,0,'You touch a creature, which must succeed on a Wisdom saving throw or become cursed. Choose one effect: Disadvantage on checks and saves with one ability; Disadvantage on attack rolls against you; must WIS save at start of each turn or Dodge; or take extra 1d8 Necrotic when you deal damage to it. Using a Higher-Level Spell Slot: Level 4 = up to 10 minutes; Level 5-6 = 8 hours, no concentration; Level 7-8 = 24 hours, no concentration; Level 9 = until dispelled.','d8',1,'necrotic',1,null,null,null,null,'wis',null,'single',null,null,1,1);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_bigbys_hand','Bigby''s Hand',5,'evocation','action','ranged',120,1,1,1,'an eggshell and a glove','concentration_1_minute',1,0,'You create a Large hand of shimmering magical energy (AC 20, HP equal to your max HP). As a Bonus Action each turn, move it up to 60 feet and choose one effect: Clenched Fist (melee spell attack, 5d8 Force); Forceful Hand (STR save or pushed 5 ft + 5x spellcasting modifier); Grasping Hand (DEX save or Grappled, Bonus Action to crush for 4d6 + spellcasting modifier Bludgeoning); Interposing Hand (Half Cover for you, Difficult Terrain for enemies). Using a Higher-Level Spell Slot: Clenched Fist +2d8, Grasping Hand +2d6 per slot level above 5.','d8',5,'force',1,null,null,null,2,null,'melee_spell','single',null,null,1,1);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_blade_barrier','Blade Barrier',6,'evocation','action','ranged',90,1,1,0,null,'concentration_10_minutes',1,0,'You create a wall of whirling magical blades within range. Choose a straight wall up to 100 ft long, 20 ft high, and 5 ft thick, or a ringed wall up to 60 ft in diameter, 20 ft high, and 5 ft thick. The wall provides Three-Quarters Cover and is Difficult Terrain. Any creature in the wall''s space makes a DEX save, taking 6d10 Force damage on a failure or half on a success. A creature also makes this save when it enters the wall or ends its turn there (once per turn).','d10',6,'force',0,null,null,null,null,'dex',null,'area','wall',null,0,0);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_blade_ward','Blade Ward',0,'abjuration','action','self',null,1,1,0,null,'concentration_1_minute',1,0,'Whenever a creature makes an attack roll against you before the spell ends, the attacker subtracts 1d4 from the attack roll.',null,null,null,0,null,null,null,null,null,null,'self',null,null,1,1);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_bless','Bless',1,'enchantment','action','ranged',30,1,1,1,'a Holy Symbol worth 5+ GP','concentration_1_minute',1,0,'You bless up to three creatures within range. Whenever a target makes an attack roll or a saving throw before the spell ends, the target adds 1d4 to the attack roll or save. Using a Higher-Level Spell Slot: You can target one additional creature for each slot level above 1.',null,null,null,1,null,null,null,1,null,null,'multiple',null,null,0,0);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_blight','Blight',4,'necromancy','action','ranged',30,1,1,0,null,'instantaneous',0,0,'A creature you can see within range makes a Constitution saving throw, taking 8d8 Necrotic damage on a failed save or half on a successful one. A Plant creature automatically fails the save. Alternatively, target a nonmagical plant that isn''t a creature — it simply withers and dies. Using a Higher-Level Spell Slot: The damage increases by 1d8 for each slot level above 4.','d8',8,'necrotic',1,null,null,null,1,'con',null,'single',null,null,1,1);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_blinding_smite','Blinding Smite',3,'evocation','bonus_action','self',null,1,0,0,null,'1_minute',0,0,'The target hit by the strike takes an extra 3d8 Radiant damage, and the target has the Blinded condition until the spell ends. At the end of each of its turns, the Blinded target makes a Constitution saving throw, ending the spell on itself on a success. Using a Higher-Level Spell Slot: The extra damage increases by 1d8 for each slot level above 3.','d8',3,'radiant',1,null,null,null,1,'con',null,'single',null,null,0,0);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_blindness_deafness','Blindness/Deafness',2,'transmutation','action','ranged',120,1,0,0,null,'1_minute',0,0,'One creature you can see within range must succeed on a Constitution saving throw, or it has the Blinded or Deafened condition (your choice) for the duration. At the end of each of its turns, the target repeats the save, ending the spell on itself on a success. Using a Higher-Level Spell Slot: You can target one additional creature for each slot level above 2.',null,null,null,1,null,null,null,1,'con',null,'single',null,null,1,1);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_blink','Blink',3,'transmutation','action','self',null,1,1,0,null,'1_minute',0,0,'Roll 1d6 at the end of each of your turns. On a 4-6, you vanish to the Ethereal Plane until the start of your next turn, where you can perceive your original plane in gray shades up to 60 feet but can only affect or be affected by other Ethereal creatures. You return to an unoccupied space within 10 feet of where you left, or the nearest unoccupied space.',null,null,null,0,null,null,null,null,null,null,'self',null,null,0,1);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_blur','Blur',2,'illusion','action','self',null,1,0,0,null,'concentration_1_minute',1,0,'Your body becomes blurred. For the duration, any creature has Disadvantage on attack rolls against you. An attacker is immune to this effect if it perceives you with Blindsight or Truesight.',null,null,null,0,null,null,null,null,null,null,'self',null,null,1,1);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_burning_hands','Burning Hands',1,'evocation','action','self',null,1,1,0,null,'instantaneous',0,0,'A thin sheet of flames shoots forth from you. Each creature in a 15-foot Cone makes a Dexterity saving throw, taking 3d6 Fire damage on a failed save or half as much on a successful one. Flammable objects in the Cone that aren''t being worn or carried start burning. Using a Higher-Level Spell Slot: The damage increases by 1d6 for each slot level above 1.','d6',3,'fire',1,null,null,null,1,'dex',null,'area','cone',15,1,1);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_call_lightning','Call Lightning',3,'conjuration','action','ranged',120,1,1,0,null,'concentration_10_minutes',1,0,'A storm cloud appears above you in a 10-foot-tall, 60-foot-radius Cylinder. When you cast the spell and as a Magic action on later turns, choose a point under the cloud — each creature within 5 feet makes a DEX save, taking 3d10 Lightning damage on a failure or half on a success. If outdoors in a storm, the spell controls the existing storm and damage increases by 1d10. Using a Higher-Level Spell Slot: Damage increases by 1d10 per slot level above 3.','d10',3,'lightning',1,null,null,null,1,'dex',null,'area','sphere',5,0,0);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_calm_emotions','Calm Emotions',2,'enchantment','action','ranged',60,1,1,0,null,'concentration_1_minute',1,0,'Each Humanoid in a 20-foot-radius Sphere centered on a point within range must succeed on a Charisma saving throw or be affected by one of the following (choose for each): Immunity to Charmed and Frightened conditions (suppressing existing ones), or Indifference toward hostile creatures of your choice (ends if they take damage or witness allies taking damage).',null,null,null,0,null,null,null,null,'cha',null,'area','sphere',20,0,0);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_chain_lightning','Chain Lightning',6,'evocation','action','ranged',150,1,1,1,'three silver pins','instantaneous',0,0,'You launch a lightning bolt toward a target within range. Three bolts then leap from that target to up to three other targets of your choice, each within 30 feet of the first (one bolt per target). Each target makes a DEX save, taking 10d8 Lightning damage on a failure or half on a success. Using a Higher-Level Spell Slot: One additional bolt leaps per slot level above 6.','d8',10,'lightning',1,null,null,null,null,'dex',null,'multiple',null,null,1,1);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_charm_monster','Charm Monster',4,'enchantment','action','ranged',30,1,1,0,null,'1_hour',0,0,'One creature you can see within range makes a Wisdom saving throw (with Advantage if you or allies are fighting it). On a failed save, the target has the Charmed condition until the spell ends or until you or allies damage it. The Charmed creature is Friendly to you. When the spell ends, the target knows it was Charmed. Using a Higher-Level Spell Slot: Target one additional creature per slot level above 4.',null,null,null,1,null,null,null,1,'wis',null,'single',null,null,1,1);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_charm_person','Charm Person',1,'enchantment','action','ranged',30,1,1,0,null,'1_hour',0,0,'One Humanoid you can see within range makes a Wisdom saving throw (with Advantage if you or allies are fighting it). On a failed save, the target has the Charmed condition until the spell ends or until you or allies damage it. The Charmed creature is Friendly to you. When the spell ends, the target knows it was Charmed. Using a Higher-Level Spell Slot: Target one additional creature per slot level above 1.',null,null,null,1,null,null,null,1,'wis',null,'single',null,null,1,1);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_chill_touch','Chill Touch',0,'necromancy','action','touch',null,1,1,0,null,'instantaneous',0,0,'Make a melee spell attack against a target within reach. On a hit, the target takes 1d10 Necrotic damage and can''t regain Hit Points until the end of your next turn. Cantrip Upgrade: The damage increases by 1d10 when you reach levels 5 (2d10), 11 (3d10), and 17 (4d10).','d10',1,'necrotic',1,2,3,4,null,null,'melee_spell','single',null,null,1,1);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_chromatic_orb','Chromatic Orb',1,'evocation','action','ranged',90,1,1,1,'a diamond worth 50+ GP','instantaneous',0,0,'Choose Acid, Cold, Fire, Lightning, Poison, or Thunder and make a ranged spell attack against a target within range. On a hit, the target takes 3d8 damage of the chosen type. If you roll the same number on two or more d8s, the orb leaps to another target within 30 feet (make a new attack and damage roll; can''t leap again unless cast with level 2+ slot). Using a Higher-Level Spell Slot: Damage increases by 1d8 per slot level above 1; orb can leap a maximum number of times equal to the slot level expended.','d8',3,'varies',1,null,null,null,1,null,'ranged_spell','single',null,null,1,1);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_circle_of_death','Circle of Death',6,'necromancy','action','ranged',150,1,1,1,'the powder of a crushed black pearl worth 500+ GP','instantaneous',0,0,'Negative energy ripples out in a 60-foot-radius Sphere from a point you choose within range. Each creature in that area makes a Constitution saving throw, taking 8d8 Necrotic damage on a failed save or half on a successful one. Using a Higher-Level Spell Slot: Damage increases by 2d8 per slot level above 6.','d8',8,'necrotic',1,null,null,null,2,'con',null,'area','sphere',60,1,1);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_circle_of_power','Circle of Power',5,'abjuration','action','self',null,1,0,0,null,'concentration_10_minutes',1,0,'An aura radiates from you in a 30-foot Emanation. While in the aura, you and allies have Advantage on saving throws against spells and magical effects. When an affected creature succeeds on a save against a spell that allows half damage on success, it takes no damage instead.',null,null,null,0,null,null,null,null,null,null,'self','emanation',30,0,1);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_clairvoyance','Clairvoyance',3,'divination','10_minutes','special',5280,1,1,1,'a focus worth 100+ GP (jeweled horn for hearing or glass eye for seeing)','concentration_10_minutes',1,0,'You create an Invisible, invulnerable sensor within range in a familiar or obvious unfamiliar location. Choose seeing or hearing when you cast the spell; you can use that sense through the sensor as if you were in its space. As a Bonus Action, you can switch between seeing and hearing. A creature with See Invisibility or Truesight sees a luminous orb.',null,null,null,0,null,null,null,null,null,null,'self',null,null,0,1);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_clone','Clone',8,'necromancy','1_hour','touch',null,1,1,1,'a diamond worth 1,000+ GP (consumed) and a sealable vessel worth 2,000+ GP large enough to hold the creature','instantaneous',0,0,'You touch a creature or 1 cubic inch of its flesh. An inert duplicate forms in the vessel and finishes growing after 120 days. If the original dies after the clone finishes forming and the soul is free and willing, it transfers to the clone. The clone is physically identical with the same personality, memories, and abilities but none of the original''s equipment. The original''s remains become inert.',null,null,null,0,null,null,null,null,null,null,'single',null,null,0,1);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_cloudkill','Cloudkill',5,'conjuration','action','ranged',120,1,1,0,null,'concentration_10_minutes',1,0,'You create a 20-foot-radius Sphere of yellow-green fog that is Heavily Obscured. Each creature in the Sphere makes a CON save, taking 5d8 Poison damage on a failure or half on a success. A creature also saves when the Sphere moves into its space or when it enters or ends its turn in the Sphere (once per turn). The Sphere moves 10 feet away from you at the start of each of your turns. Strong wind disperses it. Using a Higher-Level Spell Slot: Damage increases by 1d8 per slot level above 5.','d8',5,'poison',1,null,null,null,1,'con',null,'area','sphere',20,1,1);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_cloud_of_daggers','Cloud of Daggers',2,'conjuration','action','ranged',60,1,1,1,'a sliver of glass','concentration_1_minute',1,0,'You conjure spinning daggers in a 5-foot Cube centered on a point within range. Each creature in that area takes 4d4 Slashing damage. A creature also takes this damage if it enters the Cube, ends its turn there, or the Cube moves into its space (once per turn). On later turns, you can take a Magic action to teleport the Cube up to 30 feet. Using a Higher-Level Spell Slot: Damage increases by 2d4 per slot level above 2.','d4',4,'slashing',1,null,null,null,2,null,null,'area','cube',5,1,1);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_color_spray','Color Spray',1,'illusion','action','self',null,1,1,1,'a pinch of colorful sand','instantaneous',0,0,'You launch a dazzling array of flashing, colorful light. Each creature in a 15-foot Cone originating from you must succeed on a Constitution saving throw or have the Blinded condition until the end of your next turn.',null,null,null,0,null,null,null,null,'con',null,'area','cone',15,1,1);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_command','Command',1,'enchantment','action','ranged',60,1,0,0,null,'instantaneous',0,0,'You speak a one-word command to a creature you can see within range. The target must succeed on a Wisdom saving throw or follow the command on its next turn. Choose from: Approach (move toward you by shortest route), Drop (drop held items), Flee (move away by fastest means), Grovel (Prone, end turn), or Halt (no move, action, or Bonus Action). Using a Higher-Level Spell Slot: Affect one additional creature per slot level above 1.',null,null,null,1,null,null,null,1,'wis',null,'single',null,null,1,0);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_commune','Commune',5,'divination','1_minute','self',null,1,1,1,'incense','1_minute',0,1,'You contact a deity or divine proxy and ask up to three yes/no questions before the spell ends. You receive a correct answer for each. Divine beings may answer "unclear" if the question exceeds their knowledge. If cast more than once before a Long Rest, there is a cumulative 25% chance per casting after the first that you get no answer.',null,null,null,0,null,null,null,null,null,null,'self',null,null,0,0);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_commune_with_nature','Commune with Nature',5,'divination','1_minute','self',null,1,1,0,null,'instantaneous',0,1,'You commune with nature spirits and gain knowledge of the surrounding area (3 miles outdoors, 300 feet underground; doesn''t function in constructed areas). Choose three facts to learn: locations of settlements, portals to other planes, one CR 10+ Celestial/Elemental/Fey/Fiend/Undead, the most prevalent plant/mineral/Beast, or locations of bodies of water.',null,null,null,0,null,null,null,null,null,null,'self',null,null,0,0);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_compelled_duel','Compelled Duel',1,'enchantment','bonus_action','ranged',30,1,0,0,null,'concentration_1_minute',1,0,'One creature you can see within range makes a Wisdom saving throw. On a failed save, the target has Disadvantage on attack rolls against creatures other than you and can''t willingly move more than 30 feet away from you. The spell ends if you attack another creature, cast a spell on an enemy other than the target, an ally damages the target, or you end your turn more than 30 feet from the target.',null,null,null,0,null,null,null,null,'wis',null,'single',null,null,1,0);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_comprehend_languages','Comprehend Languages',1,'divination','action','self',null,1,1,1,'a pinch of soot and salt','1_hour',0,1,'For the duration, you understand the literal meaning of any language you hear or see signed. You also understand any written language you see, but you must be touching the surface. It takes about 1 minute to read one page of text. This spell doesn''t decode symbols or secret messages.',null,null,null,0,null,null,null,null,null,null,'self',null,null,0,1);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_compulsion','Compulsion',4,'enchantment','action','ranged',30,1,1,0,null,'concentration_1_minute',1,0,'Each creature of your choice you can see within range must succeed on a Wisdom saving throw or have the Charmed condition until the spell ends. As a Bonus Action, you can designate a horizontal direction — each Charmed target must use as much movement as possible to move that way on its next turn (safest route). After moving, the target repeats the save, ending the spell on itself on a success.',null,null,null,0,null,null,null,null,'wis',null,'multiple',null,null,0,0);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_cone_of_cold','Cone of Cold',5,'evocation','action','self',null,1,1,1,'a small crystal or glass cone','instantaneous',0,0,'Each creature in a 60-foot Cone makes a Constitution saving throw, taking 8d8 Cold damage on a failed save or half on a successful one. A creature killed by this spell becomes a frozen statue until it thaws. Using a Higher-Level Spell Slot: Damage increases by 1d8 per slot level above 5.','d8',8,'cold',1,null,null,null,1,'con',null,'area','cone',60,1,1);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_confusion','Confusion',4,'enchantment','action','ranged',90,1,1,1,'three nut shells','concentration_1_minute',1,0,'Each creature in a 10-foot-radius Sphere centered on a point within range must succeed on a Wisdom saving throw or be confused: can''t take Bonus Actions or Reactions, and rolls 1d10 at turn start (1: move randomly; 2-6: do nothing; 7-8: attack random creature in reach; 9-10: act normally). Repeats save at end of each turn. Using a Higher-Level Spell Slot: Sphere radius increases by 5 feet per slot level above 4.',null,null,null,1,null,null,null,null,'wis',null,'area','sphere',10,1,1);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_conjure_animals','Conjure Animals',3,'conjuration','action','ranged',60,1,1,0,null,'concentration_10_minutes',1,0,'You conjure nature spirits appearing as a Large pack of spectral animals in an unoccupied space within range. You have Advantage on STR saves while within 5 feet of the pack. When you move, you can also move the pack up to 30 feet. Whenever the pack moves within 10 feet of a creature or a creature enters or ends its turn within 10 feet, you can force a DEX save: 3d10 Slashing on failure. Once per turn. Using a Higher-Level Spell Slot: Damage increases by 1d10 per slot level above 3.','d10',3,'slashing',1,null,null,null,1,'dex',null,'single',null,null,0,0);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_conjure_barrage','Conjure Barrage',3,'conjuration','action','self',null,1,1,1,'a Melee or Ranged weapon worth at least 1 CP','instantaneous',0,0,'You brandish the weapon used to cast the spell and conjure spectral weapons or ammunition that launch forward. Each creature of your choice you can see in a 60-foot Cone makes a DEX save, taking 5d8 Force damage on a failure or half on a success. Using a Higher-Level Spell Slot: Damage increases by 1d8 per slot level above 3.','d8',5,'force',1,null,null,null,1,'dex',null,'area','cone',60,0,0);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_conjure_celestial','Conjure Celestial',7,'conjuration','action','ranged',90,1,1,0,null,'concentration_10_minutes',1,0,'You conjure a spirit from the Upper Planes as a 10-foot-radius, 40-foot-high Cylinder of light. For each creature you can see in the Cylinder, choose: Healing Light (regain 4d12 + spellcasting modifier HP) or Searing Light (DEX save, 6d12 Radiant on failure or half on success). The Cylinder fills with Bright Light; you can move it up to 30 feet when you move. A creature can be affected only once per turn. Using a Higher-Level Spell Slot: Healing and damage increase by 1d12 per slot level above 7.','d12',6,'radiant',1,null,null,null,1,'dex',null,'area','cylinder',10,0,0);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_conjure_elemental','Conjure Elemental',5,'conjuration','action','ranged',60,1,1,0,null,'concentration_10_minutes',1,0,'You conjure a Large intangible spirit from the Elemental Planes. Choose element: air (Lightning), earth (Thunder), fire (Fire), or water (Cold). Creatures entering or starting within 5 feet make a DEX save (if no creature Restrained): 8d8 damage on failure and Restrained until spell ends. Restrained targets repeat the save each turn: 4d8 on failure, released on success. Using a Higher-Level Spell Slot: Damage increases by 1d8 per slot level above 5.','d8',8,'varies',1,null,null,null,1,'dex',null,'single',null,null,0,1);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_conjure_fey','Conjure Fey',6,'conjuration','action','ranged',60,1,1,0,null,'concentration_10_minutes',1,0,'You conjure a Medium Fey spirit in an unoccupied space within range. When it appears, you can make one melee spell attack against a creature within 5 feet of it: 3d12 + spellcasting modifier Psychic damage on a hit, and the target is Frightened until the start of your next turn. As a Bonus Action on later turns, teleport the spirit to an unoccupied space within 30 feet and make the attack again. Using a Higher-Level Spell Slot: Damage increases by 1d12 per slot level above 6.','d12',3,'psychic',1,null,null,null,1,null,'melee_spell','single',null,null,0,0);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_conjure_minor_elementals','Conjure Minor Elementals',4,'conjuration','action','self',null,1,1,0,null,'concentration_10_minutes',1,0,'You conjure Elemental spirits that flit around you in a 15-foot Emanation. Until the spell ends, any attack you make deals an extra 2d8 damage (Acid, Cold, Fire, or Lightning — your choice per attack) when you hit a creature in the Emanation. The ground in the Emanation is Difficult Terrain for enemies. Using a Higher-Level Spell Slot: Damage increases by 1d8 per slot level above 4.','d8',2,'varies',1,null,null,null,1,null,null,'self','emanation',15,0,1);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_conjure_volley','Conjure Volley',5,'conjuration','action','ranged',150,1,1,1,'a Melee or Ranged weapon worth at least 1 CP','instantaneous',0,0,'You brandish the weapon and choose a point within range. Hundreds of spectral weapons fall in a volley in a 40-foot-radius, 20-foot-high Cylinder centered on that point. Each creature of your choice you can see in the area makes a DEX save, taking 8d8 Force damage on a failure or half on a success.','d8',8,'force',0,null,null,null,null,'dex',null,'area','cylinder',40,0,0);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_conjure_woodland_beings','Conjure Woodland Beings',4,'conjuration','action','self',null,1,1,0,null,'concentration_10_minutes',1,0,'You conjure nature spirits in a 10-foot Emanation. Whenever the Emanation enters a creature''s space or a creature enters or ends its turn there, you can force a WIS save: 5d8 Force damage on failure or half on success (once per turn). Additionally, you can take the Disengage action as a Bonus Action for the spell''s duration. Using a Higher-Level Spell Slot: Damage increases by 1d8 per slot level above 4.','d8',5,'force',1,null,null,null,1,'wis',null,'self','emanation',10,0,0);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_contact_other_plane','Contact Other Plane',5,'divination','1_minute','self',null,1,0,0,null,'1_minute',0,1,'You mentally contact a demigod or otherworldly entity. Make a DC 15 INT save. On success, ask up to five questions; DM answers each with one word. On failure, take 6d6 Psychic damage and the Incapacitated condition until you finish a Long Rest (Greater Restoration ends this early).','d6',6,'psychic',0,null,null,null,null,'int',null,'self',null,null,0,1);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_contagion','Contagion',5,'necromancy','action','touch',null,1,1,0,null,'7_days',0,0,'Your touch inflicts a magical contagion. The target must succeed on a CON save or take 11d8 Necrotic damage and gain the Poisoned condition. Choose one ability — while Poisoned, the target has Disadvantage on saves with that ability. The target repeats the save at the end of each turn; three successes end the spell, three failures lock in the 7-day duration. Effects that would end Poisoned require a CON save to take effect.','d8',11,'necrotic',0,null,null,null,null,'con',null,'single',null,null,0,0);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_contingency','Contingency',6,'abjuration','10_minutes','self',null,1,1,1,'a gem-encrusted statuette of yourself worth 1,500+ GP','10_days',0,0,'Choose a level 5 or lower spell with an action casting time that can target you. Cast it as part of casting Contingency (expending slots for both), but the contingent spell doesn''t take effect yet. Describe a trigger — when it first occurs, the contingent spell activates on you automatically. Only one Contingency at a time; casting it again ends the previous one. Also ends if the material component leaves your person.',null,null,null,0,null,null,null,null,null,null,'self',null,null,0,1);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_continual_flame','Continual Flame',2,'evocation','action','touch',null,1,1,1,'ruby dust worth 50+ GP, which the spell consumes','until_dispelled',0,0,'A flame springs from an object you touch, casting Bright Light in a 20-foot radius and Dim Light for an additional 20 feet. It looks like a regular flame but creates no heat and consumes no fuel. It can be covered or hidden but not smothered or quenched.',null,null,null,0,null,null,null,null,null,null,'single',null,null,0,1);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_control_water','Control Water',4,'transmutation','action','ranged',300,1,1,1,'a mixture of water and dust','concentration_10_minutes',1,0,'You control water in a Cube up to 100 feet on a side. Choose one effect (repeatable as Magic action): Flood (raise water level 20 feet or create a wave); Part Water (create a trench, water walls to either side); Redirect Flow (move flowing water in any direction); Whirlpool (5-foot-wide base, 50-foot-wide top, 25-foot-tall — creatures within 25 feet pulled 10 feet toward it, STR save or 2d8 Bludgeoning, half on success).','d8',2,'bludgeoning',0,null,null,null,null,'str',null,'area','cube',100,0,1);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_control_weather','Control Weather',8,'transmutation','10_minutes','self',null,1,1,1,'burning incense','concentration_8_hours',1,0,'You take control of the weather within 5 miles of you for the duration. Must be outdoors; ends early if you go indoors. Change current weather conditions (precipitation, temperature, wind) by shifting any stage up or down by one. New conditions take 1d4 × 10 minutes to take effect. Weather gradually returns to normal when the spell ends.',null,null,null,0,null,null,null,null,null,null,'self',null,null,0,1);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_cordon_of_arrows','Cordon of Arrows',2,'transmutation','action','touch',null,1,1,1,'an ornamental braid','8_hours',0,0,'You plant up to four nonmagical arrows or bolts in the ground in your space. Whenever a creature other than you enters a space within 30 feet of the ammunition for the first time on a turn or ends its turn there, one piece of ammunition flies up to strike it: DEX save or 2d4 Piercing damage. The ammunition is then destroyed. Spell ends when no ammunition remains. Using a Higher-Level Spell Slot: Ammunition affected increases by two per slot level above 2.','d4',2,'piercing',1,null,null,null,null,'dex',null,'area',null,30,0,0);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_counterspell','Counterspell',3,'abjuration','reaction','ranged',60,0,1,0,null,'instantaneous',0,0,'You attempt to interrupt a creature within 60 feet that is casting a spell with Verbal, Somatic, or Material components. The creature makes a Constitution saving throw. On a failed save, the spell dissipates with no effect and the action, Bonus Action, or Reaction used to cast it is wasted. If cast with a spell slot, the slot is not expended.',null,null,null,0,null,null,null,null,'con',null,'single',null,null,1,1);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_create_food_and_water','Create Food and Water',3,'conjuration','action','ranged',30,1,1,0,null,'instantaneous',0,0,'You create 45 pounds of bland but nourishing food and 30 gallons of fresh clean water on the ground or in containers within range. The food spoils after 24 hours if uneaten.',null,null,null,0,null,null,null,null,null,null,'single',null,null,0,0);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_create_or_destroy_water','Create or Destroy Water',1,'transmutation','action','ranged',30,1,1,1,'a mix of water and sand','instantaneous',0,0,'Choose one: Create Water (up to 10 gallons in an open container, or rain in a 30-foot Cube extinguishing exposed flames); or Destroy Water (up to 10 gallons in an open container, or destroy fog in a 30-foot Cube). Using a Higher-Level Spell Slot: Create or destroy 10 additional gallons, or Cube increases by 5 feet, per slot level above 1.',null,null,null,1,null,null,null,null,null,null,'single',null,null,0,0);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_create_undead','Create Undead',6,'necromancy','1_minute','ranged',10,1,1,1,'one 150+ GP black onyx stone per corpse','instantaneous',0,0,'Cast only at night. Choose up to three Medium or Small Humanoid corpses within range; each becomes a Ghoul under your control. Bonus Action command any within 120 feet. Control lasts 24 hours; recast before it ends to maintain control over up to three Ghouls. Using a Higher-Level Spell Slot: Level 7: four Ghouls; Level 8: five Ghouls or two Ghasts/Wights; Level 9: six Ghouls, three Ghasts/Wights, or two Mummies.',null,null,null,1,null,null,null,null,null,null,'multiple',null,null,0,1);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_creation','Creation',5,'illusion','1_minute','ranged',30,1,1,1,'a paintbrush','special',0,0,'You pull wisps of shadow material from the Shadowfell to create a nonliving object within range — vegetable matter (24 hrs), stone or crystal (12 hrs), precious metals (1 hr), gems (10 min), or adamantine/mithral (1 min). No larger than a 5-foot Cube. Using it as a spell material component causes that spell to fail. Using a Higher-Level Spell Slot: Cube increases by 5 feet per slot level above 5.',null,null,null,1,null,null,null,null,null,null,'single',null,null,0,1);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_crown_of_madness','Crown of Madness',2,'enchantment','action','ranged',120,1,1,0,null,'concentration_1_minute',1,0,'One Humanoid you can see within range must succeed on a Wisdom saving throw or have the Charmed condition. A spectral crown appears on it; before moving each turn it must use its action to make a melee attack against a creature you mentally choose. If no creature chosen or none in reach, it acts normally. Repeats save at end of each turn. You must take the Magic action each turn to maintain control, or the spell ends.',null,null,null,0,null,null,null,null,'wis',null,'single',null,null,1,1);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_crusaders_mantle','Crusader''s Mantle',3,'evocation','action','self',null,1,0,0,null,'concentration_1_minute',1,0,'You radiate a magical aura in a 30-foot Emanation. While in the aura, you and your allies each deal an extra 1d4 Radiant damage when hitting with a weapon or an Unarmed Strike.',null,null,'radiant',0,null,null,null,null,null,null,'self','emanation',30,0,0);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_cure_wounds','Cure Wounds',1,'abjuration','action','touch',null,1,1,0,null,'instantaneous',0,0,'A creature you touch regains a number of Hit Points equal to 2d8 plus your spellcasting ability modifier. Using a Higher-Level Spell Slot: The healing increases by 2d8 for each slot level above 1.',null,null,null,1,null,null,null,null,null,null,'single',null,null,0,0);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_dancing_lights','Dancing Lights',0,'illusion','action','ranged',120,1,1,1,'a bit of phosphorus','concentration_1_minute',1,0,'You create up to four torch-size lights within range appearing as torches, lanterns, or glowing orbs, or combine them into one glowing Medium humanlike form. Each light sheds Dim Light in a 10-foot radius. As a Bonus Action, you can move the lights up to 60 feet to a space within range. A light must be within 20 feet of another light created by this spell and vanishes if it exceeds the spell''s range.',null,null,null,0,null,null,null,null,null,null,'area',null,120,0,1);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_darkness','Darkness',2,'evocation','action','ranged',60,1,0,1,'bat fur and a piece of coal','concentration_10_minutes',1,0,'Magical Darkness spreads from a point within range and fills a 15-foot-radius Sphere. Darkvision can''t see through it and nonmagical light can''t illuminate it. Alternatively, cast on an object not worn or carried, causing Darkness to fill a 15-foot Emanation from that object (covering the object blocks the Darkness). If this spell''s area overlaps a Bright or Dim Light area created by a spell of level 2 or lower, that spell is dispelled.',null,null,null,0,null,null,null,null,null,null,'area','sphere',15,1,1);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_darkvision','Darkvision',2,'transmutation','action','touch',null,1,1,1,'a dried carrot','8_hours',0,0,'For the duration, a willing creature you touch has Darkvision with a range of 150 feet.',null,null,null,0,null,null,null,null,null,null,'single',null,null,0,1);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_daylight','Daylight',3,'evocation','action','ranged',60,1,1,0,null,'1_hour',0,0,'Sunlight spreads from a point within range and fills a 60-foot-radius Sphere of Bright Light, shedding Dim Light for an additional 60 feet. Alternatively, cast on an object not worn or carried, causing sunlight to fill a 60-foot Emanation from it (covering the object blocks the sunlight). If this spell''s area overlaps Darkness created by a spell of level 3 or lower, that spell is dispelled.',null,null,null,0,null,null,null,null,null,null,'area','sphere',60,0,0);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_death_ward','Death Ward',4,'abjuration','action','touch',null,1,1,0,null,'8_hours',0,0,'You touch a creature and grant it protection from death. The first time the target would drop to 0 Hit Points before the spell ends, it instead drops to 1 Hit Point and the spell ends. If still in effect when the target is subjected to an effect that would kill it instantly without dealing damage, that effect is negated and the spell ends.',null,null,null,0,null,null,null,null,null,null,'single',null,null,0,0);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_delayed_blast_fireball','Delayed Blast Fireball',7,'evocation','action','ranged',150,1,1,1,'a ball of bat guano and sulfur','concentration_1_minute',1,0,'A beam of yellow light condenses at a chosen point within range as a glowing bead. When the spell ends, the bead explodes in a 20-foot-radius Sphere: DEX save or take accumulated Fire damage (half on success). Base damage is 12d6, increasing by 1d6 at the end of each of your turns while the spell persists. A creature touching the bead makes a DEX save: failure ends the spell (bead explodes), success lets it throw the bead up to 40 feet (explodes on contact). Flammable objects ignite. Using a Higher-Level Spell Slot: Base damage increases by 1d6 per slot level above 7.','d6',12,'fire',1,null,null,null,1,'dex',null,'area','sphere',20,1,1);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_demiplane','Demiplane',8,'conjuration','action','ranged',60,0,1,0,null,'1_hour',0,0,'You create a shadowy Medium door on a flat solid surface within range leading to an empty 30-foot-cube room of wood or stone (your choice). When the spell ends, the door vanishes; objects inside remain, and creatures inside are shunted through as it vanishes (landing Prone in nearest unoccupied spaces) unless they choose otherwise. You can create a new demiplane or connect to one you or another caster created previously.',null,null,null,0,null,null,null,null,null,null,'single',null,null,0,1);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_destructive_wave','Destructive Wave',5,'evocation','action','self',null,1,0,0,null,'instantaneous',0,0,'Destructive energy ripples outward in a 30-foot Emanation. Each creature you choose in the area makes a CON save. On a failed save, the target takes 5d6 Thunder damage and 5d6 Radiant or Necrotic damage (your choice) and has the Prone condition. On a successful save, the target takes half as much damage only.','d6',10,'thunder',0,null,null,null,null,'con',null,'area','emanation',30,0,0);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_detect_evil_and_good','Detect Evil and Good',1,'divination','action','self',null,1,1,0,null,'concentration_10_minutes',1,0,'For the duration, you sense the location of any Aberration, Celestial, Elemental, Fey, Fiend, or Undead within 30 feet of yourself. You also sense whether the Hallow spell is active there and where. Blocked by 1 foot of stone, dirt, or wood; 1 inch of metal; or a thin sheet of lead.',null,null,null,0,null,null,null,null,null,null,'self',null,null,0,0);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_detect_magic','Detect Magic',1,'divination','action','self',null,1,1,0,null,'concentration_10_minutes',1,1,'For the duration, you sense the presence of magical effects within 30 feet. You can take the Magic action to see a faint aura around any visible creature or object bearing magic, and if an effect was created by a spell you learn its school. Blocked by 1 foot of stone, dirt, or wood; 1 inch of metal; or a thin sheet of lead.',null,null,null,0,null,null,null,null,null,null,'self',null,null,0,1);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_detect_poison_and_disease','Detect Poison and Disease',1,'divination','action','self',null,1,1,1,'a yew leaf','concentration_10_minutes',1,1,'For the duration, you sense the location of poisons, poisonous or venomous creatures, and magical contagions within 30 feet of yourself. You sense the kind of poison, creature, or contagion in each case. Blocked by 1 foot of stone, dirt, or wood; 1 inch of metal; or a thin sheet of lead.',null,null,null,0,null,null,null,null,null,null,'self',null,null,0,0);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_detect_thoughts','Detect Thoughts',2,'divination','action','self',null,1,1,1,'1 Copper Piece','concentration_1_minute',1,0,'You sense thoughts within 30 feet from creatures that know languages or are telepathic (Sense Thoughts). As a Magic action, target one sensed or visible creature within 30 feet to Read Thoughts (learn what''s most on its mind). On your next turn, probe deeper: WIS save or you learn its reasoning, emotions, and something that looms large in its mind; on success the spell ends. The target always knows you''re probing and can attempt an INT (Arcana) check against your spell save DC to end the spell.',null,null,null,0,null,null,null,null,'wis',null,'single',null,null,0,1);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_dimension_door','Dimension Door',4,'conjuration','action','special',500,1,0,0,null,'instantaneous',0,0,'You teleport to a location within range — a place you can see, visualize, or describe by distance and direction. You can also teleport one willing creature within 5 feet of you; it arrives within 5 feet of your destination. If either of you would arrive in an occupied space, both take 4d6 Force damage and the teleportation fails.','d6',4,'force',0,null,null,null,null,null,null,'single',null,null,1,1);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_disguise_self','Disguise Self',1,'illusion','action','self',null,1,1,0,null,'1_hour',0,0,'You make yourself — including clothing, armor, weapons, and belongings — look different until the spell ends. You can appear up to 1 foot shorter or taller, heavier or lighter. You must have the same basic limb arrangement. Changes don''t hold up to physical inspection. A creature can discern the disguise with a Study action and a successful INT (Investigation) check against your spell save DC.',null,null,null,0,null,null,null,null,null,null,'self',null,null,0,1);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_disintegrate','Disintegrate',6,'transmutation','action','ranged',60,1,1,1,'a lodestone and dust','instantaneous',0,0,'You launch a green ray at a target (creature, nonmagical object, or magical force construct) within range. A creature makes a DEX save, taking 10d6 + 40 Force damage on a failure. If this reduces it to 0 HP, it and everything nonmagical it wears and carries are disintegrated into gray dust (revivable only by True Resurrection or Wish). Automatically disintegrates a Large or smaller nonmagical object or magical force; for Huge or larger, disintegrates a 10-foot-Cube portion. Using a Higher-Level Spell Slot: Damage increases by 3d6 per slot level above 6.','d6',10,'force',1,null,null,null,3,'dex',null,'single',null,null,1,1);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_dispel_evil_and_good','Dispel Evil and Good',5,'abjuration','action','self',null,1,1,1,'powdered silver and iron','concentration_1_minute',1,0,'Celestials, Elementals, Fey, Fiends, and Undead have Disadvantage on attack rolls against you for the duration. You can end the spell early with one of: Break Enchantment (Magic action, touch a creature to end possession or Charmed/Frightened from such creatures); or Dismissal (Magic action, target one such creature within 5 feet — CHA save or sent to its home plane).',null,null,null,0,null,null,null,null,'cha',null,'single',null,null,0,0);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_dispel_magic','Dispel Magic',3,'abjuration','action','ranged',120,1,1,0,null,'instantaneous',0,0,'Choose one creature, object, or magical effect within range. Any ongoing spell of level 3 or lower on the target ends. For each ongoing spell of level 4 or higher, make a spellcasting ability check (DC 10 + that spell''s level) — on success, that spell ends. Using a Higher-Level Spell Slot: You automatically end spells whose level is equal to or less than the slot level used.',null,null,null,1,null,null,null,null,null,null,'single',null,null,1,1);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_dissonant_whispers','Dissonant Whispers',1,'enchantment','action','ranged',60,1,0,0,null,'instantaneous',0,0,'One creature you can see within range hears a discordant melody in its mind. The target makes a WIS save. On a failed save, it takes 3d6 Psychic damage and must immediately use its Reaction (if available) to move as far from you as possible by the safest route. On a successful save, it takes half damage only. Using a Higher-Level Spell Slot: Damage increases by 1d6 per slot level above 1.','d6',3,'psychic',1,null,null,null,1,'wis',null,'single',null,null,1,0);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_divination','Divination',4,'divination','action','self',null,1,1,1,'incense worth 25+ GP, which the spell consumes','instantaneous',0,1,'You contact a god or its servants and ask one question about a specific goal, event, or activity to occur within 7 days. The DM offers a truthful reply (short phrase or cryptic rhyme). If cast more than once before a Long Rest, cumulative 25% chance per casting after the first that you get no answer.',null,null,null,0,null,null,null,null,null,null,'self',null,null,0,1);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_divine_favor','Divine Favor',1,'transmutation','bonus_action','self',null,1,1,0,null,'1_minute',0,0,'Until the spell ends, your attacks with weapons deal an extra 1d4 Radiant damage on a hit.','d4',1,'radiant',0,null,null,null,null,null,null,'self',null,null,0,0);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_divine_smite','Divine Smite',1,'evocation','bonus_action','self',null,1,0,0,null,'instantaneous',0,0,'The target takes an extra 2d8 Radiant damage from the attack. The damage increases by 1d8 if the target is a Fiend or an Undead. Using a Higher-Level Spell Slot: The damage increases by 1d8 per slot level above 1.','d8',2,'radiant',1,null,null,null,1,null,null,'single',null,null,0,0);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_divine_word','Divine Word',7,'evocation','bonus_action','ranged',30,1,0,0,null,'instantaneous',0,0,'Each creature of your choice in range makes a CHA save. On a failed save, targets with 50 HP or fewer suffer effects based on current HP: 0-20 (dies), 21-30 (Blinded, Deafened, Stunned for 1 hour), 31-40 (Blinded and Deafened for 10 minutes), 41-50 (Deafened for 1 minute). Regardless of HP, Celestials, Elementals, Fey, and Fiends that fail are forced back to their home plane for 24 hours.',null,null,null,0,null,null,null,null,'cha',null,'multiple',null,null,0,0);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_dominate_beast','Dominate Beast',4,'enchantment','action','ranged',60,1,1,0,null,'concentration_1_minute',1,0,'One Beast within range must succeed on a WIS save (Advantage if you or allies are fighting it) or have the Charmed condition. You have a telepathic link and can issue commands on your turn (no action required). Whenever it takes damage, it repeats the save. Using a Higher-Level Spell Slot: Duration extends to 10 minutes (5), 1 hour (6), or 8 hours (7+).',null,null,null,1,null,null,null,null,'wis',null,'single',null,null,0,0);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_dominate_monster','Dominate Monster',8,'enchantment','action','ranged',60,1,1,0,null,'concentration_1_hour',1,0,'One creature within range must succeed on a WIS save (Advantage if you or allies are fighting it) or have the Charmed condition. You have a telepathic link and can issue commands on your turn (no action required). Whenever it takes damage, it repeats the save. Using a Higher-Level Spell Slot: Duration extends to 8 hours with a level 9 slot.',null,null,null,1,null,null,null,null,'wis',null,'single',null,null,0,1);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_dominate_person','Dominate Person',5,'enchantment','action','ranged',60,1,1,0,null,'concentration_1_minute',1,0,'One Humanoid within range must succeed on a WIS save (Advantage if you or allies are fighting it) or have the Charmed condition. You have a telepathic link and can issue commands on your turn (no action required). Whenever it takes damage, it repeats the save. Using a Higher-Level Spell Slot: Duration extends to 10 minutes (6), 1 hour (7), or 8 hours (8+).',null,null,null,1,null,null,null,null,'wis',null,'single',null,null,1,1);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_dragons_breath','Dragon''s Breath',2,'transmutation','bonus_action','touch',null,1,1,1,'a hot pepper','concentration_1_minute',1,0,'You touch one willing creature and choose Acid, Cold, Fire, Lightning, or Poison. Until the spell ends, the target can take a Magic action to exhale a 15-foot Cone: DEX save or 3d6 damage of the chosen type (half on success). Using a Higher-Level Spell Slot: Damage increases by 1d6 per slot level above 2.','d6',3,'varies',1,null,null,null,1,'dex',null,'area','cone',15,0,1);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_drawmijs_instant_summons','Drawmij''s Instant Summons',6,'conjuration','1_minute','touch',null,1,1,1,'a sapphire worth 1,000+ GP','until_dispelled',0,1,'You touch the sapphire and an object weighing 10 pounds or less (longest dimension 6 feet or less), leaving an Invisible mark on the object and inscribing its name on the sapphire. Each casting requires a different sapphire. You can then take a Magic action to speak the object''s name and crush the sapphire — the object instantly appears in your hand and the spell ends. If another creature holds it, you instead learn who has it and where they are.',null,null,null,0,null,null,null,null,null,null,'single',null,null,0,1);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_dream','Dream',5,'illusion','1_minute','special',null,1,1,1,'a handful of sand','8_hours',0,0,'You target a creature you know on the same plane. You or a willing creature you touch enters a trance (Incapacitated, Speed 0) to act as a dream messenger. If the target is asleep, the messenger appears in the target''s dreams, can converse and shape the dream environment. The target recalls the dream perfectly on waking. You can make the messenger terrifying: deliver up to ten words, then the target makes a WIS save — on failure, gains no benefit from rest and takes 3d6 Psychic damage on waking.','d6',3,'psychic',0,null,null,null,null,'wis',null,'single',null,null,0,1);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_druidcraft','Druidcraft',0,'transmutation','action','ranged',30,1,1,0,null,'instantaneous',0,0,'You create one of the following effects: Weather Sensor (a Tiny sensory effect predicting weather for the next 24 hours, persisting 1 round); Bloom (instantly make a flower blossom, seed pod open, or leaf bud bloom); Sensory Effect (a harmless sensory effect fitting in a 5-foot Cube); or Fire Play (light or snuff out a candle, torch, or campfire).',null,null,null,0,null,null,null,null,null,null,'single',null,null,0,0);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_earthquake','Earthquake',8,'transmutation','action','ranged',500,1,1,1,'a fractured rock','concentration_1_minute',1,0,'An intense tremor rips through the ground in a 100-foot-radius circle centered on a point you can see within range. The ground is Difficult Terrain. When cast and at the end of each of your turns, each creature on the ground in the area makes a DEX save — on failure, Prone and Concentration broken. Also causes 1d6 fissures (1d10×10 ft deep, 10 ft wide; creatures in same space make DEX save or fall in), and deals 50 Bludgeoning damage to structures each turn. Collapsing structures deal 12d6 Bludgeoning to nearby creatures (DEX save, half on success) and bury those who fail.','d6',12,'bludgeoning',0,null,null,null,null,'dex',null,'area','sphere',100,0,0);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_eldritch_blast','Eldritch Blast',0,'evocation','action','ranged',120,1,1,0,null,'instantaneous',0,0,'You hurl a beam of crackling energy. Make a ranged spell attack against one creature or object in range. On a hit, the target takes 1d10 Force damage. Cantrip Upgrade: The spell creates two beams at level 5, three at level 11, and four at level 17. You can direct beams at the same or different targets; make a separate attack roll for each.','d10',1,'force',1,2,3,4,null,null,'ranged_spell','single',null,null,1,0);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_elementalism','Elementalism',0,'transmutation','action','ranged',30,1,1,0,null,'instantaneous',0,0,'You exert control over the elements, creating one effect within range: Beckon Air (ripple cloth, stir dust, close doors/shutters in a 5-foot Cube); Beckon Earth (thin shroud of dust/sand in a 5-foot square, or write a word in dirt/sand); Beckon Fire (harmless embers and colored scented smoke in a 5-foot Cube that can light candles/torches/lamps; scent lingers 1 minute); Beckon Water (cool mist in a 5-foot Cube, or create 1 cup of clean water that evaporates in 1 minute); or Sculpt Element (shape up to 1-foot Cube of dirt, sand, fire, smoke, mist, or water for 1 hour).',null,null,null,0,null,null,null,null,null,null,'single',null,null,0,1);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_elemental_weapon','Elemental Weapon',3,'transmutation','action','touch',null,1,1,0,null,'concentration_1_hour',1,0,'A nonmagical weapon you touch becomes a magic weapon. Choose Acid, Cold, Fire, Lightning, or Thunder. For the duration, the weapon has a +1 bonus to attack rolls and deals an extra 1d4 damage of the chosen type on a hit. Using a Higher-Level Spell Slot: Level 5-6 slot: +2 bonus and 2d4 extra damage; level 7+ slot: +3 bonus and 3d4 extra damage.','d4',1,'varies',1,null,null,null,null,null,null,'single',null,null,0,0);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_enhance_ability','Enhance Ability',2,'transmutation','action','touch',null,1,1,1,'fur or a feather','concentration_1_hour',1,0,'You touch a creature and choose Strength, Dexterity, Intelligence, Wisdom, or Charisma. For the duration, the target has Advantage on ability checks using the chosen ability. Using a Higher-Level Spell Slot: You can target one additional creature per slot level above 2, choosing a different ability for each target.',null,null,null,1,null,null,null,null,null,null,'single',null,null,0,1);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_enlarge_reduce','Enlarge/Reduce',2,'transmutation','action','ranged',30,1,1,1,'a pinch of powdered iron','concentration_1_minute',1,0,'Enlarge or reduce a creature or unworn/uncarried object within range (unwilling creatures make a CON save). Enlarge: size increases by one category; Advantage on STR checks and saves; attacks deal extra 1d4 damage. Reduce: size decreases by one category; Disadvantage on STR checks and saves; attacks deal 1d4 less damage (minimum 1). Everything worn or carried changes size with the target; dropped items return to normal immediately.',null,null,null,0,null,null,null,null,'con',null,'single',null,null,1,1);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_ensnaring_strike','Ensnaring Strike',1,'conjuration','bonus_action','self',null,1,0,0,null,'concentration_1_minute',1,0,'As you hit the target, grasping vines appear on it and it makes a STR save (Large or larger creatures have Advantage). On a failed save, the target has the Restrained condition until the spell ends. While Restrained, it takes 1d6 Piercing damage at the start of each of its turns. The target or a creature within reach can take an action to make a STR (Athletics) check against your spell save DC to end the spell. Using a Higher-Level Spell Slot: Damage increases by 1d6 per slot level above 1.','d6',1,'piercing',1,null,null,null,1,'str',null,'single',null,null,0,0);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_entangle','Entangle',1,'conjuration','action','ranged',90,1,1,0,null,'concentration_1_minute',1,0,'Grasping plants sprout in a 20-foot square within range, turning the ground into Difficult Terrain until the spell ends. Each creature (other than you) in the area when cast must succeed on a STR save or have the Restrained condition until the spell ends. A Restrained creature can take an action to make a STR (Athletics) check against your spell save DC to free itself.',null,null,null,0,null,null,null,null,'str',null,'area','square',20,1,0);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_enthrall','Enthrall',2,'enchantment','action','ranged',60,1,1,0,null,'concentration_1_minute',1,0,'You weave a distracting string of words, causing creatures of your choice you can see within range to make a WIS save. Creatures you or your companions are fighting automatically succeed. On a failed save, a target has a −10 penalty to WIS (Perception) checks and Passive Perception until the spell ends.',null,null,null,0,null,null,null,null,'wis',null,'multiple',null,null,0,0);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_etherealness','Etherealness',7,'conjuration','action','self',null,1,1,0,null,'8_hours',0,0,'You step into the Border Ethereal for the duration. You can move in any direction (up/down costs extra movement). You can perceive the plane you left in gray up to 60 feet. You can only affect and be affected by Ethereal creatures and effects. When the spell ends, you return to where you left; if occupied, you are shunted to nearest unoccupied space and take Force damage equal to twice the feet moved. Using a Higher-Level Spell Slot: Target up to three willing creatures (including yourself) per slot level above 7 (must be within 10 feet when cast).',null,null,null,1,null,null,null,null,null,null,'self',null,null,0,1);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_evards_black_tentacles','Evard''s Black Tentacles',4,'conjuration','action','ranged',90,1,1,1,'a tentacle','concentration_1_minute',1,0,'Squirming ebony tentacles fill a 20-foot square on ground you can see within range, turning it into Difficult Terrain. Each creature in the area makes a STR save: on failure, takes 3d6 Bludgeoning damage and has the Restrained condition until the spell ends. A creature also saves if it enters the area or ends its turn there (once per turn). A Restrained creature can take an action to make a STR (Athletics) check against your spell save DC to end the condition on itself.','d6',3,'bludgeoning',0,null,null,null,null,'str',null,'area','square',20,1,1);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_expeditious_retreat','Expeditious Retreat',1,'transmutation','bonus_action','self',null,1,1,0,null,'concentration_10_minutes',1,0,'You take the Dash action, and until the spell ends, you can take that action again as a Bonus Action.',null,null,null,0,null,null,null,null,null,null,'self',null,null,0,1);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_eyebite','Eyebite',6,'necromancy','action','self',null,1,1,0,null,'concentration_1_minute',1,0,'Your eyes become an inky void. One creature of your choice within 60 feet must succeed on a WIS save or be affected by one effect of your choice: Asleep (Unconscious until it takes damage or is shaken awake); Panicked (Frightened, must Dash away from you each turn; ends if 60+ feet away where it can''t see you); or Sickened (Poisoned condition). On each of your turns, you can take a Magic action to target another creature (can''t re-target a creature that succeeded on this save).',null,null,null,0,null,null,null,null,'wis',null,'single',null,null,1,1);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_fabricate','Fabricate',4,'transmutation','10_minutes','ranged',120,1,1,0,null,'instantaneous',0,0,'You convert raw materials into products of the same material. Choose raw materials you can see within range. You can fabricate a Large or smaller object (within a 10-foot Cube or eight connected 5-foot Cubes) given sufficient material. Metal, stone, or mineral objects can be no larger than Medium (within a 5-foot Cube). Creatures and magic items can''t be created. Items requiring high skill (weapons, armor) require proficiency with the relevant Artisan''s Tools.',null,null,null,0,null,null,null,null,null,null,'single',null,null,0,1);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_faerie_fire','Faerie Fire',1,'evocation','action','ranged',60,1,0,0,null,'concentration_1_minute',1,0,'Objects in a 20-foot Cube within range are outlined in blue, green, or violet light (your choice). Each creature in the Cube is also outlined if it fails a DEX save. Outlined objects and creatures shed Dim Light in a 10-foot radius and can''t benefit from the Invisible condition. Attack rolls against an affected creature or object have Advantage if the attacker can see it.',null,null,null,0,null,null,null,null,'dex',null,'area','cube',20,1,0);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_false_life','False Life',1,'necromancy','action','self',null,1,1,1,'a drop of alcohol','instantaneous',0,0,'You gain 2d4 + 4 Temporary Hit Points. Using a Higher-Level Spell Slot: You gain 5 additional Temporary Hit Points for each slot level above 1.',null,null,null,1,null,null,null,null,null,null,'self',null,null,1,1);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_fear','Fear',3,'illusion','action','self',null,1,1,1,'a white feather','concentration_1_minute',1,0,'Each creature in a 30-foot Cone must succeed on a WIS save or drop whatever it is holding and have the Frightened condition. A Frightened creature Dashes away by the safest route each turn unless there is nowhere to move. If the creature ends its turn without line of sight to you, it makes a WIS save — on success, the spell ends on that creature.',null,null,null,0,null,null,null,null,'wis',null,'area','cone',30,1,1);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_feather_fall','Feather Fall',1,'transmutation','reaction','ranged',60,1,0,1,'a small feather or piece of down','1_minute',0,0,'Choose up to five falling creatures within range. Each target''s rate of descent slows to 60 feet per round until the spell ends. If a creature lands before the spell ends, it takes no damage from the fall and the spell ends for that creature.',null,null,null,0,null,null,null,null,null,null,'multiple',null,null,0,1);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_feign_death','Feign Death',3,'necromancy','action','touch',null,1,1,1,'a pinch of graveyard dirt','1_hour',0,1,'You touch a willing creature and put it into a cataleptic state indistinguishable from death. For the duration, the target appears dead to inspection and status spells. The target has the Blinded and Incapacitated conditions and Speed 0. It has Resistance to all damage except Psychic, and Immunity to the Poisoned condition.',null,null,null,0,null,null,null,null,null,null,'single',null,null,0,1);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_find_familiar','Find Familiar',1,'conjuration','1_hour','ranged',10,1,1,1,'burning incense worth 10+ GP, which the spell consumes','instantaneous',0,1,'You gain the service of a familiar — a spirit in an animal form you choose (Bat, Cat, Frog, Hawk, Lizard, Octopus, Owl, Rat, Raven, Spider, Weasel, or CR 0 Beast). It is a Celestial, Fey, or Fiend (your choice) instead of a Beast. You can communicate telepathically within 100 feet and see/hear through it as a Bonus Action. When casting a touch spell, the familiar can deliver the touch as a Reaction. It can''t attack. When it drops to 0 HP, it disappears until you cast the spell again. You can''t have more than one familiar at a time.',null,null,null,0,null,null,null,null,null,null,'single',null,null,0,1);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_find_steed','Find Steed',2,'conjuration','action','ranged',30,1,1,0,null,'instantaneous',0,0,'You summon an otherworldly being as a loyal steed in an unoccupied space within range (uses the Otherworldly Steed stat block). Choose the steed''s form (horse, camel, dire wolf, elk, etc.) and creature type (Celestial, Fey, or Fiend). In combat, it shares your Initiative and functions as a controlled mount. It disappears at 0 HP or on your death. Using a Higher-Level Spell Slot: Use the slot level for the stat block''s level.',null,null,null,1,null,null,null,null,null,null,'single',null,null,0,0);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_find_the_path','Find the Path',6,'divination','1_minute','self',null,1,1,1,'divination tools worth 100+ GP','concentration_1_day',1,0,'You magically sense the most direct physical route to a named location you are familiar with on the same plane of existence. For the duration, you know the distance and direction to the destination. Whenever you face a choice of paths, you know which is most direct. Fails if you name a destination on another plane, a moving destination, or an unspecific destination.',null,null,null,0,null,null,null,null,null,null,'self',null,null,0,0);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_find_traps','Find Traps',2,'divination','action','ranged',120,1,1,0,null,'instantaneous',0,0,'You sense any trap within range that is within line of sight. A trap includes any object or mechanism created to cause damage or danger (including Alarm or Glyph of Warding, but not natural hazards). This spell reveals that a trap is present but not its exact location. You learn the general nature of the danger posed by each trap you sense.',null,null,null,0,null,null,null,null,null,null,'self',null,null,0,0);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_finger_of_death','Finger of Death',7,'necromancy','action','ranged',60,1,1,0,null,'instantaneous',0,0,'You unleash negative energy toward a creature you can see within range. The target makes a CON save, taking 7d8 + 30 Necrotic damage on a failed save or half on a successful one. A Humanoid killed by this spell rises at the start of your next turn as a Zombie that follows your verbal orders.','d8',7,'necrotic',0,null,null,null,null,'con',null,'single',null,null,1,1);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_fireball','Fireball',3,'evocation','action','ranged',150,1,1,1,'a ball of bat guano and sulfur','instantaneous',0,0,'A bright streak flashes from you to a point within range and blossoms into a fiery explosion. Each creature in a 20-foot-radius Sphere makes a DEX save, taking 8d6 Fire damage on a failed save or half on a successful one. Flammable objects in the area that aren''t worn or carried start burning. Using a Higher-Level Spell Slot: Damage increases by 1d6 per slot level above 3.','d6',8,'fire',1,null,null,null,1,'dex',null,'area','sphere',20,1,1);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_fire_bolt','Fire Bolt',0,'evocation','action','ranged',120,1,1,0,null,'instantaneous',0,0,'You hurl a mote of fire at a creature or object within range. Make a ranged spell attack. On a hit, the target takes 1d10 Fire damage. A flammable object hit starts burning if not worn or carried. Cantrip Upgrade: Damage increases by 1d10 when you reach levels 5 (2d10), 11 (3d10), and 17 (4d10).','d10',1,'fire',1,2,3,4,null,null,'ranged_spell','single',null,null,1,1);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_fire_shield','Fire Shield',4,'evocation','action','self',null,1,1,1,'a bit of phosphorus or a firefly','10_minutes',0,0,'Wispy flames wreathe your body, shedding Bright Light in a 10-foot radius and Dim Light for an additional 10 feet. Choose a warm shield (Resistance to Cold damage) or chill shield (Resistance to Fire damage). Whenever a creature within 5 feet hits you with a melee attack, the shield erupts: attacker takes 2d8 Fire (warm) or 2d8 Cold (chill) damage.','d8',2,'fire',0,null,null,null,null,null,null,'self',null,null,1,1);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_fire_storm','Fire Storm',7,'evocation','action','ranged',150,1,1,0,null,'instantaneous',0,0,'A storm of fire appears in up to ten contiguous 10-foot Cubes you arrange within range. Each creature in the area makes a DEX save, taking 7d10 Fire damage on a failed save or half on a successful one. Flammable objects that aren''t worn or carried start burning.','d10',7,'fire',0,null,null,null,null,'dex',null,'area','cube',10,0,0);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_flame_blade','Flame Blade',2,'evocation','bonus_action','self',null,1,1,1,'a sumac leaf','concentration_10_minutes',1,0,'You evoke a fiery scimitar-sized blade in your free hand. If you let go, it disappears but you can evoke it again as a Bonus Action. As a Magic action, make a melee spell attack with it: on a hit, the target takes 3d6 + spellcasting ability modifier Fire damage. It sheds Bright Light in a 10-foot radius and Dim Light for an additional 10 feet. Using a Higher-Level Spell Slot: Damage increases by 1d6 per slot level above 2.','d6',3,'fire',1,null,null,null,1,null,'melee_spell','single',null,null,0,0);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_flame_strike','Flame Strike',5,'evocation','action','ranged',60,1,1,1,'a pinch of sulfur','instantaneous',0,0,'A vertical column of brilliant fire roars down from above. Each creature in a 10-foot-radius, 40-foot-high Cylinder centered on a point within range makes a DEX save, taking 5d6 Fire damage and 5d6 Radiant damage on a failed save or half as much on a successful one. Using a Higher-Level Spell Slot: Both Fire and Radiant damage increase by 1d6 per slot level above 5.','d6',10,'fire',1,null,null,null,1,'dex',null,'area','cylinder',10,0,0);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_flaming_sphere','Flaming Sphere',2,'conjuration','action','ranged',60,1,1,1,'a ball of wax','concentration_1_minute',1,0,'You create a 5-foot-diameter sphere of fire in an unoccupied space on the ground within range. Any creature that ends its turn within 5 feet makes a DEX save, taking 2d6 Fire damage on a failure or half on a success. As a Bonus Action, you can move the sphere up to 30 feet (rolling along the ground); if it moves into a creature''s space, that creature saves and the sphere stops. It can go over barriers up to 5 feet tall and across pits up to 10 feet wide. Sheds Bright Light 20 feet, Dim Light 20 more. Using a Higher-Level Spell Slot: Damage increases by 1d6 per slot level above 2.','d6',2,'fire',1,null,null,null,1,'dex',null,'single',null,null,1,1);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_flesh_to_stone','Flesh to Stone',6,'transmutation','action','ranged',60,1,1,1,'a cockatrice feather','concentration_1_minute',1,0,'One creature you can see within range makes a CON save (Constructs auto-succeed). On failure, Restrained for the duration; on success, Speed 0 until start of your next turn. A Restrained target makes another CON save at end of each turn: three successes end the spell; three failures cause the Petrified condition for the duration (until ended by Greater Restoration or similar if you maintain Concentration the full duration).',null,null,null,0,null,null,null,null,'con',null,'single',null,null,1,1);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_fly','Fly',3,'transmutation','action','touch',null,1,1,1,'a feather','concentration_10_minutes',1,0,'You touch a willing creature. For the duration, the target gains a Fly Speed of 60 feet and can hover. When the spell ends, the target falls if still aloft unless it can stop the fall. Using a Higher-Level Spell Slot: You can target one additional creature per slot level above 3.',null,null,null,1,null,null,null,null,null,null,'single',null,null,0,1);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_fog_cloud','Fog Cloud',1,'conjuration','action','ranged',120,1,1,0,null,'concentration_1_hour',1,0,'You create a 20-foot-radius Sphere of fog centered on a point within range. The Sphere is Heavily Obscured and lasts for the duration or until a strong wind disperses it. Using a Higher-Level Spell Slot: The fog''s radius increases by 20 feet per slot level above 1.',null,null,null,1,null,null,null,null,null,null,'area','sphere',20,1,1);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_forbiddance','Forbiddance',6,'abjuration','10_minutes','touch',null,1,1,1,'ruby dust worth 1,000+ GP','1_day',0,1,'You create a ward against magical travel covering up to 40,000 square feet of floor to 30 feet high. Creatures can''t teleport into the area or use portals to enter. Choose one or more creature types (Aberrations, Celestials, Elementals, Fey, Fiends, Undead): when such a creature enters or ends its turn in the area, it takes 5d10 Radiant or Necrotic damage (your choice). A password prevents damage. Cast daily for 30 days in the same location and the spell lasts until dispelled.','d10',5,'radiant',0,null,null,null,null,null,null,'area',null,null,0,0);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_forcecage','Forcecage',7,'evocation','action','ranged',100,1,1,1,'ruby dust worth 1,500+ GP, which the spell consumes','concentration_1_hour',1,0,'An Invisible, immobile, Cube-shaped prison of magical force springs into existence. Choose a cage (up to 20 feet per side, 1/2-inch bars 1/2 inch apart) or a solid box (up to 10 feet per side, blocks matter and spells). Any creature completely inside is trapped and can''t leave by nonmagical means. Teleportation requires a CHA save — success allows escape, failure wastes the effect. Extends into the Ethereal Plane. Can''t be dispelled by Dispel Magic.',null,null,null,0,null,null,null,null,'cha',null,'area','cube',20,0,1);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_foresight','Foresight',9,'divination','1_minute','touch',null,1,1,1,'a hummingbird feather','8_hours',0,0,'You touch a willing creature and bestow a limited ability to see the immediate future. For the duration, the target has Advantage on D20 Tests, and other creatures have Disadvantage on attack rolls against it. The spell ends early if you cast it again.',null,null,null,0,null,null,null,null,null,null,'single',null,null,0,1);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_fount_of_moonlight','Fount of Moonlight',4,'evocation','action','self',null,1,1,0,null,'concentration_10_minutes',1,0,'Cool light wreathes your body, emitting Bright Light in a 20-foot radius and Dim Light for an additional 20 feet. For the duration, you have Resistance to Radiant damage and your melee attacks deal an extra 2d6 Radiant damage on a hit. Immediately after taking damage from a creature within 60 feet, you can use a Reaction to force it to make a CON save — on failure, it has the Blinded condition until the end of your next turn.','d6',2,'radiant',0,null,null,null,null,'con',null,'self',null,null,0,0);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_freedom_of_movement','Freedom of Movement',4,'abjuration','action','touch',null,1,1,1,'a leather strap','1_hour',0,0,'You touch a willing creature. For the duration, its movement is unaffected by Difficult Terrain; spells and magical effects can''t reduce its Speed or cause Paralyzed or Restrained conditions; and it gains a Swim Speed equal to its Speed. It can spend 5 feet of movement to automatically escape from nonmagical restraints (manacles, Grappled condition, etc.). Using a Higher-Level Spell Slot: Target one additional creature per slot level above 4.',null,null,null,1,null,null,null,null,null,null,'single',null,null,0,0);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_friends','Friends',0,'enchantment','action','ranged',10,0,1,1,'some makeup','concentration_1_minute',1,0,'You emanate a sense of friendship toward one creature you can see within range. The target must succeed on a WIS save or have the Charmed condition for the duration. Auto-succeeds if not Humanoid, if you''re fighting it, or if you cast this on it in the past 24 hours. The spell ends early if the target takes damage or if you make an attack roll, deal damage, or force anyone to make a save. When the spell ends, the target knows it was Charmed.',null,null,null,0,null,null,null,null,'wis',null,'single',null,null,0,1);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_gaseous_form','Gaseous Form',3,'transmutation','action','touch',null,1,1,1,'a bit of gauze','concentration_1_hour',1,0,'A willing creature you touch shape-shifts into a misty cloud for the duration (along with everything it wears and carries). The spell ends if it drops to 0 HP or takes a Magic action to end it. In this form: Fly Speed 10 feet and can hover; can enter another creature''s space; Resistance to Bludgeoning, Piercing, and Slashing damage; Immunity to Prone; Advantage on STR, DEX, and CON saves; can pass through narrow openings but treats liquids as solid. Can''t talk, manipulate objects, attack, or cast spells. Using a Higher-Level Spell Slot: Target one additional creature per slot level above 3.',null,null,null,1,null,null,null,null,null,null,'single',null,null,0,1);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_gate','Gate',9,'conjuration','action','ranged',60,1,1,1,'a diamond worth 5,000+ GP','concentration_1_minute',1,0,'You conjure a circular portal (5 to 20 feet in diameter, oriented as you choose) linking an unoccupied space within range to a precise location on a different plane. The destination is visible through it. Anything moving through the front is instantly transported to the other plane in the nearest unoccupied space. You can speak the name of a specific creature on another plane — if so, the portal opens next to it and transports it to the nearest unoccupied space on your side. You gain no special power over the creature.',null,null,null,0,null,null,null,null,null,null,'single',null,null,0,1);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_geas','Geas',5,'enchantment','1_minute','ranged',60,1,0,0,null,'30_days',0,0,'You give a verbal command to a creature you can see within range, ordering it to carry out a service or refrain from an action. The target makes a WIS save or has the Charmed condition for the duration (auto-succeeds if it can''t understand your command). While Charmed, the creature takes 5d10 Psychic damage if it acts counter to your command (at most once per day). Remove Curse, Greater Restoration, or Wish ends this spell. Using a Higher-Level Spell Slot: Level 7-8 slot: 365-day duration; level 9 slot: until ended by the above spells.','d10',5,'psychic',1,null,null,null,null,'wis',null,'single',null,null,0,1);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_gentle_repose','Gentle Repose',2,'necromancy','action','touch',null,1,1,1,'2 Copper Pieces, which the spell consumes','10_days',0,1,'You touch a corpse or other remains. For the duration, the target is protected from decay and can''t become Undead. Days spent under this spell''s effect don''t count against the time limit of spells such as Raise Dead.',null,null,null,0,null,null,null,null,null,null,'single',null,null,0,1);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_giant_insect','Giant Insect',4,'conjuration','action','ranged',60,1,1,0,null,'concentration_10_minutes',1,0,'You summon a giant centipede, spider, or wasp in an unoccupied space within range (uses the Giant Insect stat block). It is an ally, shares your Initiative, and takes its turn immediately after yours. It obeys your verbal commands (no action required); if given no commands, it Dodges and avoids danger. It disappears at 0 HP or when the spell ends. Using a Higher-Level Spell Slot: Use the slot level for the stat block''s level.',null,null,null,1,null,null,null,null,null,null,'single',null,null,0,0);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_glibness','Glibness',8,'enchantment','action','self',null,1,0,0,null,'1_hour',0,0,'Until the spell ends, when you make a Charisma check, you can replace the number you roll with a 15. Additionally, no matter what you say, magic that would determine if you are telling the truth indicates that you are being truthful.',null,null,null,0,null,null,null,null,null,null,'self',null,null,0,0);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_globe_of_invulnerability','Globe of Invulnerability',6,'abjuration','action','self',null,1,1,1,'a glass bead','concentration_1_minute',1,0,'An immobile, shimmering barrier appears in a 10-foot Emanation around you. Any spell of level 5 or lower cast from outside the barrier can''t affect anything within it — such spells can target things inside but have no effect. Areas of effect from such spells also exclude the barrier''s interior. Using a Higher-Level Spell Slot: The barrier blocks spells of 1 level higher per slot level above 6.',null,null,null,1,null,null,null,null,null,null,'self','emanation',10,0,1);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_glyph_of_warding','Glyph of Warding',3,'abjuration','1_hour','touch',null,1,1,1,'powdered diamond worth 200+ GP, which the spell consumes','until_dispelled_or_triggered',0,0,'You inscribe a nearly imperceptible glyph on a surface or inside a closeable object (max 10-foot diameter area). Set a trigger condition when cast. Choose Explosive Rune (triggers a 20-foot-radius Sphere: DEX save or 5d8 Acid/Cold/Fire/Lightning/Thunder damage, half on success) or Spell Glyph (store a prepared level 3 or lower spell that targets a single creature or area; activates on trigger targeting the triggering creature). If the surface or object moves more than 10 feet from where cast, the glyph breaks. Using a Higher-Level Spell Slot: Explosive Rune damage increases by 1d8 per slot level above 3; Spell Glyph can store a spell up to the slot level used.','d8',5,'varies',1,null,null,null,1,'dex',null,'area','sphere',20,0,1);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_goodberry','Goodberry',1,'conjuration','action','self',null,1,1,1,'a sprig of mistletoe','24_hours',0,0,'Ten berries appear in your hand infused with magic for the duration. A creature can take a Bonus Action to eat one berry, restoring 1 Hit Point and providing enough nourishment to sustain it for one day. Uneaten berries disappear when the spell ends.',null,null,null,0,null,null,null,null,null,null,'self',null,null,0,0);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_grasping_vine','Grasping Vine',4,'conjuration','bonus_action','ranged',60,1,1,0,null,'concentration_1_minute',1,0,'You conjure a vine sprouting from a surface in an unoccupied space within range. Make a melee spell attack against a creature within 30 feet of the vine: on a hit, 4d8 Bludgeoning damage and the target is pulled up to 30 feet toward the vine; if Huge or smaller, it has the Grappled condition (escape DC = your spell save DC). The vine can grapple one creature at a time. As a Bonus Action on later turns, repeat the attack. Using a Higher-Level Spell Slot: The vine can grapple one additional creature per slot level above 4.','d8',4,'bludgeoning',1,null,null,null,null,null,'melee_spell','single',null,null,0,0);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_grease','Grease',1,'conjuration','action','ranged',60,1,1,1,'a bit of pork rind or butter','1_minute',0,0,'Nonflammable grease covers the ground in a 10-foot square centered on a point within range, turning it into Difficult Terrain for the duration. When the grease appears, each creature standing in its area must succeed on a DEX save or have the Prone condition. A creature that enters the area or ends its turn there must also succeed on that save or fall Prone.',null,null,null,0,null,null,null,null,'dex',null,'area','square',10,1,1);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_greater_invisibility','Greater Invisibility',4,'illusion','action','touch',null,1,1,0,null,'concentration_1_minute',1,0,'A creature you touch has the Invisible condition until the spell ends.',null,null,null,0,null,null,null,null,null,null,'single',null,null,1,1);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_greater_restoration','Greater Restoration',5,'abjuration','action','touch',null,1,1,1,'diamond dust worth 100+ GP, which the spell consumes','instantaneous',0,0,'You touch a creature and magically remove one of the following: 1 Exhaustion level; the Charmed or Petrified condition; a curse (including Attunement to a cursed magic item); any reduction to one of the target''s ability scores; or any reduction to the target''s Hit Point maximum.',null,null,null,0,null,null,null,null,null,null,'single',null,null,0,1);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_green_flame_blade','Green Flame Blade',0,'evocation','action','self',null,0,1,1,'a melee weapon worth at least 1 sp','instantaneous',0,0,'You brandish the weapon used in the casting and make a melee attack with it against one creature within 5 feet of you. On a hit, the target suffers the weapon''s normal effects, and green fire leaps from the target to a different creature of your choice within 5 feet of it. The second creature takes fire damage equal to your spellcasting ability modifier (no damage at cantrip level). At level 5: +1d8 fire to primary target, +1d8 + spellcasting modifier to secondary. At level 11: +2d8 fire to primary, +2d8 + modifier to secondary. At level 17: +3d8 fire to primary, +3d8 + modifier to secondary.','d8',0,'fire',1,1,2,3,null,null,'melee_spell','single',null,null,1,1);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_guardian_of_faith','Guardian of Faith',4,'conjuration','action','ranged',30,1,0,0,null,'8_hours',0,0,'A Large spectral guardian appears and hovers in an unoccupied space within range for the duration. It is invulnerable. Any enemy that moves to within 10 feet of it for the first time on a turn or starts its turn there makes a DEX save, taking 20 Radiant damage on a failure or half on a success. The guardian vanishes after dealing a total of 60 damage.',null,null,'radiant',0,null,null,null,null,'dex',null,'single',null,null,0,0);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_guards_and_wards','Guards and Wards',6,'abjuration','1_hour','touch',null,1,1,1,'a silver rod worth 10+ GP','24_hours',0,0,'You create a protective ward covering up to 2,500 square feet of floor (up to 20 feet tall). You can designate unaffected individuals and a password. The ward creates four effects: Corridors fill with Heavily Obscuring fog with a 50% chance of direction confusion; Doors are magically locked (as Arcane Lock) and up to ten can be disguised as walls; Stairs fill with Webs (regenerate in 10 minutes); and one of: Dancing Lights in four corridors, Magic Mouth in two locations, Stinking Cloud in two locations, Gust of Wind in one corridor, or Suggestion in one 5-foot square. Dispel Magic doesn''t affect the ward itself but can end each effect individually.',null,null,null,0,null,null,null,null,null,null,'area',null,null,0,1);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_guidance','Guidance',0,'divination','action','touch',null,1,1,0,null,'concentration_1_minute',1,0,'You touch a willing creature and choose a skill. Until the spell ends, the creature adds 1d4 to any ability check using the chosen skill.',null,null,null,0,null,null,null,null,null,null,'single',null,null,0,0);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_guiding_bolt','Guiding Bolt',1,'evocation','action','ranged',120,1,1,0,null,'1_round',0,0,'You hurl a bolt of light toward a creature within range. Make a ranged spell attack. On a hit, the target takes 4d6 Radiant damage, and the next attack roll made against it before the end of your next turn has Advantage. Using a Higher-Level Spell Slot: Damage increases by 1d6 per slot level above 1.','d6',4,'radiant',1,null,null,null,1,null,'ranged_spell','single',null,null,1,0);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_gust_of_wind','Gust of Wind',2,'evocation','action','self',null,1,1,1,'a legume seed','concentration_1_minute',1,0,'A Line of strong wind 60 feet long and 10 feet wide blasts from you in a direction you choose. Each creature in the Line must succeed on a STR save or be pushed 15 feet away in the Line''s direction. A creature ending its turn in the Line repeats the save. Moving closer to you in the Line costs 2 feet of movement per 1 foot moved. Disperses gas and vapor; extinguishes unprotected flames; 50% chance to extinguish protected flames. As a Bonus Action on later turns, you can change the direction.',null,null,null,0,null,null,null,null,'str',null,'area','line',60,1,1);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_hail_of_thorns','Hail of Thorns',1,'conjuration','bonus_action','self',null,1,0,0,null,'instantaneous',0,0,'As you hit a creature with a Ranged weapon, this spell creates a rain of thorns. The target and each creature within 5 feet of it make a DEX save, taking 1d10 Piercing damage on a failed save or half on a successful one. Using a Higher-Level Spell Slot: Damage increases by 1d10 per slot level above 1.','d10',1,'piercing',1,null,null,null,1,'dex',null,'area','sphere',5,0,0);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_hallow','Hallow',5,'abjuration','24_hours','touch',null,1,1,1,'incense worth 1,000+ GP, which the spell consumes','until_dispelled',0,0,'You infuse an area (up to 60-foot radius) with holy or unholy power. Choose a creature type (Aberration, Celestial, Elemental, Fey, Fiend, or Undead) — those creatures can''t willingly enter the area and their Charm/Fright effects are suppressed inside. Also choose one extra effect: Courage, Darkness, Daylight, Peaceful Rest, Extradimensional Interference, Fear, Resistance (one damage type), Silence, Tongues, or Vulnerability (one damage type). Fails if the radius overlaps an existing Hallow.',null,null,null,0,null,null,null,null,null,null,'area','sphere',60,0,0);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_hallucinatory_terrain','Hallucinatory Terrain',4,'illusion','10_minutes','ranged',300,1,1,1,'a mushroom','24_hours',0,0,'Natural terrain in a 150-foot Cube within range looks, sounds, and smells like another sort of natural terrain for the duration. Manufactured structures, equipment, and creatures within the area aren''t changed. Tactile characteristics are unchanged. A creature can Study and make an INT (Investigation) check against your spell save DC to disbelieve it; on success it sees a vague image superimposed on the real terrain.',null,null,null,0,null,null,null,null,null,null,'area','cube',150,0,1);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_harm','Harm',6,'necromancy','action','ranged',60,1,1,0,null,'instantaneous',0,0,'You unleash virulent magic on a creature you can see within range. The target makes a CON save. On a failed save, it takes 14d6 Necrotic damage and its Hit Point maximum is reduced by the Necrotic damage taken. On a successful save, it takes half damage only. This spell can''t reduce a target''s HP maximum below 1.','d6',14,'necrotic',0,null,null,null,null,'con',null,'single',null,null,1,0);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_haste','Haste',3,'transmutation','action','ranged',30,1,1,1,'a shaving of licorice root','concentration_1_minute',1,0,'Choose a willing creature within range. Until the spell ends, the target''s Speed is doubled, it gains +2 to AC, has Advantage on DEX saves, and gains an additional action each turn (usable only for Attack (one attack), Dash, Disengage, Hide, or Utilize). When the spell ends, the target is Incapacitated with Speed 0 until the end of its next turn.',null,null,null,0,null,null,null,null,null,null,'single',null,null,1,1);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_heal','Heal',6,'abjuration','action','ranged',60,1,1,0,null,'instantaneous',0,0,'Choose a creature you can see within range. Positive energy restores 70 Hit Points to the target. This spell also ends the Blinded, Deafened, and Poisoned conditions on the target. Using a Higher-Level Spell Slot: The healing increases by 10 for each slot level above 6.',null,null,null,1,null,null,null,null,null,null,'single',null,null,0,0);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_healing_word','Healing Word',1,'abjuration','bonus_action','ranged',60,1,0,0,null,'instantaneous',0,0,'A creature of your choice that you can see within range regains Hit Points equal to 2d4 plus your spellcasting ability modifier. Using a Higher-Level Spell Slot: The healing increases by 2d4 per slot level above 1.',null,null,null,1,null,null,null,null,null,null,'single',null,null,0,0);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_heat_metal','Heat Metal',2,'transmutation','action','ranged',60,1,1,1,'a piece of iron and a flame','concentration_1_minute',1,0,'Choose a manufactured metal object within range. It glows red-hot. Any creature in physical contact takes 2d8 Fire damage when you cast the spell. As a Bonus Action on later turns, deal this damage again while the object is in range. If a creature holding or wearing the object takes the damage, it makes a CON save or drops it. If it doesn''t drop it, it has Disadvantage on attack rolls and ability checks until your next turn. Using a Higher-Level Spell Slot: Damage increases by 1d8 per slot level above 2.','d8',2,'fire',1,null,null,null,1,'con',null,'single',null,null,1,0);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_hellish_rebuke','Hellish Rebuke',1,'evocation','reaction','ranged',60,1,1,0,null,'instantaneous',0,0,'The creature that damaged you is momentarily surrounded by green flames. It makes a DEX save, taking 2d10 Fire damage on a failed save or half on a successful one. Using a Higher-Level Spell Slot: Damage increases by 1d10 per slot level above 1.','d10',2,'fire',1,null,null,null,1,'dex',null,'single',null,null,1,0);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_heroes_feast','Heroes'' Feast',6,'conjuration','10_minutes','self',null,1,1,1,'a gem-encrusted bowl worth 1,000+ GP, which the spell consumes','instantaneous',0,0,'You conjure a feast that appears in an unoccupied 10-foot Cube next to you. It takes 1 hour to consume; benefits don''t set in until then. Up to twelve creatures can partake. Participants gain benefits lasting 24 hours: Resistance to Poison damage; Immunity to the Frightened and Poisoned conditions; Hit Point maximum increases by 2d10 and they gain that many HP.',null,null,null,0,null,null,null,null,null,null,'single',null,null,0,0);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_heroism','Heroism',1,'enchantment','action','touch',null,1,1,0,null,'concentration_1_minute',1,0,'A willing creature you touch is imbued with bravery. Until the spell ends, the creature is immune to the Frightened condition and gains Temporary Hit Points equal to your spellcasting ability modifier at the start of each of its turns. Using a Higher-Level Spell Slot: Target one additional creature per slot level above 1.',null,null,null,1,null,null,null,null,null,null,'single',null,null,0,0);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_hex','Hex',1,'enchantment','bonus_action','ranged',90,1,1,1,'the petrified eye of a newt','concentration_1_hour',1,0,'You place a curse on a creature you can see within range. Until the spell ends, you deal an extra 1d6 Necrotic damage whenever you hit it with an attack roll. Also choose one ability — the target has Disadvantage on ability checks with it. If the target drops to 0 HP before the spell ends, you can Bonus Action to curse a new creature. Using a Higher-Level Spell Slot: Concentration lasts up to 4 hours (level 2), 8 hours (levels 3-4), or 24 hours (level 5+).','d6',1,'necrotic',0,null,null,null,null,null,null,'single',null,null,0,0);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_hold_monster','Hold Monster',5,'enchantment','action','ranged',90,1,1,1,'a straight piece of iron','concentration_1_minute',1,0,'Choose a creature you can see within range. The target must succeed on a WIS save or have the Paralyzed condition for the duration. At the end of each of its turns, the target repeats the save, ending the spell on itself on a success. Using a Higher-Level Spell Slot: Target one additional creature per slot level above 5.',null,null,null,1,null,null,null,1,'wis',null,'single',null,null,1,1);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_hold_person','Hold Person',2,'enchantment','action','ranged',60,1,1,1,'a straight piece of iron','concentration_1_minute',1,0,'Choose a Humanoid you can see within range. The target must succeed on a WIS save or have the Paralyzed condition for the duration. At the end of each of its turns, the target repeats the save, ending the spell on itself on a success. Using a Higher-Level Spell Slot: Target one additional Humanoid per slot level above 2.',null,null,null,1,null,null,null,1,'wis',null,'single',null,null,1,1);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_holy_aura','Holy Aura',8,'abjuration','action','self',null,1,1,1,'a reliquary worth 1,000+ GP','concentration_1_minute',1,0,'For the duration, you emit an aura in a 30-foot Emanation. Creatures of your choice in the aura have Advantage on all saving throws, and other creatures have Disadvantage on attack rolls against them. When a Fiend or Undead hits an affected creature with a melee attack, the attacker must succeed on a CON save or have the Blinded condition until the end of its next turn.',null,null,null,0,null,null,null,null,'con',null,'self','emanation',30,0,0);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_hunger_of_hadar','Hunger of Hadar',3,'conjuration','action','ranged',150,1,1,1,'a pickled tentacle','concentration_1_minute',1,0,'A 20-foot-radius Sphere of Darkness appears centered on a point within range. It is Difficult Terrain, Heavily Obscured, filled with strange whispers (audible 30 feet away), and no light can illuminate it — creatures fully inside have the Blinded condition. Any creature starting its turn in the area takes 2d6 Cold damage. Any creature ending its turn there makes a DEX save or takes 2d6 Acid damage from tentacles. Using a Higher-Level Spell Slot: The Cold or Acid damage (your choice) increases by 1d6 per slot level above 3.','d6',2,'cold',1,null,null,null,1,'dex',null,'area','sphere',20,0,0);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_hunters_mark','Hunter''s Mark',1,'divination','bonus_action','ranged',90,1,0,0,null,'concentration_1_hour',1,0,'You mark one creature you can see within range as your quarry. Until the spell ends, you deal an extra 1d6 Force damage whenever you hit it with an attack roll. You also have Advantage on WIS (Perception or Survival) checks to find it. If it drops to 0 HP before the spell ends, you can Bonus Action to move the mark to a new creature within range. Using a Higher-Level Spell Slot: Concentration lasts up to 8 hours (levels 3-4) or 24 hours (level 5+).','d6',1,'force',0,null,null,null,null,null,null,'single',null,null,0,0);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_hypnotic_pattern','Hypnotic Pattern',3,'illusion','action','ranged',120,0,1,1,'a pinch of confetti','concentration_1_minute',1,0,'You create a twisting pattern of colors in a 30-foot Cube within range that appears for a moment then vanishes. Each creature in the area that can see the pattern must succeed on a WIS save or have the Charmed condition. While Charmed, the creature has the Incapacitated condition and Speed 0. The spell ends for an affected creature if it takes any damage or if someone uses an action to shake it out of its stupor.',null,null,null,0,null,null,null,null,'wis',null,'area','cube',30,1,1);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_ice_knife','Ice Knife',1,'conjuration','action','ranged',60,0,1,1,'a drop of water or a piece of ice','instantaneous',0,0,'You create a shard of ice and fling it at one creature within range. Make a ranged spell attack — on a hit, the target takes 1d10 Piercing damage. Hit or miss, the shard then explodes: the target and each creature within 5 feet must succeed on a DEX save or take 2d6 Cold damage. Using a Higher-Level Spell Slot: The Cold damage increases by 1d6 per slot level above 1.','d6',2,'cold',1,null,null,null,1,'dex','ranged_spell','area','sphere',5,1,1);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_ice_storm','Ice Storm',4,'evocation','action','ranged',300,1,1,1,'a mitten','instantaneous',0,0,'Hail falls in a 20-foot-radius, 40-foot-high Cylinder centered on a point within range. Each creature in the Cylinder makes a DEX save, taking 2d10 Bludgeoning damage and 4d6 Cold damage on a failed save or half as much on a successful one. Hailstones turn the ground in the Cylinder into Difficult Terrain until the end of your next turn. Using a Higher-Level Spell Slot: The Bludgeoning damage increases by 1d10 per slot level above 4.','d10',2,'bludgeoning',1,null,null,null,1,'dex',null,'area','cylinder',20,1,1);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_identify','Identify',1,'divination','1_minute','touch',null,1,1,1,'a pearl worth 100+ GP','instantaneous',0,1,'You touch an object throughout the casting. If it is a magic item or magical object, you learn its properties and how to use them, whether it requires Attunement, and how many charges it has. You learn whether ongoing spells affect it and what they are. If it was created by a spell, you learn that spell''s name. Alternatively, touching a creature reveals which ongoing spells currently affect it.',null,null,null,0,null,null,null,null,null,null,'single',null,null,0,1);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_illusory_script','Illusory Script',1,'illusion','1_minute','touch',null,0,1,1,'ink worth 10+ GP, which the spell consumes','10_days',0,1,'You write on a suitable material and imbue it with an illusion. To you and designated creatures, the writing appears normal and conveys your intended meaning. To all others, it appears as unintelligible unknown or magical script (or you can alter its meaning, handwriting, and language to another language you know). If dispelled, both the original and illusion disappear. A creature with Truesight can read the hidden message.',null,null,null,0,null,null,null,null,null,null,'single',null,null,0,1);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_imprisonment','Imprisonment',9,'abjuration','1_minute','ranged',30,1,1,1,'a statuette of the target worth 5,000+ GP','until_dispelled',0,0,'You create a magical restraint on a creature you can see within range. The target makes a WIS save — on success, it is unaffected and immune to this spell for 24 hours. On failure, it is imprisoned and doesn''t need to breathe, eat, or drink; doesn''t age; can''t be located by Divination or teleport. Choose one effect: Burial (entombed in a hollow magical globe), Chaining (Restrained by immovable chains), Hedged Prison (trapped in a demiplane), Minimus Containment (1 inch tall inside a gemstone), or Slumber (Unconscious, can''t be woken). When cast, specify a trigger to end it (DM must agree it could happen within a decade). Dispel Magic ends it only with a level 9 slot.',null,null,null,0,null,null,null,null,'wis',null,'single',null,null,0,1);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_incendiary_cloud','Incendiary Cloud',8,'conjuration','action','ranged',150,1,1,0,null,'concentration_1_minute',1,0,'A swirling cloud of embers and smoke fills a 20-foot-radius Sphere within range. The area is Heavily Obscured. When the cloud appears, each creature in it makes a DEX save, taking 10d8 Fire damage on a failure or half on a success. A creature also makes this save when the Sphere moves into its space or when it enters or ends its turn there (once per turn). The cloud moves 10 feet away from you in a direction you choose at the start of each of your turns. Strong wind disperses it.','d8',10,'fire',0,null,null,null,null,'dex',null,'area','sphere',20,1,1);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_inflict_wounds','Inflict Wounds',1,'necromancy','action','touch',null,1,1,0,null,'instantaneous',0,0,'A creature you touch makes a CON saving throw, taking 2d10 Necrotic damage on a failed save or half as much on a successful one. Using a Higher-Level Spell Slot: The damage increases by 1d10 per slot level above 1.','d10',2,'necrotic',1,null,null,null,1,'con',null,'single',null,null,1,0);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_insect_plague','Insect Plague',5,'conjuration','action','ranged',300,1,1,1,'a locust','concentration_10_minutes',1,0,'Swarming locusts fill a 20-foot-radius Sphere centered on a point within range. The area is Lightly Obscured and Difficult Terrain. When the swarm appears, each creature in it makes a CON save, taking 4d10 Piercing damage on a failure or half on a success. A creature also saves when it enters the area for the first time on a turn or ends its turn there (once per turn). Using a Higher-Level Spell Slot: Damage increases by 1d10 per slot level above 5.','d10',4,'piercing',1,null,null,null,1,'con',null,'area','sphere',20,0,0);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_invisibility','Invisibility',2,'illusion','action','touch',null,1,1,1,'an eyelash in gum arabic','concentration_1_hour',1,0,'A creature you touch has the Invisible condition until the spell ends. The spell ends early immediately after the target makes an attack roll, deals damage, or casts a spell. Using a Higher-Level Spell Slot: You can target one additional creature per slot level above 2.',null,null,null,1,null,null,null,null,null,null,'single',null,null,1,1);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_jallarzis_storm_of_radiance','Jallarzi''s Storm of Radiance',5,'evocation','action','ranged',120,1,1,1,'a pinch of phosphorus','concentration_1_minute',1,0,'You unleash a storm of flashing light and raging thunder in a 10-foot-radius, 40-foot-high Cylinder centered on a point within range. While in this area, creatures have the Blinded and Deafened conditions and can''t cast spells with a Verbal component. When the storm appears, each creature in it makes a CON save, taking 2d10 Radiant and 2d10 Thunder damage on a failure or half on a success. A creature also saves when it enters the area for the first time on a turn or ends its turn there (once per turn). Using a Higher-Level Spell Slot: Both damage types increase by 1d10 per slot level above 5.','d10',4,'radiant',1,null,null,null,1,'con',null,'area','cylinder',10,1,1);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_jump','Jump',1,'transmutation','bonus_action','touch',null,1,1,1,'a grasshopper''s hind leg','1_minute',0,0,'You touch a willing creature. Once on each of its turns until the spell ends, that creature can jump up to 30 feet by spending 10 feet of movement. Using a Higher-Level Spell Slot: You can target one additional creature per slot level above 1.',null,null,null,1,null,null,null,null,null,null,'single',null,null,0,1);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_knock','Knock',2,'transmutation','action','ranged',60,1,0,0,null,'instantaneous',0,0,'Choose an object you can see within range (door, box, chest, manacles, padlock, or similar). A target held shut by a mundane lock, stuck, or barred becomes unlocked, unstuck, or unbarred (only one lock per casting). If held by Arcane Lock, that spell is suppressed for 10 minutes. When cast, a loud knock audible up to 300 feet away emanates from the target.',null,null,null,0,null,null,null,null,null,null,'single',null,null,0,1);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_legend_lore','Legend Lore',5,'divination','10_minutes','self',null,1,1,1,'incense worth 250+ GP (consumed) and four ivory strips worth 50+ GP each','instantaneous',0,0,'Name or describe a famous person, place, or object. The spell brings to your mind a brief summary of significant lore about it as described by the DM. The lore may include important details, amusing revelations, or secret lore. The more you already know, the more precise the information. It is accurate but may be couched in figurative language or poetry. If the thing isn''t actually famous, the spell fails.',null,null,null,0,null,null,null,null,null,null,'self',null,null,0,1);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_leomunds_secret_chest','Leomund''s Secret Chest',4,'conjuration','action','touch',null,1,1,1,'a chest (3x2x2 ft) of rare materials worth 5,000+ GP and a Tiny replica of the same materials worth 50+ GP','until_dispelled',0,0,'You hide a chest (up to 12 cubic feet of nonliving material) and all its contents on the Ethereal Plane by touching the chest and its miniature replica. You can take a Magic action to touch the replica and recall the chest (appears within 5 feet) or send it back. After 60 days, 5% cumulative chance per day the spell ends. Also ends if you cast it again or the replica is destroyed.',null,null,null,0,null,null,null,null,null,null,'single',null,null,0,1);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_leomunds_tiny_hut','Leomund''s Tiny Hut',3,'evocation','1_minute','self',null,1,1,1,'a crystal bead','8_hours',0,1,'A 10-foot Emanation springs into existence around you and remains stationary. Creatures and objects inside when cast can move through it freely; all others are barred. Spells of level 3 or lower can''t be cast through it and their effects can''t extend into it. The atmosphere inside is comfortable and dry. You can command the interior lighting (Dim Light or Darkness, no action). Opaque from outside, transparent from inside. Ends early if you leave or cast it again.',null,null,null,0,null,null,null,null,null,null,'self','emanation',10,0,1);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_lesser_restoration','Lesser Restoration',2,'abjuration','bonus_action','touch',null,1,1,0,null,'instantaneous',0,0,'You touch a creature and end one condition on it: Blinded, Deafened, Paralyzed, or Poisoned.',null,null,null,0,null,null,null,null,null,null,'single',null,null,0,0);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_levitate','Levitate',2,'transmutation','action','ranged',60,1,1,1,'a metal spring','concentration_10_minutes',1,0,'One creature or loose object (up to 500 pounds) you can see within range rises vertically up to 20 feet and remains suspended. An unwilling creature that succeeds on a CON save is unaffected. The target can move by pushing or pulling against fixed surfaces. You can change the target''s altitude up to 20 feet per turn (Magic action if not self). When the spell ends, the target floats gently to the ground if still aloft.',null,null,null,0,null,null,null,null,'con',null,'single',null,null,1,1);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_light','Light',0,'evocation','action','touch',null,1,0,1,'a firefly or phosphorescent moss','1_hour',0,0,'You touch one Large or smaller object that isn''t being worn or carried. Until the spell ends, the object sheds Bright Light in a 20-foot radius and Dim Light for an additional 20 feet. The light can be colored as you like. Covering the object with something opaque blocks the light. The spell ends if you cast it again.',null,null,null,0,null,null,null,null,null,null,'single',null,null,0,1);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_lightning_arrow','Lightning Arrow',3,'transmutation','bonus_action','self',null,1,1,0,null,'instantaneous',0,0,'As your ranged attack hits or misses, the weapon or ammunition transforms into a lightning bolt. Instead of normal damage, the target takes 4d8 Lightning damage on a hit or half on a miss. Each creature within 10 feet of the target then makes a DEX save, taking 2d8 Lightning damage on a failure or half on a success. The weapon or ammunition returns to normal. Using a Higher-Level Spell Slot: Both damage effects increase by 1d8 per slot level above 3.','d8',4,'lightning',1,null,null,null,1,'dex',null,'area','sphere',10,0,0);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_lightning_bolt','Lightning Bolt',3,'evocation','action','self',null,1,1,1,'a bit of fur and a crystal rod','instantaneous',0,0,'A stroke of lightning forming a 100-foot-long, 5-foot-wide Line blasts from you in a direction you choose. Each creature in the Line makes a DEX save, taking 8d6 Lightning damage on a failed save or half on a successful one. Using a Higher-Level Spell Slot: Damage increases by 1d6 per slot level above 3.','d6',8,'lightning',1,null,null,null,1,'dex',null,'area','line',100,1,1);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_locate_animals_or_plants','Locate Animals or Plants',2,'divination','action','self',null,1,1,1,'fur from a bloodhound','instantaneous',0,1,'Describe or name a specific kind of Beast, Plant creature, or nonmagical plant. You learn the direction and distance to the closest creature or plant of that kind within 5 miles, if any are present.',null,null,null,0,null,null,null,null,null,null,'self',null,null,0,0);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_locate_creature','Locate Creature',4,'divination','action','self',null,1,1,1,'fur from a bloodhound','concentration_1_hour',1,0,'Describe or name a familiar creature. If it is within 1,000 feet, you sense its direction; if moving, you know the direction of movement. Can locate a specific known creature or the nearest of a specific kind (must have seen it within 30 feet). Doesn''t locate a creature in a different form (e.g. Petrified or Polymorphed). Can''t locate through lead.',null,null,null,0,null,null,null,null,null,null,'self',null,null,0,1);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_locate_object','Locate Object',2,'divination','action','self',null,1,1,1,'a forked twig','concentration_10_minutes',1,0,'Describe or name a familiar object. If it is within 1,000 feet, you sense its direction; if moving, you know the direction of movement. Can locate a specific known object (must have seen it within 30 feet) or the nearest of a particular kind. Can''t locate through lead.',null,null,null,0,null,null,null,null,null,null,'self',null,null,0,1);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_longstrider','Longstrider',1,'transmutation','action','touch',null,1,1,1,'a pinch of dirt','1_hour',0,0,'You touch a creature. The target''s Speed increases by 10 feet until the spell ends. Using a Higher-Level Spell Slot: You can target one additional creature per slot level above 1.',null,null,null,1,null,null,null,null,null,null,'single',null,null,0,1);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_mage_armor','Mage Armor',1,'abjuration','action','touch',null,1,1,1,'a piece of cured leather','8_hours',0,0,'You touch a willing creature who isn''t wearing armor. Until the spell ends, the target''s base AC becomes 13 plus its Dexterity modifier. The spell ends early if the target dons armor.',null,null,null,0,null,null,null,null,null,null,'single',null,null,1,1);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_mage_hand','Mage Hand',0,'conjuration','action','ranged',30,1,1,0,null,'1_minute',0,0,'A spectral floating hand appears at a point within range and lasts for the duration (vanishes if more than 30 feet from you or if you cast this spell again). When cast and as a Magic action on later turns, you can use the hand to manipulate an object, open an unlocked door or container, stow or retrieve an item from an open container, or pour the contents out of a vial. As part of the Magic action, you can move the hand up to 30 feet. The hand can''t attack, activate magic items, or carry more than 10 pounds.',null,null,null,0,null,null,null,null,null,null,'single',null,null,0,1);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_magic_circle','Magic Circle',3,'abjuration','1_minute','ranged',10,1,1,1,'salt and powdered silver worth 100+ GP, which the spell consumes','1_hour',0,0,'You create a 10-foot-radius, 20-foot-tall Cylinder of magical energy on a point on the ground within range. Choose one or more creature types (Celestials, Elementals, Fey, Fiends, or Undead). Those creatures can''t willingly enter the Cylinder by nonmagical means (teleportation requires a CHA save), have Disadvantage on attack rolls against targets inside, and can''t possess or Charm/Frighten targets inside. You can reverse the circle''s direction to prevent chosen creatures from leaving. Using a Higher-Level Spell Slot: Duration increases by 1 hour per slot level above 3.',null,null,null,1,null,null,null,null,'cha',null,'area','cylinder',10,0,1);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_magic_jar','Magic Jar',6,'necromancy','1_minute','self',null,1,1,1,'a gem, crystal, or reliquary worth 500+ GP','until_dispelled',0,0,'Your soul leaves your body (which falls catatonic) and enters the container. From it, you can project your soul up to 100 feet to return to your body (ending the spell) or attempt to possess a Humanoid within 100 feet (CHA save — failure traps their soul in the container; success grants 24-hour immunity). While possessing a body, you control it and replace its physical stats with your own mental ones. You can return to the container as a Magic action if within 100 feet. If the host dies while you''re in it, you make a CHA save or die. If the container is destroyed, your soul returns to your body or you die.',null,null,null,0,null,null,null,null,'cha',null,'single',null,null,0,1);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_magic_missile','Magic Missile',1,'evocation','action','ranged',120,1,1,0,null,'instantaneous',0,0,'You create three glowing darts of magical force. Each dart strikes a creature of your choice that you can see within range, dealing 1d4 + 1 Force damage. The darts all strike simultaneously, and you can direct them to hit one creature or several. Using a Higher-Level Spell Slot: The spell creates one more dart per slot level above 1.','d4',3,'force',1,null,null,null,null,null,null,'multiple',null,null,1,1);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_magic_mouth','Magic Mouth',2,'illusion','1_minute','ranged',30,1,1,1,'jade dust worth 10+ GP, which the spell consumes','until_dispelled',0,1,'You implant a message of 25 words or fewer within an object in range, to be uttered when a trigger condition is met. A magical mouth appears on the object and recites the message in your voice when triggered. The trigger must be based on visual or audible conditions within 30 feet. You can have the spell end after delivery or repeat on each trigger.',null,null,null,0,null,null,null,null,null,null,'single',null,null,0,1);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_magic_weapon','Magic Weapon',2,'transmutation','bonus_action','touch',null,1,1,0,null,'1_hour',0,0,'You touch a nonmagical weapon. Until the spell ends, it becomes a magic weapon with a +1 bonus to attack rolls and damage rolls. Ends early if you cast it again. Using a Higher-Level Spell Slot: +2 bonus with a level 3-5 slot; +3 bonus with a level 6+ slot.',null,null,null,1,null,null,null,null,null,null,'single',null,null,0,1);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_major_image','Major Image',3,'illusion','action','ranged',120,1,1,1,'a bit of fleece','concentration_10_minutes',1,0,'You create an image of an object, creature, or phenomenon no larger than a 20-foot Cube at a spot within range. It appears real, including sounds, smells, and temperature, but can''t deal damage or cause conditions. You can take a Magic action to move it anywhere within range and alter its appearance naturally. Physical interaction reveals the illusion; a creature can Study and make an INT (Investigation) check against your save DC to disbelieve it. Using a Higher-Level Spell Slot: The spell lasts until dispelled without Concentration if cast with a level 4+ slot.',null,null,null,1,null,null,null,null,null,null,'single',null,null,0,1);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_mass_cure_wounds','Mass Cure Wounds',5,'abjuration','action','ranged',60,1,1,0,null,'instantaneous',0,0,'A wave of healing energy washes from a point within range. Choose up to six creatures in a 30-foot-radius Sphere centered on that point. Each target regains Hit Points equal to 5d8 plus your spellcasting ability modifier. Using a Higher-Level Spell Slot: Healing increases by 1d8 per slot level above 5.',null,null,null,1,null,null,null,null,null,null,'area','sphere',30,0,0);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_mass_heal','Mass Heal',9,'abjuration','action','ranged',60,1,1,0,null,'instantaneous',0,0,'A flood of healing energy flows from you. You restore up to 700 Hit Points, divided as you choose among any number of creatures you can see within range. Creatures healed also have the Blinded, Deafened, and Poisoned conditions removed.',null,null,null,0,null,null,null,null,null,null,'multiple',null,null,0,0);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_mass_healing_word','Mass Healing Word',3,'abjuration','bonus_action','ranged',60,1,0,0,null,'instantaneous',0,0,'Up to six creatures of your choice you can see within range regain Hit Points equal to 2d4 plus your spellcasting ability modifier. Using a Higher-Level Spell Slot: Healing increases by 1d4 per slot level above 3.',null,null,null,1,null,null,null,null,null,null,'multiple',null,null,0,0);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_mass_suggestion','Mass Suggestion',6,'enchantment','action','ranged',60,1,0,1,'a snake''s tongue','24_hours',0,0,'You suggest a course of activity (25 words or fewer) to up to twelve creatures you can see within range that can hear and understand you. The suggestion must sound achievable and not obviously harmful. Each target must succeed on a WIS save or have the Charmed condition for the duration (or until you or allies damage the target). Each Charmed target pursues the suggestion to the best of its ability. Using a Higher-Level Spell Slot: Duration extends to 10 days (level 7), 30 days (level 8), or 366 days (level 9).',null,null,null,1,null,null,null,null,'wis',null,'multiple',null,null,0,1);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_maze','Maze',8,'conjuration','action','ranged',60,1,1,0,null,'concentration_10_minutes',1,0,'You banish a creature you can see within range into a labyrinthine demiplane for the duration or until it escapes. The target can take a Study action to make a DC 20 INT (Investigation) check to escape. When the spell ends, the target reappears in the space it left or the nearest unoccupied space.',null,null,null,0,null,null,null,null,null,null,'single',null,null,1,1);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_meld_into_stone','Meld into Stone',3,'transmutation','action','touch',null,1,1,0,null,'8_hours',0,1,'You step into a stone object or surface large enough to fully contain your body, merging with the stone for the duration. Nothing of your presence is detectable by nonmagical senses. While merged: can''t see outside; Disadvantage on WIS (Perception) checks to hear; can cast spells on yourself; can use 5 feet of movement to leave where you entered (ending the spell). Minor damage doesn''t harm you, but partial destruction or reshaping expels you and deals 6d6 Force damage; complete destruction expels you and deals 50 Force damage.',null,null,null,0,null,null,null,null,null,null,'single',null,null,0,0);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_melfs_acid_arrow','Melf''s Acid Arrow',2,'evocation','action','ranged',90,1,1,1,'powdered rhubarb leaf','instantaneous',0,0,'A shimmering green arrow streaks toward a target within range and bursts in acid. Make a ranged spell attack. On a hit, the target takes 4d4 Acid damage and 2d4 Acid damage at the end of its next turn. On a miss, the arrow splashes the target for half the initial damage only. Using a Higher-Level Spell Slot: Both the initial and later damage increase by 1d4 per slot level above 2.','d4',4,'acid',1,null,null,null,1,null,'ranged_spell','single',null,null,1,1);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_mending','Mending',0,'transmutation','1_minute','touch',null,1,1,1,'two lodestones','instantaneous',0,0,'This spell repairs a single break or tear in an object you touch (broken chain link, torn cloak, leaking wineskin, etc.) as long as the break or tear is no larger than 1 foot in any dimension, leaving no trace of the former damage. This spell can physically repair a magic item but can''t restore its magic.',null,null,null,0,null,null,null,null,null,null,'single',null,null,0,1);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_message','Message',0,'transmutation','action','ranged',120,0,1,1,'a copper wire','1_round',0,0,'You point toward a creature within range and whisper a message. Only the target hears it and can reply in a whisper only you hear. You can cast this spell through solid objects if you are familiar with the target and know it is beyond the barrier. Blocked by magical silence, 1 foot of stone/metal/wood, or a thin sheet of lead.',null,null,null,0,null,null,null,null,null,null,'single',null,null,0,1);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_meteor_swarm','Meteor Swarm',9,'evocation','action','special',5280,1,1,0,null,'instantaneous',0,0,'Blazing orbs of fire plummet to four different points you can see within range. Each creature in a 40-foot-radius Sphere centered on each of those points makes a DEX save, taking 20d6 Fire damage and 20d6 Bludgeoning damage on a failure or half on a success. A creature in more than one Sphere is affected only once. Nonmagical objects in the area also take the damage and start burning if flammable.','d6',40,'fire',0,null,null,null,null,'dex',null,'area','sphere',40,1,1);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_mind_blank','Mind Blank',8,'abjuration','action','touch',null,1,1,0,null,'24_hours',0,0,'Until the spell ends, one willing creature you touch has Immunity to Psychic damage and the Charmed condition. The target is also unaffected by anything that would sense its emotions or alignment, read its thoughts, or magically detect its location. No spell — not even Wish — can gather information about the target, observe it remotely, or control its mind.',null,null,null,0,null,null,null,null,null,null,'single',null,null,0,1);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_mind_sliver','Mind Sliver',0,'enchantment','action','ranged',60,1,0,0,null,'1_round',0,0,'One creature you can see within range must succeed on an INT save or take 1d6 Psychic damage and subtract 1d4 from the next saving throw it makes before the end of your next turn. Cantrip Upgrade: Damage increases by 1d6 when you reach levels 5 (2d6), 11 (3d6), and 17 (4d6).','d6',1,'psychic',1,2,3,4,null,'int',null,'single',null,null,1,1);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_mind_spike','Mind Spike',2,'divination','action','ranged',120,0,1,0,null,'concentration_1_hour',1,0,'You drive a spike of psionic energy into one creature you can see within range. The target makes a WIS save, taking 3d8 Psychic damage on a failure or half on a success. On a failed save, you also always know the target''s location (while on the same plane) until the spell ends — the target can''t become hidden from you and gains no benefit from the Invisible condition against you. Using a Higher-Level Spell Slot: Damage increases by 1d8 per slot level above 2.','d8',3,'psychic',1,null,null,null,1,'wis',null,'single',null,null,1,1);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_minor_illusion','Minor Illusion',0,'illusion','action','ranged',30,0,1,1,'a bit of fleece','1_minute',0,0,'You create a sound or an image of an object within range. Sound: any volume from whisper to scream, any sound you choose, continuous or discrete. Image: an object no larger than a 5-foot Cube — can''t produce sensory effects. Physical interaction reveals the illusion. A creature can Study and make an INT (Investigation) check against your spell save DC to disbelieve it. Casting again ends the spell.',null,null,null,0,null,null,null,null,null,null,'single',null,null,0,1);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_mirage_arcane','Mirage Arcane',7,'illusion','10_minutes','special',null,1,1,0,null,'10_days',0,0,'You make terrain in an area up to 1 mile square look, sound, smell, and feel like some other sort of natural terrain or add structures. The illusion includes audible, visual, tactile, and olfactory elements and can create Difficult Terrain or remove it. Illusory pieces removed from the area disappear immediately. Creatures with Truesight can see the true terrain but still physically interact with the illusion.',null,null,null,0,null,null,null,null,null,null,'area',null,null,0,1);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_mirror_image','Mirror Image',2,'illusion','action','self',null,1,1,0,null,'1_minute',0,0,'Three illusory duplicates of yourself appear in your space and move with you. Each time a creature hits you with an attack roll, roll a d6 for each remaining duplicate — on a 3 or higher, one duplicate is hit instead of you and is destroyed. Duplicates ignore all other damage and effects. The spell ends when all three are destroyed. Unaffected by creatures with the Blinded condition, Blindsight, or Truesight.',null,null,null,0,null,null,null,null,null,null,'self',null,null,1,1);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_mislead','Mislead',5,'illusion','action','self',null,0,1,0,null,'concentration_1_hour',1,0,'You gain the Invisible condition and an illusory double of you appears where you are standing. The invisibility ends immediately after you make an attack roll, deal damage, or cast a spell. As a Magic action, you can move the double up to twice your Speed and make it gesture, speak, and behave in any way you choose. It is intangible and invulnerable. You can see through its eyes and hear through its ears as if you were in its location.',null,null,null,0,null,null,null,null,null,null,'self',null,null,0,1);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_misty_step','Misty Step',2,'conjuration','bonus_action','self',null,1,0,0,null,'instantaneous',0,0,'Briefly surrounded by silvery mist, you teleport up to 30 feet to an unoccupied space you can see.',null,null,null,0,null,null,null,null,null,null,'self',null,null,1,1);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_modify_memory','Modify Memory',5,'enchantment','action','ranged',30,1,1,0,null,'concentration_1_minute',1,0,'One creature you can see within range makes a WIS save (Advantage if you''re fighting it). On a failed save, the target has the Charmed and Incapacitated conditions and is unaware of its surroundings (can hear you). While Charmed, you can affect its memory of an event in the last 24 hours (up to 10 minutes long): eliminate it, restore perfect clarity, change details, or implant a false memory. Speak the changes; the target must understand you. Using a Higher-Level Spell Slot: Alter memories up to 7 days (6), 30 days (7), 365 days (8), or any time in its past (9).',null,null,null,1,null,null,null,null,'wis',null,'single',null,null,0,1);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_moonbeam','Moonbeam',2,'evocation','action','ranged',120,1,1,1,'a moonseed leaf','concentration_1_minute',1,0,'A silvery beam of pale light shines down in a 5-foot-radius, 40-foot-high Cylinder within range, filling it with Dim Light. You can take a Magic action on later turns to move the Cylinder up to 60 feet. When the Cylinder appears and when a creature enters or ends its turn there (once per turn), it makes a CON save: on failure, 2d10 Radiant damage and if shape-shifted it reverts to its true form and can''t shape-shift until it leaves; on success, half damage only. Using a Higher-Level Spell Slot: Damage increases by 1d10 per slot level above 2.','d10',2,'radiant',1,null,null,null,1,'con',null,'area','cylinder',5,0,0);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_mordenkainens_faithful_hound','Mordenkainen''s Faithful Hound',4,'conjuration','action','ranged',30,1,1,1,'a silver whistle','8_hours',0,0,'You conjure a phantom watchdog in an unoccupied space within range. Only you can see it; it is intangible and invulnerable. It has Truesight 30 feet. When a Small or larger creature comes within 30 feet without speaking the password, it starts barking loudly. At the start of each of your turns, it bites one enemy within 5 feet: DEX save or 4d8 Force damage. As a Magic action on later turns, you can move it up to 30 feet. Vanishes if more than 300 feet from you.','d8',4,'force',0,null,null,null,null,'dex',null,'single',null,null,0,1);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_mordenkainens_magnificent_mansion','Mordenkainen''s Magnificent Mansion',7,'conjuration','1_minute','ranged',300,1,1,1,'a miniature door worth 15+ GP','24_hours',0,0,'You conjure a shimmering door leading to an extradimensional dwelling (up to 50 contiguous 10-foot Cubes, furnished as you choose) that lasts for the duration. You and designated creatures can enter while the door is open. You can open or close it (no action) within 30 feet; while closed it is imperceptible. The dwelling contains food for a nine-course banquet for 100 people and is staffed by 100 near-transparent servants who obey your commands but can''t leave or attack. When the spell ends, creatures and objects inside are expelled to the nearest unoccupied spaces.',null,null,null,0,null,null,null,null,null,null,'single',null,null,0,1);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_mordenkainens_private_sanctum','Mordenkainen''s Private Sanctum',4,'abjuration','10_minutes','ranged',120,1,1,1,'a thin sheet of lead','24_hours',0,0,'You make a Cube (5 to 100 feet per side) within range magically secure for the duration. Choose any combination of properties: sound can''t pass through the barrier; the barrier appears dark and foggy (blocking all vision including Darkvision); Divination sensors can''t appear inside or pass through the perimeter; creatures inside can''t be targeted by Divination spells; nothing can teleport into or out; planar travel is blocked inside. Casting daily for 365 days in the same spot makes it permanent until dispelled. Using a Higher-Level Spell Slot: Cube size increases by 100 feet per slot level above 4.',null,null,null,1,null,null,null,null,null,null,'area','cube',100,0,1);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_mordenkainens_sword','Mordenkainen''s Sword',7,'evocation','action','ranged',90,1,1,1,'a miniature sword worth 250+ GP','concentration_1_minute',1,0,'You create a spectral sword that hovers within range. When it appears, make a melee spell attack against a target within 5 feet: on a hit, 4d12 + spellcasting modifier Force damage. On later turns, take a Bonus Action to move the sword up to 30 feet and repeat the attack against the same or a different target.','d12',4,'force',0,null,null,null,null,null,'melee_spell','single',null,null,1,1);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_move_earth','Move Earth',6,'transmutation','action','ranged',120,1,1,1,'a miniature shovel','concentration_2_hours',1,0,'Choose an area of terrain no larger than 40 feet on a side within range. You can reshape dirt, sand, or clay in any manner for the duration: raise/lower elevation, create/fill trenches, erect/flatten walls, or form pillars. Changes can''t exceed half the area''s largest dimension. Takes 10 minutes per change. Creatures can''t usually be trapped by the slow movement. Every 10 minutes you can choose a new area within range. Can''t manipulate natural stone or stone construction.',null,null,null,0,null,null,null,null,null,null,'area',null,40,0,1);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_nondetection','Nondetection',3,'abjuration','action','touch',null,1,1,1,'a pinch of diamond dust worth 25+ GP, which the spell consumes','8_hours',0,0,'For the duration, you hide a target you touch from Divination spells. The target can be a willing creature, or a place or object no larger than 10 feet in any dimension. The target can''t be targeted by any Divination spell or perceived through magical scrying sensors.',null,null,null,0,null,null,null,null,null,null,'single',null,null,0,1);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_nystuls_magic_aura','Nystul''s Magic Aura',2,'illusion','action','touch',null,1,1,1,'a small square of silk','24_hours',0,0,'You place an illusion on a willing creature or an uncarried object. A creature gains the Mask effect (choose a creature type — spells treat it as that type). An object gains the False Aura effect (change how it appears to magical detection: make it seem magical, nonmagical, or of a different school). The effect lasts 24 hours. Casting daily on the same target for 30 days makes the illusion last until dispelled.',null,null,null,0,null,null,null,null,null,null,'single',null,null,0,1);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_otilukes_freezing_sphere','Otiluke''s Freezing Sphere',6,'evocation','action','ranged',300,1,1,1,'a miniature crystal sphere','instantaneous',0,0,'A frigid globe explodes in a 60-foot-radius Sphere at a point within range. Each creature makes a CON save, taking 10d6 Cold damage on a failure or half on a success. If it strikes water, it freezes a 30-foot-square area 6 inches deep for 1 minute; swimming creatures are Restrained (STR Athletics check to break free). Alternatively, you can hold the globe as a sling-bullet-sized object to throw (range 40 feet) or use in a sling — it shatters on impact with the same effect, or explodes after 1 minute if not shattered. Using a Higher-Level Spell Slot: Damage increases by 1d6 per slot level above 6.','d6',10,'cold',1,null,null,null,1,'con',null,'area','sphere',60,1,1);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_otilukes_resilient_sphere','Otiluke''s Resilient Sphere',4,'abjuration','action','ranged',30,1,1,1,'a glass sphere','concentration_1_minute',1,0,'A shimmering sphere encloses a Large or smaller creature or object within range. An unwilling creature makes a DEX save or is enclosed. Nothing can pass through the barrier in or out; the creature can breathe inside. The sphere is immune to all damage; creatures inside can''t be damaged from outside nor damage anything outside. An enclosed creature can take an action to push against the walls and roll at half its Speed. The sphere can be picked up and moved. Disintegrate destroys it without harming what''s inside.',null,null,null,0,null,null,null,null,'dex',null,'single',null,null,0,1);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_ottos_irresistible_dance','Otto''s Irresistible Dance',6,'enchantment','action','ranged',30,1,0,0,null,'concentration_1_minute',1,0,'One creature you can see within range makes a WIS save. On a successful save, it dances comically until the end of its next turn (must spend all movement dancing in place). On a failed save, it has the Charmed condition: must use all movement to dance in place, has Disadvantage on DEX saves and attack rolls, and other creatures have Advantage on attack rolls against it. On each of its turns, it can take an action to repeat the save, ending the spell on a success.',null,null,null,0,null,null,null,null,'wis',null,'single',null,null,1,1);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_passwall','Passwall',5,'transmutation','action','ranged',30,1,1,1,'a pinch of sesame seeds','1_hour',0,0,'A passage up to 5 feet wide, 8 feet tall, and 20 feet deep appears at a point you can see on a wooden, plaster, or stone surface within range, lasting for the duration. It creates no structural instability. When the opening disappears, any creatures or objects in the passage are safely ejected to the nearest unoccupied space.',null,null,null,0,null,null,null,null,null,null,'single',null,null,0,1);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_pass_without_trace','Pass without Trace',2,'abjuration','action','self',null,1,1,1,'ashes from burned mistletoe','concentration_1_hour',1,0,'You radiate a concealing aura in a 30-foot Emanation for the duration. While in the aura, you and each creature you choose have a +10 bonus to DEX (Stealth) checks and leave no tracks.',null,null,null,0,null,null,null,null,null,null,'self','emanation',30,0,0);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_phantasmal_force','Phantasmal Force',2,'illusion','action','ranged',60,1,1,1,'a bit of fleece','concentration_1_minute',1,0,'One creature you can see within range makes an INT save. On a failed save, you create a phantasm (no larger than a 10-foot Cube) perceivable only to the target, including sound, temperature, and other stimuli. The target treats it as real and rationalizes illogical outcomes. It can Study and make an INT (Investigation) check against your spell save DC to disbelieve. A dangerous phantasm can deal 2d8 Psychic damage per turn if the target is in or within 5 feet of it.','d8',2,'psychic',0,null,null,null,null,'int',null,'single',null,null,0,1);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_phantasmal_killer','Phantasmal Killer',4,'illusion','action','ranged',120,1,1,0,null,'concentration_1_minute',1,0,'You create an illusion of a creature''s deepest fears, visible only to it. The target makes a WIS save: on failure, 4d10 Psychic damage and Disadvantage on ability checks and attack rolls for the duration; on success, half damage and the spell ends. For the duration, the target makes a WIS save at the end of each of its turns: failure deals the Psychic damage again; success ends the spell. Using a Higher-Level Spell Slot: Damage increases by 1d10 per slot level above 4.','d10',4,'psychic',1,null,null,null,1,'wis',null,'single',null,null,1,1);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_phantom_steed','Phantom Steed',3,'illusion','1_minute','ranged',30,1,1,0,null,'1_hour',0,1,'A Large quasi-real horselike creature appears in an unoccupied space within range. You decide its appearance; it comes equipped with saddle, bit, and bridle (equipment vanishes if carried more than 10 feet from it). You or a creature you choose can ride it. It uses the Riding Horse stat block but has Speed 100 feet and can travel 13 miles per hour. When the spell ends, the steed fades over 1 minute (giving the rider time to dismount). Ends early if the steed takes any damage.',null,null,null,0,null,null,null,null,null,null,'single',null,null,0,1);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_planar_ally','Planar Ally',6,'conjuration','10_minutes','ranged',60,1,1,0,null,'instantaneous',0,0,'You beseech a known otherworldly entity (god, demon prince, or similar cosmic power). It sends a Celestial, Elemental, or Fiend loyal to it to appear in an unoccupied space within range. The creature is under no compulsion. You can bargain for its service with payment: 100 GP per minute of service, 1,000 GP per hour, or 10,000 GP per day (up to 10 days). If no agreement is reached, it returns immediately. After completing its task or when service expires, it returns to its home plane.',null,null,null,0,null,null,null,null,null,null,'single',null,null,0,0);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_planar_binding','Planar Binding',5,'abjuration','1_hour','ranged',60,1,1,1,'a jewel worth 1,000+ GP, which the spell consumes','24_hours',0,0,'You attempt to bind a Celestial, Elemental, Fey, or Fiend within range to your service. At the end of casting, the target makes a CHA save or is bound to serve you for the duration (a summoned creature''s existing spell duration extends to match). A bound creature must follow your commands to the best of its ability. A Hostile creature twists your commands toward its own goals. Using a Higher-Level Spell Slot: Duration extends to 10 days (6), 30 days (7), 180 days (8), or 366 days (9).',null,null,null,1,null,null,null,null,'cha',null,'single',null,null,0,1);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_plane_shift','Plane Shift',7,'conjuration','action','touch',null,1,1,1,'a forked metal rod worth 250+ GP attuned to a plane of existence','instantaneous',0,0,'You and up to eight willing creatures who link hands are transported to a different plane of existence. You can specify a target destination in general terms and appear in or near it (DM determines). Alternatively, if you know a teleportation circle''s sigil sequence on another plane, this spell can take you there.',null,null,null,0,null,null,null,null,null,null,'multiple',null,null,0,1);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_plant_growth','Plant Growth',3,'transmutation','action','ranged',150,1,1,0,null,'instantaneous',0,0,'Overgrowth (Action): All normal plants in a 100-foot-radius Sphere centered on a point within range become thick and overgrown — creatures must spend 4 feet of movement per 1 foot moved through the area. You can exclude areas. Enrichment (8 hours): All plants in a half-mile radius centered on a point within range are enriched for 365 days, yielding twice the normal food when harvested (only once per year per plant).',null,null,null,0,null,null,null,null,null,null,'area','sphere',100,0,0);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_poison_spray','Poison Spray',0,'necromancy','action','ranged',30,1,1,0,null,'instantaneous',0,0,'You spray toxic mist at a creature within range. Make a ranged spell attack. On a hit, the target takes 1d12 Poison damage. Cantrip Upgrade: Damage increases by 1d12 when you reach levels 5 (2d12), 11 (3d12), and 17 (4d12).','d12',1,'poison',1,2,3,4,null,null,'ranged_spell','single',null,null,1,1);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_polymorph','Polymorph',4,'transmutation','action','ranged',60,1,1,1,'a caterpillar cocoon','concentration_1_hour',1,0,'You attempt to transform a creature you can see within range into a Beast. The target makes a WIS save or shape-shifts into a Beast form of your choice (CR equal to or less than the target''s CR or level). Its statistics are replaced by the Beast''s stat block, but it retains alignment, personality, creature type, HP, and Hit Dice. It gains Temporary HP equal to the Beast form''s HP (spell ends early if those reach 0). It can''t speak or cast spells, and equipment melds into the new form.',null,null,null,0,null,null,null,null,'wis',null,'single',null,null,1,1);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_power_word_fortify','Power Word Fortify',7,'enchantment','action','ranged',60,1,0,0,null,'instantaneous',0,0,'You fortify up to six creatures you can see within range. The spell bestows 120 Temporary Hit Points, divided as you choose among the recipients.',null,null,null,0,null,null,null,null,null,null,'multiple',null,null,0,0);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_power_word_heal','Power Word Heal',9,'enchantment','action','ranged',60,1,0,0,null,'instantaneous',0,0,'A wave of healing energy washes over one creature you can see within range. The target regains all its Hit Points. The Charmed, Frightened, Paralyzed, Poisoned, and Stunned conditions end on it. If it has the Prone condition, it can use its Reaction to stand up.',null,null,null,0,null,null,null,null,null,null,'single',null,null,0,0);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_power_word_kill','Power Word Kill',9,'enchantment','action','ranged',60,1,0,0,null,'instantaneous',0,0,'You compel one creature you can see within range to die. If the target has 100 Hit Points or fewer, it dies. Otherwise, it takes 12d12 Psychic damage.','d12',12,'psychic',0,null,null,null,null,null,null,'single',null,null,1,1);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_power_word_stun','Power Word Stun',8,'enchantment','action','ranged',60,1,0,0,null,'instantaneous',0,0,'You overwhelm the mind of one creature you can see within range. If the target has 150 Hit Points or fewer, it has the Stunned condition. Otherwise, its Speed is 0 until the start of your next turn. The Stunned target makes a CON save at the end of each of its turns, ending the condition on itself on a success.',null,null,null,0,null,null,null,null,'con',null,'single',null,null,1,1);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_prayer_of_healing','Prayer of Healing',2,'abjuration','10_minutes','ranged',30,1,0,0,null,'instantaneous',0,0,'Up to five creatures of your choice who remain within range for the entire casting gain the benefits of a Short Rest and also regain 2d8 Hit Points. A creature can''t be affected by this spell again until it finishes a Long Rest. Using a Higher-Level Spell Slot: Healing increases by 1d8 per slot level above 2.',null,null,null,1,null,null,null,null,null,null,'multiple',null,null,0,0);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_prestidigitation','Prestidigitation',0,'transmutation','action','ranged',10,1,1,0,null,'1_hour',0,0,'You create a magical effect within range. Choose one: Sensory Effect (harmless instantaneous sensory effect); Fire Play (light or snuff a candle, torch, or small campfire); Clean or Soil (clean or soil an object up to 1 cubic foot); Minor Sensation (chill, warm, or flavor up to 1 cubic foot of nonliving material for 1 hour); Magic Mark (color, mark, or symbol on an object for 1 hour); or Minor Creation (a nonmagical trinket or illusory image that fits in your hand, lasts until end of your next turn). Up to three non-instantaneous effects active at once.',null,null,null,0,null,null,null,null,null,null,'single',null,null,0,1);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_prismatic_spray','Prismatic Spray',7,'evocation','action','self',null,1,1,0,null,'instantaneous',0,0,'Eight rays of light flash from you in a 60-foot Cone. Each creature in the Cone makes a DEX save. Roll 1d8 per target to determine the ray: 1 Red (12d6 Fire, half on success), 2 Orange (12d6 Acid), 3 Yellow (12d6 Lightning), 4 Green (12d6 Poison), 5 Blue (12d6 Cold), 6 Indigo (Restrained, then CON saves — 3 failures = Petrified), 7 Violet (Blinded, then WIS save — failure = banished to another plane), 8 Two rays (roll twice, reroll 8s).','d6',12,'varies',0,null,null,null,null,'dex',null,'area','cone',60,1,1);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_prismatic_wall','Prismatic Wall',9,'abjuration','action','ranged',60,1,1,0,null,'10_minutes',0,0,'A shimmering multicolored opaque wall (up to 90 ft long, 30 ft high, 1 inch thick) or globe (up to 30 ft diameter) appears centered on a point within range. Sheds Bright Light 100 feet, Dim Light another 100 feet. Creatures within 20 feet that can see it make a CON save or have the Blinded condition for 1 minute. The wall has 7 layers (Red through Violet); creatures passing through make a DEX save per layer. Each layer can be destroyed by specific means. Can''t be affected by Antimagic Field; Dispel Magic affects only the violet layer.',null,null,null,0,null,null,null,null,'dex',null,'area','wall',90,0,1);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_produce_flame','Produce Flame',0,'conjuration','bonus_action','self',null,1,1,0,null,'10_minutes',0,0,'A flickering flame appears in your hand for the duration. It emits no heat and ignites nothing, shedding Bright Light in a 20-foot radius and Dim Light for an additional 20 feet. Ends if you cast it again. Until it ends, you can take a Magic action to hurl fire at a creature or object within 60 feet: ranged spell attack, 1d8 Fire damage on a hit. Cantrip Upgrade: Damage increases by 1d8 when you reach levels 5 (2d8), 11 (3d8), and 17 (4d8).','d8',1,'fire',1,2,3,4,null,null,'ranged_spell','single',null,null,1,0);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_programmed_illusion','Programmed Illusion',6,'illusion','action','ranged',120,1,1,1,'jade dust worth 25+ GP','until_dispelled',0,0,'You create an illusion (no larger than a 30-foot Cube) that is imperceptible until a trigger condition you specify occurs. When triggered, the illusion performs for up to 5 minutes in the manner you described when casting. After performing, it disappears and is dormant for 10 minutes before it can activate again. The trigger must be based on visual or audible phenomena within 30 feet. Physical interaction reveals it as illusory; a creature can Study and make an INT (Investigation) check against your spell save DC to disbelieve it.',null,null,null,0,null,null,null,null,null,null,'single',null,null,0,1);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_project_image','Project Image',7,'illusion','action','special',2640000,1,1,1,'a statuette of yourself worth 5+ GP','concentration_1_day',1,0,'You create an illusory copy of yourself at any location within range that you have seen before. It looks and sounds like you but is intangible and disappears if it takes any damage. You can see and hear through it. As a Magic action, move it up to 60 feet and make it gesture, speak, and behave in any way. Physical interaction reveals it as illusory; a Study action and INT (Investigation) check against your spell save DC can disbelieve it.',null,null,null,0,null,null,null,null,null,null,'single',null,null,0,1);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_protection_from_energy','Protection from Energy',3,'abjuration','action','touch',null,1,1,0,null,'concentration_1_hour',1,0,'For the duration, the willing creature you touch has Resistance to one damage type of your choice: Acid, Cold, Fire, Lightning, or Thunder.',null,null,null,0,null,null,null,null,null,null,'single',null,null,1,1);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_protection_from_evil_and_good','Protection from Evil and Good',1,'abjuration','action','touch',null,1,1,1,'a flask of Holy Water worth 25+ GP, which the spell consumes','concentration_10_minutes',1,0,'Until the spell ends, one willing creature you touch is protected against Aberrations, Celestials, Elementals, Fey, Fiends, and Undead. Those creatures have Disadvantage on attack rolls against the target. The target can''t be possessed by or gain the Charmed or Frightened conditions from them. If already possessed, Charmed, or Frightened by such a creature, the target has Advantage on new saving throws against the relevant effect.',null,null,null,0,null,null,null,null,null,null,'single',null,null,1,1);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_protection_from_poison','Protection from Poison',2,'abjuration','action','touch',null,1,1,0,null,'1_hour',0,0,'You touch a creature and end the Poisoned condition on it. For the duration, the target has Advantage on saving throws to avoid or end the Poisoned condition and has Resistance to Poison damage.',null,null,null,0,null,null,null,null,null,null,'single',null,null,0,0);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_purify_food_and_drink','Purify Food and Drink',1,'transmutation','action','ranged',10,1,1,0,null,'instantaneous',0,1,'You remove poison and rot from nonmagical food and drink in a 5-foot-radius Sphere centered on a point within range.',null,null,null,0,null,null,null,null,null,null,'area','sphere',5,0,0);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_raise_dead','Raise Dead',5,'necromancy','1_hour','touch',null,1,1,1,'a diamond worth 500+ GP, which the spell consumes','instantaneous',0,0,'You revive a dead creature that has been dead no longer than 10 days and wasn''t Undead when it died. The creature returns to life with 1 Hit Point. The spell neutralizes any poisons that affected the creature at death and closes all mortal wounds, but doesn''t restore missing body parts (spell fails automatically if integral parts are missing). The target takes a −4 penalty to D20 Tests, reduced by 1 after each Long Rest until it reaches 0.',null,null,null,0,null,null,null,null,null,null,'single',null,null,0,0);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_rarys_telepathic_bond','Rary''s Telepathic Bond',5,'divination','action','ranged',30,1,1,1,'two eggs','1_hour',0,1,'You forge a telepathic link among up to eight willing creatures within range, psychically linking each to all the others for the duration. Creatures that can''t communicate in any languages aren''t affected. Until the spell ends, the targets can communicate telepathically regardless of shared language, over any distance (but not across planes of existence).',null,null,null,0,null,null,null,null,null,null,'multiple',null,null,0,1);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_ray_of_enfeeblement','Ray of Enfeeblement',2,'necromancy','action','ranged',60,1,1,0,null,'concentration_1_minute',1,0,'A beam of enervating energy shoots toward a creature within range. The target makes a CON save. On success, it has Disadvantage on its next attack roll until the start of your next turn. On failure, it has Disadvantage on STR-based D20 Tests for the duration and subtracts 1d8 from all its damage rolls. The target repeats the save at the end of each of its turns, ending the spell on a success.','d8',1,'necrotic',0,null,null,null,null,'con',null,'single',null,null,1,1);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_ray_of_frost','Ray of Frost',0,'evocation','action','ranged',60,1,1,0,null,'instantaneous',0,0,'A frigid beam of blue-white light streaks toward a creature within range. Make a ranged spell attack. On a hit, it takes 1d8 Cold damage and its Speed is reduced by 10 feet until the start of your next turn. Cantrip Upgrade: Damage increases by 1d8 when you reach levels 5 (2d8), 11 (3d8), and 17 (4d8).','d8',1,'cold',1,2,3,4,null,null,'ranged_spell','single',null,null,1,1);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_ray_of_sickness','Ray of Sickness',1,'necromancy','action','ranged',60,1,1,0,null,'instantaneous',0,0,'You shoot a greenish ray at a creature within range. Make a ranged spell attack. On a hit, the target takes 2d8 Poison damage and has the Poisoned condition until the end of your next turn. Using a Higher-Level Spell Slot: Damage increases by 1d8 per slot level above 1.','d8',2,'poison',1,null,null,null,1,null,'ranged_spell','single',null,null,1,1);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_regenerate','Regenerate',7,'transmutation','1_minute','touch',null,1,1,1,'a prayer wheel','1_hour',0,0,'A creature you touch regains 4d8 + 15 Hit Points. For the duration, the target regains 1 Hit Point at the start of each of its turns, and any severed body parts regrow after 2 minutes.',null,null,null,0,null,null,null,null,null,null,'single',null,null,0,0);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_reincarnate','Reincarnate',5,'necromancy','1_hour','touch',null,1,1,1,'rare oils worth 1,000+ GP, which the spell consumes','instantaneous',0,0,'You touch a dead Humanoid or a piece of one that has been dead no longer than 10 days. The spell forms a new body and calls the soul to enter it. Roll 1d10 to determine the body''s species (Aasimar, Dragonborn, Dwarf, Elf, Gnome, Goliath, Halfling, Human, Orc, or Tiefling) or the DM chooses. The creature makes any choices the species offers, recalls its former life, retains its prior capabilities, loses its old species traits, and gains its new species traits.',null,null,null,0,null,null,null,null,null,null,'single',null,null,0,0);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_remove_curse','Remove Curse',3,'abjuration','action','touch',null,1,1,0,null,'instantaneous',0,0,'At your touch, all curses affecting one creature or object end. If the object is a cursed magic item, its curse remains, but the spell breaks its owner''s Attunement to it so it can be removed or discarded.',null,null,null,0,null,null,null,null,null,null,'single',null,null,0,1);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_resistance','Resistance',0,'abjuration','action','touch',null,1,1,0,null,'concentration_1_minute',1,0,'You touch a willing creature and choose a damage type: Acid, Bludgeoning, Cold, Fire, Lightning, Necrotic, Piercing, Poison, Radiant, Slashing, or Thunder. When the creature takes damage of the chosen type before the spell ends, it reduces the total damage taken by 1d4. A creature can benefit from this spell only once per turn.',null,null,null,0,null,null,null,null,null,null,'single',null,null,0,0);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_resurrection','Resurrection',7,'necromancy','1_hour','touch',null,1,1,1,'a diamond worth 1,000+ GP, which the spell consumes','instantaneous',0,0,'You revive a dead creature that has been dead no longer than a century, didn''t die of old age, and wasn''t Undead when it died. The creature returns with all its Hit Points. Poisons are neutralized, all mortal wounds closed, and missing body parts restored. The target takes a −4 penalty to D20 Tests, reduced by 1 after each Long Rest until 0. Reviving a creature dead 365+ days or longer means you can''t cast spells until you finish a Long Rest and have Disadvantage on D20 Tests until then.',null,null,null,0,null,null,null,null,null,null,'single',null,null,0,0);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_reverse_gravity','Reverse Gravity',7,'transmutation','action','ranged',100,1,1,1,'a lodestone and iron filings','concentration_1_minute',1,0,'Gravity reverses in a 50-foot-radius, 100-foot-high Cylinder centered on a point within range. All creatures and objects not anchored to the ground fall upward to the top of the Cylinder. A creature can make a DEX save to grab a fixed object and avoid the fall. Creatures and objects strike the ceiling or anchored objects as in a downward fall. Unobstructed creatures hover at the top. When the spell ends, everything falls back down.',null,null,null,0,null,null,null,null,'dex',null,'area','cylinder',50,0,1);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_revivify','Revivify',3,'necromancy','action','touch',null,1,1,1,'a diamond worth 300+ GP, which the spell consumes','instantaneous',0,0,'You touch a creature that has died within the last minute. It revives with 1 Hit Point. This spell can''t revive a creature that died of old age, nor does it restore missing body parts.',null,null,null,0,null,null,null,null,null,null,'single',null,null,0,0);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_rope_trick','Rope Trick',2,'transmutation','action','touch',null,1,1,1,'a segment of rope','1_hour',0,0,'You touch a rope. One end hovers upward until the rope hangs perpendicular to the ground or reaches a ceiling. At the top, an Invisible 3-by-5-foot portal opens to an extradimensional space that lasts until the spell ends. The space holds up to eight Medium or smaller creatures. Attacks, spells, and other effects can''t pass into or out of the space, but creatures inside can see through the portal. Anything inside drops out when the spell ends.',null,null,null,0,null,null,null,null,null,null,'single',null,null,0,1);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_sacred_flame','Sacred Flame',0,'evocation','action','ranged',60,1,1,0,null,'instantaneous',0,0,'Flame-like radiance descends on a creature you can see within range. The target must succeed on a DEX save or take 1d8 Radiant damage. The target gains no benefit from Half Cover or Three-Quarters Cover for this save. Cantrip Upgrade: Damage increases by 1d8 when you reach levels 5 (2d8), 11 (3d8), and 17 (4d8).','d8',1,'radiant',1,2,3,4,null,'dex',null,'single',null,null,1,0);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_sanctuary','Sanctuary',1,'abjuration','bonus_action','ranged',30,1,1,1,'a shard of glass from a mirror','1_minute',0,0,'You ward a creature within range. Until the spell ends, any creature who targets the warded creature with an attack roll or a damaging spell must succeed on a WIS save or lose the attack or spell or choose a new target. This spell doesn''t protect from areas of effect. The spell ends if the warded creature makes an attack roll, casts a spell, or deals damage.',null,null,null,0,null,null,null,null,'wis',null,'single',null,null,0,0);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_scorching_ray','Scorching Ray',2,'evocation','action','ranged',120,1,1,0,null,'instantaneous',0,0,'You hurl three fiery rays at one target or several within range. Make a ranged spell attack for each ray. On a hit, the target takes 2d6 Fire damage. Using a Higher-Level Spell Slot: One additional ray per slot level above 2.','d6',2,'fire',1,null,null,null,null,null,'ranged_spell','multiple',null,null,1,1);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_scrying','Scrying',5,'divination','10_minutes','self',null,1,1,1,'a focus worth 1,000+ GP (crystal ball, mirror, or water-filled font)','concentration_10_minutes',1,0,'You can see and hear a creature on the same plane of existence. The target makes a WIS save (modified by how well you know it and any physical connection you have). On a failed save, an Invisible intangible sensor appears within 10 feet of the target and moves with it for the duration. You see and hear through the sensor. Alternatively, target a location you have seen — the sensor appears there and doesn''t move. On a successful save, the target is unaffected and immune for 24 hours.',null,null,null,0,null,null,null,null,'wis',null,'single',null,null,0,1);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_searing_smite','Searing Smite',1,'evocation','bonus_action','self',null,1,0,0,null,'1_minute',0,0,'As you hit the target, it takes an extra 1d6 Fire damage. At the start of each of its turns until the spell ends, the target takes 1d6 Fire damage and makes a CON save — on success, the spell ends. Using a Higher-Level Spell Slot: All damage increases by 1d6 per slot level above 1.','d6',1,'fire',1,null,null,null,1,'con',null,'single',null,null,0,0);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_see_invisibility','See Invisibility',2,'divination','action','self',null,1,1,1,'a pinch of talc','1_hour',0,0,'For the duration, you see creatures and objects that have the Invisible condition as if they were visible, and you can see into the Ethereal Plane. Creatures and objects there appear ghostly.',null,null,null,0,null,null,null,null,null,null,'self',null,null,0,1);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_seeming','Seeming',5,'illusion','action','ranged',30,1,1,0,null,'8_hours',0,0,'You give an illusory appearance to each creature of your choice you can see within range. An unwilling target makes a CHA save — success means it''s unaffected. You can give the same or different appearances. Targets can appear up to 1 foot shorter or taller and must retain the same basic limb arrangement. Changes fail to hold up to physical inspection. A creature can Study and make an INT (Investigation) check against your spell save DC to detect the disguise.',null,null,null,0,null,null,null,null,'cha',null,'multiple',null,null,0,1);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_sending','Sending',3,'divination','action','special',null,1,1,1,'a copper wire','instantaneous',0,0,'You send a short message of 25 words or fewer to a creature you have met or that was described to you by someone who has met it. The target hears the message in its mind and can answer immediately. Works across any distance and other planes (5% chance of failure across planes). A target can block you for 8 hours after receiving your message.',null,null,null,0,null,null,null,null,null,null,'single',null,null,0,1);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_sequester','Sequester',7,'transmutation','action','touch',null,1,1,1,'gem dust worth 5,000+ GP, which the spell consumes','until_dispelled',0,0,'With a touch, you magically sequester an object or willing creature. The target has the Invisible condition, can''t be targeted by Divination spells, detected by magic, or viewed remotely. A creature enters suspended animation (Unconscious, doesn''t age, no food/water/air needed). You can set a condition to end the spell early. Also ends if the target takes any damage.',null,null,null,0,null,null,null,null,null,null,'single',null,null,0,1);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_shapechange','Shapechange',9,'transmutation','action','self',null,1,1,1,'a jade circlet worth 1,500+ GP','concentration_1_hour',1,0,'You shape-shift into a creature with a CR no higher than your level or CR, that you have seen and that isn''t a Construct or Undead. You gain Temporary HP equal to the first form''s HP. Your statistics are replaced by the form''s stat block, but you retain your creature type, alignment, personality, INT/WIS/CHA, HP, Hit Dice, proficiencies, ability to communicate, and Spellcasting feature (if any). You can take a Magic action to shape-shift into a different eligible form.',null,null,null,0,null,null,null,null,null,null,'self',null,null,0,1);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_shatter','Shatter',2,'evocation','action','ranged',60,1,1,1,'a chip of mica','instantaneous',0,0,'A loud noise erupts from a point within range. Each creature in a 10-foot-radius Sphere makes a CON save, taking 3d8 Thunder damage on a failure or half on a success. A Construct has Disadvantage on the save. Nonmagical unattended objects in the area also take the damage. Using a Higher-Level Spell Slot: Damage increases by 1d8 per slot level above 2.','d8',3,'thunder',1,null,null,null,1,'con',null,'area','sphere',10,1,1);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_shield','Shield',1,'abjuration','reaction','self',null,1,1,0,null,'1_round',0,0,'An imperceptible barrier of magical force protects you. Until the start of your next turn, you have a +5 bonus to AC (including against the triggering attack) and take no damage from Magic Missile.',null,null,null,0,null,null,null,null,null,null,'self',null,null,1,1);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_shield_of_faith','Shield of Faith',1,'abjuration','bonus_action','ranged',60,1,1,1,'a prayer scroll','concentration_10_minutes',1,0,'A shimmering field surrounds a creature of your choice within range, granting it a +2 bonus to AC for the duration.',null,null,null,0,null,null,null,null,null,null,'single',null,null,0,0);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_shillelagh','Shillelagh',0,'transmutation','bonus_action','self',null,1,1,1,'mistletoe','1_minute',0,0,'A Club or Quarterstaff you are holding is imbued with nature''s power. For the duration, you can use your spellcasting ability instead of Strength for attack and damage rolls with that weapon, and its damage die becomes a d8 (d10 at level 5, d12 at level 11, 2d6 at level 17). Damage can be Force or the weapon''s normal type (your choice). Ends early if you cast it again or let go of the weapon.',null,null,null,0,null,null,null,null,null,null,'single',null,null,0,0);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_shining_smite','Shining Smite',2,'transmutation','bonus_action','self',null,1,0,0,null,'concentration_1_minute',1,0,'The target hit by the strike takes an extra 2d6 Radiant damage. Until the spell ends, the target sheds Bright Light in a 5-foot radius, attack rolls against it have Advantage, and it can''t benefit from the Invisible condition. Using a Higher-Level Spell Slot: Damage increases by 1d6 per slot level above 2.','d6',2,'radiant',1,null,null,null,1,null,null,'single',null,null,0,0);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_shocking_grasp','Shocking Grasp',0,'evocation','action','touch',null,1,1,0,null,'instantaneous',0,0,'Lightning springs from you to a creature you try to touch. Make a melee spell attack. On a hit, the target takes 1d8 Lightning damage and can''t make Opportunity Attacks until the start of its next turn. You have Advantage on the attack roll if the target is wearing metal armor. Cantrip Upgrade: Damage increases by 1d8 when you reach levels 5 (2d8), 11 (3d8), and 17 (4d8).','d8',1,'lightning',1,2,3,4,null,null,'melee_spell','single',null,null,1,1);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_silence','Silence',2,'illusion','action','ranged',120,1,1,0,null,'concentration_10_minutes',1,1,'No sound can be created within or pass through a 20-foot-radius Sphere centered on a point within range. Any creature or object entirely inside has Immunity to Thunder damage, and creatures have the Deafened condition while entirely inside. Casting a spell with a Verbal component is impossible there.',null,null,null,0,null,null,null,null,null,null,'area','sphere',20,0,0);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_silent_image','Silent Image',1,'illusion','action','ranged',60,1,1,1,'a bit of fleece','concentration_10_minutes',1,0,'You create a purely visual image of an object, creature, or phenomenon no larger than a 15-foot Cube at a spot within range. As a Magic action, you can move it anywhere within range and alter its appearance naturally. Physical interaction reveals the illusion. A creature can Study and make an INT (Investigation) check against your spell save DC to disbelieve it.',null,null,null,0,null,null,null,null,null,null,'single',null,null,0,1);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_simulacrum','Simulacrum',7,'illusion','12_hours','touch',null,1,1,1,'powdered ruby worth 1,500+ GP, which the spell consumes','until_dispelled',0,0,'You create a simulacrum of one Beast or Humanoid within 10 feet for the entire casting by touching both the creature and a same-sized pile of ice or snow, which turns into the simulacrum. It is a Construct with half the original''s HP maximum and can''t cast this spell. It is Friendly and obeys your commands. It can''t gain levels or take Rests. Restoring its HP costs 100 GP per HP during your Long Rest. It lasts until it drops to 0 HP (reverts to snow). Casting this spell again instantly destroys any existing simulacrum.',null,null,null,0,null,null,null,null,null,null,'single',null,null,0,1);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_sleep','Sleep',1,'enchantment','action','ranged',60,1,1,1,'a pinch of sand or rose petals','concentration_1_minute',1,0,'Each creature of your choice in a 5-foot-radius Sphere centered on a point within range must succeed on a WIS save or have the Incapacitated condition until the end of its next turn, then repeat the save. If it fails the second save, it has the Unconscious condition for the duration. The spell ends on a target if it takes damage or someone within 5 feet shakes it awake. Creatures that don''t sleep or have Immunity to Exhaustion auto-succeed.',null,null,null,0,null,null,null,null,'wis',null,'area','sphere',5,1,1);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_sleet_storm','Sleet Storm',3,'conjuration','action','ranged',150,1,1,1,'a miniature umbrella','concentration_1_minute',1,0,'Sleet falls in a 40-foot-tall, 20-foot-radius Cylinder centered on a point within range. The area is Heavily Obscured, and exposed flames are doused. Ground is Difficult Terrain. When a creature enters the Cylinder for the first time on a turn or starts its turn there, it must succeed on a DEX save or have the Prone condition and lose Concentration.',null,null,null,0,null,null,null,null,'dex',null,'area','cylinder',20,1,1);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_slow','Slow',3,'transmutation','action','ranged',120,1,1,1,'a drop of molasses','concentration_1_minute',1,0,'Up to six creatures of your choice in a 40-foot Cube within range must succeed on a WIS save or be affected: Speed halved, −2 penalty to AC and DEX saves, can''t take Reactions, can take only an action or Bonus Action (not both), one attack maximum if taking the Attack action, and 25% chance a spell with a Somatic component fails. An affected target repeats the save at end of each of its turns, ending the effect on itself on a success.',null,null,null,0,null,null,null,null,'wis',null,'area','cube',40,1,1);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_sorcerous_burst','Sorcerous Burst',0,'evocation','action','ranged',120,1,1,0,null,'instantaneous',0,0,'Make a ranged spell attack against one creature or object within range. On a hit, the target takes 1d8 damage of a type you choose: Acid, Cold, Fire, Lightning, Poison, Psychic, or Thunder. If you roll an 8 on a d8, you can roll another d8 and add it to the damage (maximum additional d8s equals your spellcasting modifier). Cantrip Upgrade: Damage increases by 1d8 when you reach levels 5 (2d8), 11 (3d8), and 17 (4d8).','d8',1,'varies',1,2,3,4,null,null,'ranged_spell','single',null,null,1,0);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_spare_the_dying','Spare the Dying',0,'necromancy','action','ranged',15,1,1,0,null,'instantaneous',0,0,'Choose a creature within range that has 0 Hit Points and isn''t dead. The creature becomes Stable. Cantrip Upgrade: The range doubles when you reach levels 5 (30 feet), 11 (60 feet), and 17 (120 feet).',null,null,null,0,null,null,null,null,null,null,'single',null,null,0,0);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_speak_with_animals','Speak with Animals',1,'divination','action','self',null,1,1,0,null,'10_minutes',0,1,'For the duration, you can comprehend and verbally communicate with Beasts, and you can use any of the Influence action''s skill options with them. Most Beasts have little to say beyond survival and companionship topics, but can give information about nearby locations and monsters, including what they''ve perceived in the past day.',null,null,null,0,null,null,null,null,null,null,'self',null,null,0,0);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_speak_with_dead','Speak with Dead',3,'necromancy','action','ranged',10,1,1,1,'burning incense','10_minutes',0,0,'You grant the semblance of life to a corpse within range (must have a mouth; fails if the creature was Undead when it died or was targeted by this spell in the past 10 days). Until the spell ends, you can ask it up to five questions. The corpse knows only what it knew in life. Answers are brief, cryptic, or repetitive, and the corpse isn''t compelled to be truthful if it sees you as an enemy. The spell doesn''t return its soul.',null,null,null,0,null,null,null,null,null,null,'single',null,null,0,1);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_speak_with_plants','Speak with Plants',3,'transmutation','action','self',null,1,1,0,null,'10_minutes',0,0,'Plants in an immobile 30-foot Emanation gain limited sentience and animation, can communicate with you, and follow simple commands. You can question them about events in the past day. You can turn Difficult Terrain caused by plants into ordinary terrain for the duration (or vice versa). Plants can''t uproot themselves but can move branches and tendrils. You can communicate with Plant creatures in the area as if sharing a language.',null,null,null,0,null,null,null,null,null,null,'self','emanation',30,0,0);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_spider_climb','Spider Climb',2,'transmutation','action','touch',null,1,1,1,'a drop of bitumen and a spider','concentration_1_hour',1,0,'Until the spell ends, one willing creature you touch gains the ability to move up, down, and across vertical surfaces and along ceilings while leaving its hands free. The target also gains a Climb Speed equal to its Speed. Using a Higher-Level Spell Slot: Target one additional creature per slot level above 2.',null,null,null,1,null,null,null,null,null,null,'single',null,null,0,1);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_spike_growth','Spike Growth',2,'transmutation','action','ranged',150,1,1,1,'seven thorns','concentration_10_minutes',1,0,'Hard spikes and thorns sprout in a 20-foot-radius Sphere centered on a point within range, making it Difficult Terrain. A creature takes 2d4 Piercing damage for every 5 feet it travels through the area. The transformation is camouflaged to look natural; creatures that can''t see it must take a Search action and succeed on a WIS (Perception or Survival) check against your spell save DC to recognize the hazard.','d4',2,'piercing',0,null,null,null,null,null,null,'area','sphere',20,0,0);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_spirit_guardians','Spirit Guardians',3,'conjuration','action','self',null,1,1,1,'a prayer scroll','concentration_10_minutes',1,0,'Protective spirits flit in a 15-foot Emanation around you. You can designate unaffected creatures. Other creatures have their Speed halved in the Emanation. Whenever the Emanation enters a creature''s space or a creature enters or ends its turn there, it makes a WIS save: on failure, 3d8 Radiant (good/neutral) or 3d8 Necrotic (evil) damage; on success, half. Once per turn. Using a Higher-Level Spell Slot: Damage increases by 1d8 per slot level above 3.','d8',3,'radiant',1,null,null,null,1,'wis',null,'self','emanation',15,0,0);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_spiritual_weapon','Spiritual Weapon',2,'evocation','bonus_action','ranged',60,1,1,0,null,'concentration_1_minute',1,0,'You create a floating spectral force resembling a weapon in a space within range. Make one melee spell attack against a creature within 5 feet of it: on a hit, 1d8 + spellcasting modifier Force damage. As a Bonus Action on later turns, move the force up to 20 feet and repeat the attack. Using a Higher-Level Spell Slot: Damage increases by 1d8 per slot level above 2.','d8',1,'force',1,null,null,null,1,null,'melee_spell','single',null,null,0,0);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_staggering_smite','Staggering Smite',4,'enchantment','bonus_action','self',null,1,0,0,null,'instantaneous',0,0,'The target takes an extra 4d6 Psychic damage and must succeed on a WIS save or have the Stunned condition until the end of your next turn. Using a Higher-Level Spell Slot: Damage increases by 1d6 per slot level above 4.','d6',4,'psychic',1,null,null,null,1,'wis',null,'single',null,null,0,0);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_starry_wisp','Starry Wisp',0,'evocation','action','ranged',60,1,1,0,null,'instantaneous',0,0,'You launch a mote of light at one creature or object within range. Make a ranged spell attack. On a hit, the target takes 1d8 Radiant damage and until the end of your next turn, it emits Dim Light in a 10-foot radius and can''t benefit from the Invisible condition. Cantrip Upgrade: Damage increases by 1d8 when you reach levels 5 (2d8), 11 (3d8), and 17 (4d8).','d8',1,'radiant',1,2,3,4,null,null,'ranged_spell','single',null,null,1,0);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_steel_wind_strike','Steel Wind Strike',5,'conjuration','action','ranged',30,0,1,1,'a Melee weapon worth 1+ SP','instantaneous',0,0,'You flourish the weapon and vanish to strike like the wind. Choose up to five creatures you can see within range. Make a melee spell attack against each. On a hit, a target takes 6d10 Force damage. You then teleport to an unoccupied space within 5 feet of one of the targets.','d10',6,'force',0,null,null,null,null,null,'melee_spell','multiple',null,null,1,1);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_stinking_cloud','Stinking Cloud',3,'conjuration','action','ranged',90,1,1,1,'a rotten egg','concentration_1_minute',1,0,'You create a 20-foot-radius Sphere of yellow nauseating gas centered on a point within range. The cloud is Heavily Obscured and lingers for the duration or until dispersed by strong wind. Each creature that starts its turn in the Sphere makes a CON save or has the Poisoned condition until the end of the current turn. While Poisoned this way, the creature can''t take an action or Bonus Action.',null,null,null,0,null,null,null,null,'con',null,'area','sphere',20,1,1);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_stone_shape','Stone Shape',4,'transmutation','action','touch',null,1,1,1,'soft clay','instantaneous',0,0,'You touch a stone object of Medium size or smaller, or a section of stone no more than 5 feet in any dimension, and form it into any shape you like. You can create a passage through a wall up to 5 feet thick, shape a door or frame to seal it shut, or form crude objects with up to two hinges and a latch. Finer mechanical detail isn''t possible.',null,null,null,0,null,null,null,null,null,null,'single',null,null,0,1);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_stoneskin','Stoneskin',4,'transmutation','action','touch',null,1,1,1,'diamond dust worth 100+ GP, which the spell consumes','concentration_1_hour',1,0,'Until the spell ends, one willing creature you touch has Resistance to Bludgeoning, Piercing, and Slashing damage.',null,null,null,0,null,null,null,null,null,null,'single',null,null,1,1);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_storm_of_vengeance','Storm of Vengeance',9,'conjuration','action','special',5280,1,1,0,null,'concentration_1_minute',1,0,'A churning storm cloud (300-foot radius) forms for the duration. Each creature under it when it appears makes a CON save or takes 2d6 Thunder damage and has the Deafened condition. Turn 2: 4d6 Acid damage to all beneath. Turn 3: six lightning bolts strike six creatures (DEX save, 10d6 Lightning, half on success). Turn 4: 2d6 Bludgeoning hail. Turns 5-10: 1d6 Cold damage, Difficult Terrain, Heavily Obscured, no ranged weapon attacks, strong wind.',null,null,null,0,null,null,null,null,'con',null,'area','sphere',300,0,0);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_suggestion','Suggestion',2,'enchantment','action','ranged',30,1,0,1,'a drop of honey','concentration_8_hours',1,0,'You suggest a course of activity (25 words or fewer) to one creature you can see within range that can hear and understand you. The suggestion must sound achievable and not obviously harmful. The target must succeed on a WIS save or have the Charmed condition for the duration (or until you or allies deal damage to it). The Charmed target pursues the suggestion to the best of its ability.',null,null,null,0,null,null,null,null,'wis',null,'single',null,null,1,1);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_summon_aberration','Summon Aberration',4,'conjuration','action','ranged',90,1,1,1,'a pickled tentacle and an eyeball in a platinum-inlaid vial worth 400+ GP','concentration_1_hour',1,0,'You call forth an aberrant spirit (Beholderkin, Mind Flayer, or Slaad — your choice). It manifests in an unoccupied space within range and uses the Aberrant Spirit stat block. It is an ally, shares your Initiative, and obeys verbal commands. Disappears at 0 HP or when the spell ends. Using a Higher-Level Spell Slot: Use the slot level for the stat block''s level.',null,null,null,1,null,null,null,null,null,null,'single',null,null,0,1);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_summon_beast','Summon Beast',2,'conjuration','action','ranged',90,1,1,1,'a feather, tuft of fur, and fish tail inside a gilded acorn worth 200+ GP','concentration_1_hour',1,0,'You call forth a bestial spirit (Air, Land, or Water — your choice of environment). It manifests in an unoccupied space within range and uses the Bestial Spirit stat block. It is an ally, shares your Initiative, and obeys verbal commands. Disappears at 0 HP or when the spell ends. Using a Higher-Level Spell Slot: Use the slot level for the stat block''s level.',null,null,null,1,null,null,null,null,null,null,'single',null,null,0,0);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_summon_celestial','Summon Celestial',5,'conjuration','action','ranged',90,1,1,1,'a reliquary worth 500+ GP','concentration_1_hour',1,0,'You call forth a Celestial spirit (Avenger or Defender — your choice). It manifests in an angelic form in an unoccupied space within range and uses the Celestial Spirit stat block. It is an ally, shares your Initiative, and obeys verbal commands. Disappears at 0 HP or when the spell ends. Using a Higher-Level Spell Slot: Use the slot level for the stat block''s level.',null,null,null,1,null,null,null,null,null,null,'single',null,null,0,0);
