('spell_summon_undead','Summon Undead',3,'necromancy','action','ranged',90,1,1,1,'a gilded skull worth 300+ GP','concentration_1_hour',1,0,'You call forth an Undead spirit (Ghostly, Putrid, or Skeletal — your choice). It manifests in an unoccupied space within range and uses the Undead Spirit stat block. It is an ally, shares your Initiative, and obeys verbal commands. Disappears at 0 HP or when the spell ends. Using a Higher-Level Spell Slot: Use the slot level for the stat block''s level.',null,null,null,1,null,null,null,null,null,null,'single',null,null,0,1);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_sunbeam','Sunbeam',6,'evocation','action','self',null,1,1,1,'a magnifying glass','concentration_1_minute',1,0,'You launch a sunbeam in a 5-foot-wide, 60-foot-long Line. Each creature in the Line makes a CON save: on failure, 6d8 Radiant damage and Blinded until the start of your next turn; on success, half damage only. Until the spell ends, you can take a Magic action to create a new Line. A mote of brilliant radiance (sunlight) sheds Bright Light 30 feet and Dim Light 30 more above you for the duration.','d8',6,'radiant',0,null,null,null,null,'con',null,'area','line',60,1,1);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_sunburst','Sunburst',8,'evocation','action','ranged',150,1,1,1,'a piece of sunstone','instantaneous',0,0,'Brilliant sunlight flashes in a 60-foot-radius Sphere centered on a point within range. Each creature in the Sphere makes a CON save: on failure, 12d6 Radiant damage and the Blinded condition for 1 minute; on success, half damage only. A Blinded creature repeats the save at the end of each of its turns, ending the effect on success. This spell dispels Darkness in its area created by any spell.','d6',12,'radiant',0,null,null,null,null,'con',null,'area','sphere',60,1,1);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_swift_quiver','Swift Quiver',5,'transmutation','bonus_action','self',null,1,1,1,'a Quiver worth 1+ GP','concentration_1_minute',1,0,'When you cast the spell and as a Bonus Action until it ends, you can make two attacks with a weapon that fires Arrows or Bolts. The spell magically creates the ammunition needed for each attack. Each piece of ammunition deals damage like a nonmagical piece of its kind and disintegrates immediately after hitting or missing.',null,null,null,0,null,null,null,null,null,null,'self',null,null,0,0);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_symbol','Symbol',7,'abjuration','1_minute','touch',null,1,1,1,'powdered diamond worth 1,000+ GP, which the spell consumes','until_dispelled_or_triggered',0,0,'You inscribe a harmful glyph on a surface or inside a closeable object (max 10-foot diameter). Set a trigger condition and choose an effect: Death (CON save or 10d10 Necrotic), Discord (WIS save or argue for 1 minute, Disadvantage on attacks and checks), Fear (WIS save or Frightened 1 minute), Pain (CON save or Incapacitated 1 minute), Sleep (WIS save or Unconscious 10 minutes), or Stunning (WIS save or Stunned 1 minute). When triggered, glows in a 60-foot Sphere for 10 minutes, affecting creatures entering or ending turns there.',null,null,null,0,null,null,null,null,'con',null,'area','sphere',60,0,1);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_synaptic_static','Synaptic Static',5,'enchantment','action','ranged',120,1,1,0,null,'instantaneous',0,0,'Psychic energy erupts at a point within range. Each creature in a 20-foot-radius Sphere makes an INT save, taking 8d6 Psychic damage on a failure or half on a success. On a failed save, the target also has muddled thoughts for 1 minute: subtracts 1d6 from all attack rolls, ability checks, and CON saves to maintain Concentration. The target repeats the INT save at the end of each of its turns, ending the effect on success.','d6',8,'psychic',0,null,null,null,null,'int',null,'area','sphere',20,1,1);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_tashas_bubbling_cauldron','Tasha''s Bubbling Cauldron',6,'conjuration','action','ranged',5,1,1,1,'a gilded ladle worth 500+ GP','10_minutes',0,0,'You conjure a claw-footed cauldron of bubbling liquid in an unoccupied space within 5 feet of you. The liquid duplicates the properties of a Common or Uncommon potion of your choice. As a Bonus Action, you or an ally can withdraw one such potion (in a vial that disappears when consumed). The cauldron produces a number of potions equal to your spellcasting ability modifier (minimum 1). When the last potion is withdrawn, the cauldron disappears. Unused potions disappear when you cast this spell again.',null,null,null,0,null,null,null,null,null,null,'single',null,null,0,1);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_tashas_hideous_laughter','Tasha''s Hideous Laughter',1,'enchantment','action','ranged',30,1,1,1,'a tart and a feather','concentration_1_minute',1,0,'One creature you can see within range makes a WIS save. On a failed save, it has the Prone and Incapacitated conditions for the duration, laughs uncontrollably, and can''t end the Prone condition on itself. At the end of each of its turns and each time it takes damage, it makes another WIS save (Advantage if triggered by damage). On a successful save, the spell ends. Using a Higher-Level Spell Slot: Target one additional creature per slot level above 1.',null,null,null,1,null,null,null,1,'wis',null,'single',null,null,1,1);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_telekinesis','Telekinesis',5,'transmutation','action','ranged',60,1,1,0,null,'concentration_10_minutes',1,0,'You gain the ability to move or manipulate creatures or objects by thought. As a Magic action on later turns, you can exert your will on one creature or object within range. Creature (Huge or smaller): STR save or moved up to 30 feet in any direction and Restrained until end of your next turn. Object (Huge or smaller, unattended): moved automatically up to 30 feet. If worn/carried: STR save or pulled away and moved 30 feet. You can also exert fine control (open containers, manipulate tools, pour vials).',null,null,null,0,null,null,null,null,'str',null,'single',null,null,0,1);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_telepathy','Telepathy',8,'divination','action','special',null,1,1,1,'a pair of linked silver rings','24_hours',0,0,'You create a telepathic link between yourself and a willing familiar creature anywhere on the same plane of existence. Until the spell ends (or either of you leaves the plane), you and the target can instantly share words, images, sounds, and other sensory messages through the link. The target recognizes you as the communicator and understands the meaning of your messages.',null,null,null,0,null,null,null,null,null,null,'single',null,null,0,1);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_teleport','Teleport',7,'conjuration','action','ranged',10,1,0,0,null,'instantaneous',0,0,'You instantly transport yourself and up to eight willing creatures you can see within range, or a single Large-or-smaller object within range, to a destination on the same plane. Your familiarity with the destination determines success: Permanent circle or linked object (always on target); Very familiar (5% mishap); Seen casually (33% mishap); Viewed once or described (43% mishap); False destination (50% mishap, rest Similar Area). A Mishap deals 3d10 Force damage and the DM rerolls the outcome.',null,null,null,0,null,null,null,null,null,null,'multiple',null,null,0,1);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_teleportation_circle','Teleportation Circle',5,'conjuration','1_minute','ranged',10,1,0,1,'rare inks worth 50+ GP, which the spell consumes','1_round',0,0,'You draw a 5-foot-radius circle inscribed with sigils linking your location to a permanent teleportation circle you know (same plane). A shimmering portal opens until end of your next turn. Any creature entering the portal appears within 5 feet of the destination circle. You learn two sigil sequences when you first gain this spell. You can commit new sequences to memory after studying for 1 minute. Casting this spell daily in the same location for 365 days creates a permanent circle.',null,null,null,0,null,null,null,null,null,null,'single',null,null,0,1);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_tensers_floating_disk','Tenser''s Floating Disk',1,'conjuration','action','ranged',30,1,1,1,'a drop of mercury','1_hour',0,1,'This spell creates a circular 3-foot-diameter plane of force (1 inch thick) that floats 3 feet above the ground in an unoccupied space within range. It holds up to 500 pounds (spell ends if exceeded). Immobile while you''re within 20 feet. Follows you if you move more than 20 feet away (stays within 20 feet), navigating terrain changes up to 10 feet. The spell ends if you move more than 100 feet from the disk.',null,null,null,0,null,null,null,null,null,null,'single',null,null,0,1);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_thaumaturgy','Thaumaturgy',0,'transmutation','action','ranged',30,1,0,0,null,'1_minute',0,0,'You manifest a minor wonder within range, choosing one of the following (up to three 1-minute effects active at once): Altered Eyes (alter appearance of your eyes for 1 minute); Booming Voice (voice booms 3x louder, Advantage on CHA Intimidation for 1 minute); Fire Play (flames flicker, brighten, dim, or change color for 1 minute); Invisible Hand (unlocked door or window flies open or slams shut); Phantom Sound (instantaneous sound from a point within range); or Tremors (harmless ground tremors for 1 minute).',null,null,null,0,null,null,null,null,null,null,'single',null,null,0,0);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_thorn_whip','Thorn Whip',0,'transmutation','action','ranged',30,1,1,1,'the stem of a thorny plant','instantaneous',0,0,'You create a vine-like whip covered in thorns and make a melee spell attack against a creature within range. On a hit, the target takes 1d6 Piercing damage, and if it is Large or smaller, you can pull it up to 10 feet closer to you. Cantrip Upgrade: Damage increases by 1d6 when you reach levels 5 (2d6), 11 (3d6), and 17 (4d6).','d6',1,'piercing',1,2,3,4,null,null,'melee_spell','single',null,null,1,0);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_thunderclap','Thunderclap',0,'evocation','action','self',null,0,1,0,null,'instantaneous',0,0,'Each creature in a 5-foot Emanation originating from you must succeed on a CON save or take 1d6 Thunder damage. The thunderous sound can be heard up to 100 feet away. Cantrip Upgrade: Damage increases by 1d6 when you reach levels 5 (2d6), 11 (3d6), and 17 (4d6).','d6',1,'thunder',1,2,3,4,null,'con',null,'area','emanation',5,1,1);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_thunderous_smite','Thunderous Smite',1,'evocation','bonus_action','self',null,1,0,0,null,'instantaneous',0,0,'Your strike rings with thunder audible within 300 feet. The target takes an extra 2d6 Thunder damage. If the target is a creature, it must succeed on a STR save or be pushed 10 feet away from you and have the Prone condition. Using a Higher-Level Spell Slot: Damage increases by 1d6 per slot level above 1.','d6',2,'thunder',1,null,null,null,1,'str',null,'single',null,null,0,0);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_thunderwave','Thunderwave',1,'evocation','action','self',null,1,1,0,null,'instantaneous',0,0,'A wave of thunderous energy erupts from you. Each creature in a 15-foot Cube originating from you makes a CON save: on failure, 2d8 Thunder damage and pushed 10 feet away; on success, half damage only. Unsecured objects in the Cube are also pushed 10 feet away. A thunderous boom is audible within 300 feet. Using a Higher-Level Spell Slot: Damage increases by 1d8 per slot level above 1.','d8',2,'thunder',1,null,null,null,1,'con',null,'area','cube',15,1,1);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_time_stop','Time Stop',9,'transmutation','action','self',null,1,0,0,null,'instantaneous',0,0,'You briefly stop the flow of time for everyone but yourself. No time passes for other creatures while you take 1d4 + 1 turns in a row, using actions and movement normally. The spell ends if one of your actions or any effect you create during it affects another creature or an object worn/carried by someone else, or if you move more than 1,000 feet from where you cast it.',null,null,null,0,null,null,null,null,null,null,'self',null,null,0,1);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_toll_the_dead','Toll the Dead',0,'necromancy','action','ranged',60,1,1,0,null,'instantaneous',0,0,'You point at one creature you can see within range, and a dolorous bell chimes audible within 10 feet of the target. The target must succeed on a WIS save or take 1d8 Necrotic damage. If the target is missing any Hit Points, it instead takes 1d12 Necrotic damage. Cantrip Upgrade: Damage increases by one die when you reach levels 5 (2d8 or 2d12), 11 (3d8 or 3d12), and 17 (4d8 or 4d12).','d8',1,'necrotic',1,2,3,4,null,'wis',null,'single',null,null,1,1);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_tongues','Tongues',3,'divination','action','touch',null,1,0,1,'a miniature ziggurat','1_hour',0,0,'The creature you touch gains the ability to understand any spoken or signed language it hears or sees for the duration. Moreover, when the target communicates by speaking or signing, any creature that knows at least one language can understand it if it can hear the speech or see the signing.',null,null,null,0,null,null,null,null,null,null,'single',null,null,0,1);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_transport_via_plants','Transport via Plants',6,'conjuration','action','ranged',10,1,1,0,null,'1_minute',0,0,'You create a magical link between a Large or larger inanimate plant within range and another plant at any distance on the same plane (you must have seen or touched the destination at least once). For the duration, any creature can step into the target plant and exit from the destination plant by using 5 feet of movement.',null,null,null,0,null,null,null,null,null,null,'single',null,null,0,0);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_tree_stride','Tree Stride',5,'conjuration','action','self',null,1,1,0,null,'concentration_1_minute',1,0,'You gain the ability to enter a living tree and move into another living tree of the same kind within 500 feet (both must be at least your size). Use 5 feet of movement to enter. You instantly know the location of all same-kind trees within 500 feet. As part of entering, you can pass into one of those trees or step out of the one you''re in, appearing within 5 feet of the destination (using 5 more feet of movement). Once per turn. Must end each turn outside a tree.',null,null,null,0,null,null,null,null,null,null,'self',null,null,0,0);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_true_polymorph','True Polymorph',9,'transmutation','action','ranged',30,1,1,1,'a drop of mercury, a dollop of gum arabic, and a wisp of smoke','concentration_1_hour',1,0,'Choose one creature or nonmagical object within range. An unwilling creature makes a WIS save — success means unaffected. Creature into Creature: transform into any creature with CR equal to or less than the target''s; it retains HP, Hit Dice, alignment, and personality. Creature into Object: transforms with gear into an object no larger than the creature. Object into Creature: transform into any creature of CR 9 or lower, no larger than the object; Friendly and obeys commands for 1 hour, then uncontrolled. If Concentration is maintained for the full hour, the transformation becomes permanent until dispelled.',null,null,null,0,null,null,null,null,'wis',null,'single',null,null,0,1);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_true_resurrection','True Resurrection',9,'necromancy','1_hour','touch',null,1,1,1,'diamonds worth 25,000+ GP, which the spell consumes','instantaneous',0,0,'You touch a creature dead no longer than 200 years that didn''t die of old age. The creature is revived with all its Hit Points. All wounds, poison, magical contagion, and curses are removed. Damaged or missing organs and limbs are restored. Undead are restored to their non-Undead form. If the original body no longer exists, speak the creature''s name and it appears in an unoccupied space within 10 feet of you.',null,null,null,0,null,null,null,null,null,null,'single',null,null,0,0);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_true_seeing','True Seeing',6,'divination','action','touch',null,1,1,1,'mushroom powder worth 25+ GP, which the spell consumes','1_hour',0,0,'For the duration, the willing creature you touch has Truesight with a range of 120 feet.',null,null,null,0,null,null,null,null,null,null,'single',null,null,0,1);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_true_strike','True Strike',0,'divination','action','self',null,0,1,1,'a weapon with which you have proficiency worth 1+ CP','instantaneous',0,0,'Guided by magical insight, you make one attack with the weapon used in casting. The attack uses your spellcasting ability for attack and damage rolls instead of STR or DEX. If it deals damage, it can be Radiant or the weapon''s normal type (your choice). Cantrip Upgrade: The attack deals extra Radiant damage when you reach levels 5 (1d6), 11 (2d6), and 17 (3d6).',null,null,'radiant',1,1,2,3,null,null,'melee_spell','single',null,null,1,1);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_tsunami','Tsunami',8,'conjuration','1_minute','special',5280,1,1,0,null,'concentration_6_rounds',1,0,'A wall of water (up to 300 ft long, 300 ft high, 50 ft thick) springs into existence. When it appears, each creature in its area makes a STR save: 6d10 Bludgeoning on failure, half on success. Each turn the wall moves 50 feet away; Huge-or-smaller creatures in or entered by the wall make a STR save: 5d10 Bludgeoning on failure. Damage reduces by 1d10 each round, wall height reduces by 50 feet each round. Creatures inside can swim (STR Athletics check vs. spell save DC to move at all).','d10',6,'bludgeoning',0,null,null,null,null,'str',null,'area','wall',300,0,0);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_unseen_servant','Unseen Servant',1,'conjuration','action','ranged',60,1,1,1,'a bit of string and of wood','1_hour',0,1,'This spell creates an Invisible, mindless, shapeless, Medium force that performs simple tasks at your command. It springs into existence in an unoccupied space within range. AC 10, 1 HP, STR 2, can''t attack; spell ends if it drops to 0 HP. Once per turn as a Bonus Action, command it to move up to 15 feet and interact with an object. It performs simple tasks a human could do. If commanded to move more than 60 feet from you, the spell ends.',null,null,null,0,null,null,null,null,null,null,'single',null,null,0,1);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_vampiric_touch','Vampiric Touch',3,'necromancy','action','self',null,1,1,0,null,'concentration_1_minute',1,0,'Make a melee spell attack against one creature within reach. On a hit, the target takes 3d6 Necrotic damage and you regain Hit Points equal to half the Necrotic damage dealt. Until the spell ends, you can repeat the attack on each of your turns as a Magic action, targeting the same creature or a different one. Using a Higher-Level Spell Slot: Damage increases by 1d6 per slot level above 3.','d6',3,'necrotic',1,null,null,null,1,null,'melee_spell','single',null,null,1,1);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_vicious_mockery','Vicious Mockery',0,'enchantment','action','ranged',60,1,0,0,null,'instantaneous',0,0,'You unleash a string of insults laced with subtle enchantments at one creature you can see or hear within range. The target must succeed on a WIS save or take 1d6 Psychic damage and have Disadvantage on the next attack roll it makes before the end of its next turn. Cantrip Upgrade: Damage increases by 1d6 when you reach levels 5 (2d6), 11 (3d6), and 17 (4d6).','d6',1,'psychic',1,2,3,4,null,'wis',null,'single',null,null,1,0);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_vitriolic_sphere','Vitriolic Sphere',4,'evocation','action','ranged',150,1,1,1,'a drop of bile','instantaneous',0,0,'A glowing ball of acid explodes in a 20-foot-radius Sphere at a point within range. Each creature makes a DEX save: on failure, 10d4 Acid damage and another 5d4 Acid damage at the end of its next turn; on success, half the initial damage only. Using a Higher-Level Spell Slot: Initial damage increases by 2d4 per slot level above 4.','d4',10,'acid',1,null,null,null,2,'dex',null,'area','sphere',20,1,1);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_wall_of_fire','Wall of Fire',4,'evocation','action','ranged',120,1,1,1,'a piece of charcoal','concentration_1_minute',1,0,'You create an opaque wall of fire (up to 60 ft long, 20 ft high, 1 ft thick, or ringed up to 20 ft diameter) on a solid surface within range. When it appears, each creature in its area makes a DEX save: 5d8 Fire damage on failure, half on success. One side (your choice) deals 5d8 Fire damage to each creature ending its turn within 10 feet of that side or inside the wall. Using a Higher-Level Spell Slot: Damage increases by 1d8 per slot level above 4.','d8',5,'fire',1,null,null,null,1,'dex',null,'area','wall',60,1,1);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_wall_of_force','Wall of Force',5,'evocation','action','ranged',120,1,1,1,'a shard of glass','concentration_10_minutes',1,0,'An Invisible wall of force appears at a point within range in any orientation (horizontal, vertical, angled), free floating or resting on a surface. Can be a hemispherical dome or globe (up to 10-foot radius) or up to ten contiguous 10-by-10-foot panels (1/4 inch thick). Nothing can physically pass through it. Immune to all damage; can''t be dispelled by Dispel Magic. Disintegrate destroys it instantly. Extends into the Ethereal Plane and blocks ethereal travel.',null,null,null,0,null,null,null,null,null,null,'area','wall',null,0,1);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_wall_of_ice','Wall of Ice',6,'evocation','action','ranged',120,1,1,1,'a piece of quartz','concentration_10_minutes',1,0,'You create a wall of ice (hemispherical dome or globe up to 10-foot radius, or up to ten contiguous 10-foot-square panels; 1 foot thick) on a solid surface within range. Creatures in its space are pushed to one side and make a DEX save: 10d6 Cold damage on failure, half on success. The wall (AC 12, 30 HP per 10-foot section; Immune to Cold/Poison/Psychic, Vulnerable to Fire) can be breached. Destroyed sections leave frigid air: CON save or 5d6 Cold damage when first moved through. Using a Higher-Level Spell Slot: Appearance damage +2d6, frigid air damage +1d6 per slot level above 6.','d6',10,'cold',1,null,null,null,2,'dex',null,'area','wall',null,0,1);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_wall_of_stone','Wall of Stone',5,'evocation','action','ranged',120,1,1,1,'a cube of granite','concentration_10_minutes',1,0,'A nonmagical wall of solid stone (6 inches thick, up to ten 10-by-10-foot panels, or 10-by-20-foot panels at 3 inches thick) springs into existence within range. It must merge with and be supported by existing stone. Creatures in its space are pushed aside; creatures that would be surrounded can make a DEX save to use their Reaction to move clear. The wall (AC 15, 30 HP per inch of thickness, Immune to Poison and Psychic) can be breached. If Concentration is maintained for the full duration, the wall becomes permanent.',null,null,null,0,null,null,null,null,'dex',null,'area','wall',null,0,1);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_wall_of_thorns','Wall of Thorns',6,'conjuration','action','ranged',120,1,1,1,'a handful of thorns','concentration_10_minutes',1,0,'You create a wall of tangled thorny brush (up to 60 ft long, 10 ft high, 5 ft thick, or a 20-ft-diameter circle up to 20 ft high and 5 ft thick) that blocks line of sight. When it appears, each creature in its area makes a DEX save: 7d8 Piercing damage on failure, half on success. Moving through the wall costs 4 feet per 1 foot traveled. The first time a creature enters or ends its turn in the wall, it makes a DEX save: 7d8 Slashing on failure, half on success (once per turn). Using a Higher-Level Spell Slot: Both damage types increase by 1d8 per slot level above 6.','d8',7,'piercing',1,null,null,null,1,'dex',null,'area','wall',60,0,0);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_warding_bond','Warding Bond',2,'abjuration','action','touch',null,1,1,1,'a pair of platinum rings worth 50+ GP each, which you and the target must wear for the duration','1_hour',0,0,'You touch a willing creature, creating a mystic connection. While the target is within 60 feet of you, it gains a +1 bonus to AC and saving throws and Resistance to all damage. Each time it takes damage, you take the same amount. The spell ends if you drop to 0 HP, you and the target are separated by more than 60 feet, or the spell is cast again on either connected creature.',null,null,null,0,null,null,null,null,null,null,'single',null,null,0,0);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_water_breathing','Water Breathing',3,'transmutation','action','ranged',30,1,1,1,'a short reed','24_hours',0,1,'This spell grants up to ten willing creatures of your choice within range the ability to breathe underwater until the spell ends. Affected creatures also retain their normal mode of respiration.',null,null,null,0,null,null,null,null,null,null,'multiple',null,null,0,1);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_water_walk','Water Walk',3,'transmutation','action','ranged',30,1,1,1,'a piece of cork','1_hour',0,1,'Up to ten willing creatures within range gain the ability to move across any liquid surface (water, acid, mud, snow, quicksand, or lava) as if it were harmless solid ground (lava heat damage still applies). An affected target must take a Bonus Action to pass from the surface into the liquid, but falls through automatically if it falls into the liquid.',null,null,null,0,null,null,null,null,null,null,'multiple',null,null,0,0);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_web','Web',2,'conjuration','action','ranged',60,1,1,1,'a bit of spiderweb','concentration_1_hour',1,0,'Sticky webbing fills a 20-foot Cube at a point within range. The area is Difficult Terrain and Lightly Obscured. The webs must be anchored to solid masses or a flat surface or they collapse at the start of your next turn. The first time a creature enters the webs or starts its turn there, it makes a DEX save or has the Restrained condition. A Restrained creature can use an action to make a STR (Athletics) check against your spell save DC to break free. Webs are flammable: a 5-foot Cube burns away in 1 round, dealing 2d4 Fire damage to creatures starting their turn in the fire.',null,null,null,0,null,null,null,null,'dex',null,'area','cube',20,1,1);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_weird','Weird',9,'illusion','action','ranged',120,1,1,0,null,'concentration_1_minute',1,0,'Each creature of your choice in a 30-foot-radius Sphere centered on a point within range makes a WIS save: on failure, 10d10 Psychic damage and the Frightened condition for the duration; on success, half damage only. A Frightened target makes a WIS save at the end of each of its turns: on failure, 5d10 Psychic damage; on success, the spell ends on that target.','d10',10,'psychic',0,null,null,null,null,'wis',null,'area','sphere',30,1,1);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_wind_walk','Wind Walk',6,'transmutation','1_minute','ranged',30,1,1,1,'a candle','8_hours',0,0,'You and up to ten willing creatures within range assume gaseous cloud forms for the duration. While in cloud form: Fly Speed 300 feet and can hover; Immunity to Prone; Resistance to Bludgeoning, Piercing, and Slashing damage. Only available actions: Dash or a Magic action to begin reverting (takes 1 minute; Stunned while reverting). Can revert back to cloud form with a Magic action and 1-minute transformation. If in cloud form and airborne when effect ends, descends 60 feet per round for 1 minute.',null,null,null,0,null,null,null,null,null,null,'multiple',null,null,0,0);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_wind_wall','Wind Wall',3,'evocation','action','ranged',120,1,1,1,'a fan and a feather','concentration_1_minute',1,0,'A wall of strong wind (up to 50 ft long, 15 ft high, 1 ft thick) rises from the ground along a continuous path of your choice within range. When it appears, each creature in its area makes a STR save: 4d8 Bludgeoning on failure, half on success. The wind keeps fog and gases at bay; Small or smaller flying creatures/objects can''t pass through; loose materials fly upward; arrows/bolts/similar projectiles miss automatically; boulders and siege projectiles are unaffected; gaseous creatures can''t pass through.','d8',4,'bludgeoning',0,null,null,null,null,'str',null,'area','wall',50,0,0);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_wish','Wish',9,'conjuration','action','self',null,1,0,0,null,'instantaneous',0,0,'The mightiest spell a mortal can cast. Basic use: duplicate any spell of level 8 or lower without meeting any requirements. Alternatively, choose one effect: Object Creation (object up to 25,000 GP value, not a magic item); Instant Health (up to 20 creatures regain all HP and lose Greater Restoration conditions); Resistance (up to 10 creatures gain permanent Resistance to one damage type); Spell Immunity (up to 10 creatures immune to one spell/effect for 8 hours); Sudden Learning (replace one eligible feat); Roll Redo (force a reroll of any die roll in the last round with Advantage or Disadvantage); or Reshape Reality (DM-ruled custom wish). Non-duplication uses: take 1d10 Necrotic per spell level until Long Rest, STR 3 for 2d4 days, 33% chance of never casting Wish again.',null,null,null,0,null,null,null,null,null,null,'self',null,null,1,1);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_witch_bolt','Witch Bolt',1,'evocation','action','ranged',60,1,1,1,'a twig struck by lightning','concentration_1_minute',1,0,'A beam of crackling energy forms a sustained arc of lightning to a creature within range. Make a ranged spell attack: on a hit, 2d12 Lightning damage. On each of your subsequent turns, take a Bonus Action to deal 1d12 Lightning damage automatically (even if the first attack missed). The spell ends if the target is outside the spell''s range or has Total Cover from you. Using a Higher-Level Spell Slot: Initial damage increases by 1d12 per slot level above 1.','d12',2,'lightning',1,null,null,null,1,null,'ranged_spell','single',null,null,1,1);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_word_of_radiance','Word of Radiance',0,'evocation','action','self',null,1,0,1,'a sunburst token','instantaneous',0,0,'Burning radiance erupts from you in a 5-foot Emanation. Each creature of your choice you can see in it must succeed on a CON save or take 1d6 Radiant damage. Cantrip Upgrade: Damage increases by 1d6 when you reach levels 5 (2d6), 11 (3d6), and 17 (4d6).','d6',1,'radiant',1,2,3,4,null,'con',null,'area','emanation',5,1,0);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_word_of_recall','Word of Recall',6,'conjuration','action','ranged',5,1,0,0,null,'instantaneous',0,0,'You and up to five willing creatures within 5 feet of you instantly teleport to a previously designated sanctuary, appearing in the nearest unoccupied space to the designated spot. The spell has no effect if you haven''t first designated a sanctuary by casting this spell at that location.',null,null,null,0,null,null,null,null,null,null,'multiple',null,null,0,0);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_wrathful_smite','Wrathful Smite',1,'necromancy','bonus_action','self',null,1,0,0,null,'1_minute',0,0,'The target takes an extra 1d6 Necrotic damage and must succeed on a WIS save or have the Frightened condition until the spell ends. At the end of each of its turns, the Frightened target repeats the save, ending the spell on itself on a success. Using a Higher-Level Spell Slot: Damage increases by 1d6 per slot level above 1.','d6',1,'necrotic',1,null,null,null,1,'wis',null,'single',null,null,0,0);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_yolandes_regal_presence','Yolande''s Regal Presence',5,'enchantment','action','self',null,1,1,1,'a miniature tiara','concentration_1_minute',1,0,'You surround yourself with unearthly majesty in a 10-foot Emanation. Whenever the Emanation enters a creature''s space you can see, or a creature you can see enters the Emanation or ends its turn there, you can force it to make a WIS save: on failure, 4d6 Psychic damage, Prone, and pushed up to 10 feet away; on success, half damage only. A creature makes this save only once per turn.','d6',4,'psychic',0,null,null,null,null,'wis',null,'self','emanation',10,1,1);
INSERT INTO spells (id,name,level,school,casting_time,range_type,range_feet,has_verbal,has_somatic,has_material,material_component,duration,concentration,ritual,description,damage_die,damage_die_count,damage_type,scales_with_level,cantrip_dice_5,cantrip_dice_11,cantrip_dice_17,slot_scale_dice,save_type,attack_type,target_type,area_shape,area_size_feet,has_backend_resolver,is_wizard_spell) VALUES
('spell_zone_of_truth','Zone of Truth',2,'enchantment','action','ranged',60,1,1,0,null,'10_minutes',0,0,'You create a magical zone in a 15-foot-radius Sphere centered on a point within range. A creature that enters the area for the first time on a turn or starts its turn there makes a CHA save. On a failed save, it can''t speak a deliberate lie while in the radius. You know whether each creature succeeds or fails. An affected creature is aware of the spell and can avoid answering questions but must be truthful in what it does say.',null,null,null,0,null,null,null,null,'cha',null,'area','sphere',15,0,0);
